pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A residual that is too small to hold even the smallest plausible item (size 1..=10)
    // is wasted space; the smaller it is, the worse.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }

    // Penalize residual that cannot fit the lookahead item (k=2 lookahead):
    // the gap becomes dead space for the next arrival.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 3.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward a fit that leaves a "clean" residual for the next item.
        score -= 4.0;
    }

    // Perfect fit bonus: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Make it attractive only when the current item fits poorly everywhere,
    // i.e., when post_residual here would be a large unusable remainder relative
    // to capacity, or when this is the last fitting bin and the fit is ugly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with stream progress
        // (early on, opening bins is cheap; later, waste is costly).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 30.0 * progress;

        // If many bins already fit the item, opening a new one is wasteful.
        score += fitting_bins_count as f64 * 5.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Slight tie-break toward bins whose residual is already small
    // (best-fit flavor), scaled against mean residual across bins.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps: post_residual in (0, min_item] is dead space.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size.min(20)) {
        score += 50.0;
    }
    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Reward using bins when few bins fit the item (last-chance pressure).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // over opening new ones.
    let open_pressure = open_bins_count as f64 * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 20.0 + open_pressure;
    } else {
        score -= open_pressure * 0.5;
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Lookahead: if next item could use the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += (next_item_size as f64 - post_residual as f64).abs() * 0.2;
    }

    // Slight preference to fill earlier bins as stream progresses.
    score += (step_index as f64 / total_items.max(1) as f64) * 2.0;

    // Deviation from mean residual: prefer bins tighter than average.
    score += (bin_residual as f64 - mean_residual).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward a residual that exactly matches the next item (perfect 2-step packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Reward near-perfect match of next item (small slack).
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 / (1.0 + slack);
        // Extra reward when the next item fills the bin exactly after this placement's slack.
        if post_residual - next_item_size <= 5 {
            score -= 150.0;
        }
    }
    // Penalize residuals that CANNOT fit the next item (dead space), scaled by dead space size.
    else if next_item_size > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += 50.0 + dead * 2.0;
    }

    // Penalize creating unusable tiny residual (below minimum plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Favor tighter overall fit relative to the mean residual of open bins.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Early in the stream, allow opening new bins more freely to build a good bin pool.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 30.0 * (1.0 - progress);
    }

    // Late in the stream, prefer filling existing bins aggressively.
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly favor bins whose post_residual is tiny.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // can exactly or nearly host the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 == next {
            score -= 400.0; // exact chain fit
        } else if (post_residual as f64 - next).abs() <= 3.0 {
            score -= 250.0; // near chain fit
        } else if post_residual >= next_item_size {
            // residual can host next item but not perfectly: mild reward
            score -= 0.5 * (post_residual as f64 - next);
        } else {
            // next item cannot fit in the residual: penalize dead space
            score += 0.8 * (next - post_residual as f64);
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving a residual close to the mean keeps flexibility.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the item is
    // large relative to capacity and few bins are open.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let new_bin_bonus = 300.0 * (frac - 0.5).max(0.0) * (1.0 - progress)
            - 50.0 * open_bins_count as f64;
        score += new_bin_bonus;
        // if lookahead fits perfectly into a fresh bin residual (=capacity - item)
        if next_item_size > 0 && post_residual as u32 == next_item_size {
            score -= 350.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold the
    // smallest plausible item are worthless — punish them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (small relative post residual).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 15.0;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= (10.0 - slack.min(10.0)) * 1.5;
    }
    // If next item cannot use the leftover gap, penalize slightly.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: prefer consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is near the mean (balanced packing),
    // penalize extremes unless it's a perfect fit.
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.15;

    // New-bin candidate: make empty bin mildly attractive only when the
    // item is large relative to capacity or many bins already struggle.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score = 55.0 - large_item * 30.0 + open_bins_count as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strong reward for tight placements.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Non-linear dead-space penalty: small leftovers are worse than medium ones.
        let pr = post_residual as f64;
        score += (bin_capacity as f64 / pr) * 2.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item (chained packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_quality = (post_residual - next_item_size) as f64;
        score -= 60.0 - 0.3 * chain_quality.min(100.0);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Penalize creating residual too small for the lookahead item (likely dead space).
        score += 15.0 + 0.2 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer filling existing bins.
    let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
    score -= pressure * 3.0;

    // Time horizon: early in the stream, be more willing to open new bins (score for
    // new-bin candidate relatively better); late in stream, consolidate.
    let t = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty so it only wins when open bins are bad fits.
        score = 0.5 * bin_capacity as f64 + 40.0 * (1.0 - t) - 25.0 * pressure;
        if item_size as f64 >= 0.7 * bin_capacity as f64 {
            // Large item: opening a fresh bin is often fine.
            score -= 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a bin
        }
    } else {
        // Existing bin: late-stream consolidation reward.
        score -= 20.0 * t;
    }

    // Mild preference for bins with residual close to item (best-fit sharpening).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * gap;

    score
}

