            }
        } else {
            // This bin becomes dead for the next item; penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 {
        // If this is the only bin that fits, using it avoids opening a new bin
        score -= 25.0;
        if post_residual <= 10 {
            score -= 10.0; // and it nearly fills the bin: excellent
        }
    }

    // --- New-bin candidate arbitration ---
    if bin_residual == bin_capacity {
        // Fresh bin: neutral baseline; attractive only if current bins are fragmented
        // or the item is large relative to mean residual.
        let pressure = (item_size as f64 - mean_residual).max(0.0);
        score = 45.0 - pressure * 0.6;
        if next_item_size > 0 && next_item_size > mean_residual {
            score -= 15.0; // lookahead suggests fresh capacity is valuable
        }
        if fitting_bins_count == 1 {
            score += 40.0; // don't open a new bin when a last-chance bin exists
        }
    }

    // --- Mild stream-phase adaptation: pack tighter early, exploit classes later ---
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= phase * 5.0 * (class as f64 / 10.0);

    // --- Fragmentation guard across the fleet ---
    if (mean_residual - post_residual as f64).abs() < 5.0 {
        score -= 4.0; // harmonize with fleet mean residual
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

