    };
    score += harmonic_bonus;

    // Integer-division thresholds: how many "next item" units fit in post_residual.
    if next_item_size > 0 && next_item_size <= post as u32 {
        let fits_next = post / (next_item_size as i64);
        score -= 4.0 * fits_next as f64;
        // Perfect match: post_residual exactly equals next item size.
        if post == next_item_size as i64 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this residual: penalize proportionally to waste.
        score += 3.0 * (next_item_size as f64 - post as f64).max(0.0) / 10.0;
    }

    // Capacity-fraction classes: reward residuals that are small fractions of C.
    let frac = post as f64 / cap as f64;
    if frac <= 0.1 {
        score -= 2.0; // near-full bin is excellent (little dead space)
    } else if frac <= 0.25 {
        score -= 1.0;
    } else if frac >= 0.5 {
        score += 1.5 * frac; // large residual = wasteful bin
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 5.0;
    } else if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: penalize opening a fresh bin unless residuals
    // across open bins are already very low (nothing useful left).
    if bin_residual == bin_capacity {
        let base = 12.0 + 0.15 * mean_residual;
        let progress = step_index as f64 / total_items.max(1) as f64;
