        score += 15.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of common small sizes) are more valuable.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Fraction of capacity remaining after placement.
    let frac = prf / cap;

    // Penalize awkward leftovers: residual not divisible by small harmonic
    // classes (2,4,5,10) wastes space. Count divisibility as a reward.
    let mut harmony: f64 = 0.0;
    if pr % 10 == 0 { harmony += 6.0; }
    if pr % 5 == 0 { harmony += 2.0; }
    if pr % 4 == 0 { harmony += 1.5; }
    if pr % 2 == 0 { harmony += 0.5; }
    score -= harmony;

    // Integer-division thresholds: leftover chunks of size >= 20 can still
    // hold typical items; leftover below ~15 is nearly dead space.
    if pr >= 40 {
        score -= 4.0;
    } else if pr >= 20 {
        score -= 2.0;
    } else if pr >= 10 {
        score -= 0.5;
    } else if pr > 0 {
        // dead space penalty grows for tiny unusable residue
        score += (10 - pr) as f64 * 0.4;
    }

    // Perfect fit: huge reward.
    if pr == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 12.0;
        } else if next_item_size <= pr {
            score -= 3.0 * (1.0 - (pr - next_item_size) as f64 / cap);
        } else {
            // next item won't fit here; mildly penalize leaving a mid gap
            score += 1.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0 + 0.1 * item_size as f64;
    }

    // New-bin candidate: prefer opening a fresh bin early in the stream or
    // when the fit into existing bins is poor; otherwise discourage it.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Fresh bin has post_residual == capacity; neutralize base and apply
        // a bias: cheaper to open new bin when mean residual is low and many
        // bins open (fragmentation), costlier when an existing bin fits well.
        score = cap * (1.0 - 0.05 * harmony / 10.0);
        score += 8.0 * (1.0 - progress);
        score += 0.3 * (open_bins_count as f64).sqrt() * 2.0;
        score -= mean_residual * 0.05;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 2.0;
        }
        // if only candidate, must accept
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mean-residual coupling: placing into a bin whose residual is far below
    // mean (tight bin) is good; above mean (loose bin) slightly penalized.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable gaps (too small for the smallest
    // plausible item) are heavily penalized, superlinearly.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fit, extremely desirable
    } else if post_residual <= 10 {
        score += 40.0 + 6.0 * (post_residual as f64); // small dead gap, likely wasted
    } else if post_residual <= 25 {
        score += 12.0; // moderately awkward gap
    } else {
        // larger residuals remain usable; reward proportional usable space mildly
        score -= 0.05 * (post_residual as f64 - 25.0);
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (avoid spreading); with few open bins, tolerate opening new capacity.
    let ob = open_bins_count as f64;
    score += 1.5 * ob.ln();

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin for a fittable item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // reward this placement strongly (chains well).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item still fits: mild reward scaled by tightness
        score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: an empty bin has zero dead-space risk but
    // incurs an opening cost that grows with stream progress (late new bins
    // are wasteful) and with the number of already-open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + 40.0 * progress + 2.0 * ob;
        // but if no open bin fits at all, opening is unavoidable — soften
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "straggler" bin — prioritize consuming it.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 0.3 * (mean_residual - res);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;

        // Perfect 2-step match: post_residual exactly equals next item size.
        if (post - nxt).abs() < 0.5 {
            score -= 60.0 + 40.0 * (1.0 - progress);
        }
        // Next item fits in the leftover: strong reward, scaled by tightness of fit.
        else if post >= next_item_size {
            let slack = post - nxt;
            // Prefer bins where the leftover after both placements is small.
            score -= 30.0 - (slack / 10.0).min(25.0);
        }
        // Next item does NOT fit: penalize dead space proportional to unusability.
        else {
            // Dead space = post_residual that likely becomes waste.
            score += 15.0 + 0.5 * post;
            // Extra penalty if this bin would become nearly empty of usable space.
            if post < 10 {
                score += 20.0;
            }
        }
    }

    // Relative-to-mean coupling: bins tighter than average are more valuable to fill.
    if mean_residual > 0.0 {
        let rel = (bin_residual as f64 - mean_residual) / mean_residual;
        // Filling a looser-than-average bin is cheaper; filling a tighter bin costs more.
        score += 10.0 * rel.max(-2.0).min(2.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // current item is large and no good reuse exists.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are used only when genuinely better.
        score += 35.0;
        // Large items pack better into fresh bins.
        if item_size >= 60 {
            score -= 20.0;
        }
        // Lookahead synergy: fresh bin can host both current and next item.
        if next_item_size > 0 && (item_size + next_item_size) as f64 <= bin_capacity as f64 {
            score -= 45.0;
        }
        // Late in stream, prefer consolidating into open bins.
        score += 20.0 * progress;
        // Many open bins: discourage adding more.
        score += 3.0 * open_bins_count as f64;
    }

    // Small overall nudge toward tighter fits regardless of lookahead.
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: perfect fill gets a big bonus.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Fraction of the bin wasted after placement.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += waste_frac * waste_frac * 200.0;

        // Lookahead: residual that cannot host the next item is likely dead space.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                // Residual still usable by the next item -> reward proportionally.
                score -= 0.5 * next_item_size as f64;
            } else {
                // Dead space relative to the next item -> penalize.
                score += 1.5 * post_residual as f64;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin when many open bins already exist and the item
    // is small enough to fit comfortably somewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_penalty = (open_bins_count as f64).ln().max(0.0) * 30.0;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // New bins are more acceptable early in the stream or for large items.
        score += 40.0 + open_penalty * (0.3 + 0.7 * progress) - 60.0 * item_frac;
        // If the item is small and open bins have plenty of room, discourage new bin.
        if item_frac < 0.5 && mean_residual > item_size as f64 * 1.5 {
            score += 60.0;
        }
    } else {
        // Existing bin: mild reward when its residual is below average (compact bins),
        // i.e., prefer filling the emptiest bins last / fullest bins first.
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        } else {
            score += 5.0;
        }
    }

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate loose fits less; late, be more tolerant of slack
    let progress_coupling = pr_norm * (0.6 - 1.2 * progress + 0.6 * progress * progress);
    score += 40.0 * progress_coupling;

    // Penalize large residuals that become dead space, super-linearly
    score += 8.0 * pr_norm * pr_norm * pr_norm * cap;

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            score -= 18.0 * (1.0 - gap / cap);
        } else {
            score += 5.0;
        }
    }

    // Mild penalty for proliferating bins relative to stream length
    score += (open_bins_count as f64) * (2.0 + 6.0 * progress) / (1.0 + (total_items as f64).sqrt());

    // Deviation from mean residual: prefer bins near the mean (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Slight reward for filling a large fraction of the bin
    score -= 3.0 * (item_size as f64) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the leftover space (integer division into 10-unit classes) ---
    let class = post_residual / 10;
    // Waste penalty grows super-linearly for small leftover classes (dead space)
    if class <= 2 {
        score += (3 - class) as f64 * 18.0;
    } else if class >= 5 {
        // Large usable leftover is good: reward it
        score -= (class - 4) as f64 * 6.0;
    }

    // --- Perfect fit detection via modulo arithmetic ---
    let rem = post_residual % 10;
    if rem == 0 {
        score -= 12.0; // leftover on a harmonic boundary (10,20,...) is reusable
    } else {
        score += rem as f64 * 1.5; // off-boundary leftovers fragment space
    }

    // --- Exact zero leftover: strongest reward ---
    if post_residual == 0 {
        score -= 60.0;
    }

    // --- Lookahead coupling: does leftover class fit the next item? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            // Prefer leaving a leftover that exactly accommodates the next item
            if slack % 10 == 0 || slack == 0 {
                score -= 20.0;
            } else {
                score -= 8.0;
            }
        } else {
            // This bin becomes dead for the next item; penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 {
        // If this is the only bin that fits, using it avoids opening a new bin
        score -= 25.0;
        if post_residual <= 10 {
            score -= 10.0; // and it nearly fills the bin: excellent
        }
    }

    // --- New-bin candidate arbitration ---
    if bin_residual == bin_capacity {
        // Fresh bin: neutral baseline; attractive only if current bins are fragmented
        // or the item is large relative to mean residual.
        let pressure = (item_size as f64 - mean_residual).max(0.0);
        score = 45.0 - pressure * 0.6;
        if next_item_size > 0 && next_item_size > mean_residual {
            score -= 15.0; // lookahead suggests fresh capacity is valuable
        }
        if fitting_bins_count == 1 {
            score += 40.0; // don't open a new bin when a last-chance bin exists
        }
    }

    // --- Mild stream-phase adaptation: pack tighter early, exploit classes later ---
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= phase * 5.0 * (class as f64 / 10.0);

    // --- Fragmentation guard across the fleet ---
    if (mean_residual - post_residual as f64).abs() < 5.0 {
        score -= 4.0; // harmonize with fleet mean residual
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100)
    // are pure waste. Penalize gaps below the minimum plausible item size hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 6.0; // worst at residual=1
    }

    // Small gaps that cannot fit the lookahead item are likely dead space too.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        // Only penalize if the gap is unlikely to fit any future item.
        if post_residual < 15 {
            score += 25.0;
        } else {
            score += 8.0;
        }
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // filling existing bins and avoid opening new ones unnecessarily.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and mean residual.
        score += 35.0 + pressure + mean_residual * 0.3;
        // Late in the stream, opening a new bin is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    } else {
        // Reward placing into bins with larger residuals when many bins open,
        // to consolidate space (keep big gaps for big future items).
        score -= (bin_residual as f64 / bin_capacity as f64) * pressure;
    }

    // If lookahead fits exactly in the post residual, big reward.
    if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() <= 1.0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward a residual that exactly matches the next item (perfect 2-step packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Reward near-perfect match of next item (small slack).
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 / (1.0 + slack);
        // Extra reward when the next item fills the bin exactly after this placement's slack.
        if post_residual - next_item_size <= 5 {
            score -= 150.0;
        }
    }
    // Penalize residuals that CANNOT fit the next item (dead space), scaled by dead space size.
    else if next_item_size > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += 50.0 + dead * 2.0;
    }

    // Penalize creating unusable tiny residual (below minimum plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Favor tighter overall fit relative to the mean residual of open bins.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Early in the stream, allow opening new bins more freely to build a good bin pool.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 30.0 * (1.0 - progress);
    }

    // Late in the stream, prefer filling existing bins aggressively.
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: exact or near-exact fills are excellent.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Penalize dead space that nothing can ever use (min item size ~1, but
    // small leftovers under ~10 are hard to reuse in practice).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count >= 2 {
        // Mild exploration: when many bins fit, prefer tighter ones even more.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: if the next item would fit perfectly in the
    // post-residual, reward heavily; if next item cannot fit here anyway,
    // neutral.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let slack_after_next = post_residual - next_item_size;
            if slack_after_next <= 5 {
                score -= 20.0;
            } else if slack_after_next > 50 {
                score += 8.0; // next item leaves big gap -> mild penalty
            }
        }
    }

    // Global state: when mean residual across open bins is high, we have
    // slack everywhere -> prefer filling existing bins rather than opening
    // new ones (helps the new-bin candidate lose).
    score -= 0.15 * mean_residual;

    // Time horizon: early in the stream, be more willing to open bins
    // (exploration); late in the stream, consolidate aggressively.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score += 20.0 * (1.0 - progress); // new bins look worse as stream ends

    // Too many open bins: discourage spreading further.
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate (empty bin): add a fixed opening cost so it only
    // wins when existing bins are genuinely bad fits.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * item_size as f64;
    }

    // Prefer placing large items into large-residual bins; small items
    // should go into small-residual bins (best-fit-like shaping).
    let size_ratio = item_size as f64 / bin_capacity as f64;
    let residual_ratio = bin_residual as f64 / bin_capacity as f64;
    score += 10.0 * (residual_ratio - size_ratio).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling with stream progress:
    // early on, dead space is tolerable; late, it is costly.
    let progress_coupling = 30.0 * progress * progress * norm_pr
        + 15.0 * progress * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += progress_coupling;

    // Last chance bin: strong reward (subtract) if it fits, scaled smoothly
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Penalize bins far from mean residual (prefer homogeneity), smooth quadratic
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Lookahead: reward leaving room for the next item (smooth interaction)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let slack = (pr - ns) / cap;
            score -= 8.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 6.0 * (ns - pr) / cap;
        }
    }

    // Mild penalty for opening a brand-new bin when alternatives exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 12.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 classes capture typical
    // "friendly" sizes for future items (multiples of 5/10 pack well).
    let post = post_residual;
    let cap = bin_capacity;
    let fill = (cap - post) as f64 / cap as f64; // fraction of bin filled

    // Reward tight fits: small post_residual heavily favored non-linearly.
    if post > 0 {
        score -= (cap as f64 / post as f64) * 2.0;
    } else {
        score -= 60.0; // perfect closure
    }

    // Dead-space penalty: residuals in awkward classes (1..9) are hard to fill.
    if post > 0 && post < 10 {
        score += 15.0;
    }

    // Modulo-10 harmonic bonus: residual divisible by 10 is reusable.
    if post % 10 == 0 && post > 0 {
        score -= 8.0;
    }
    // Half/quarter capacity classes are also friendly.
    if post == cap / 2 || post == cap / 4 || post == (3 * cap) / 4 {
        score -= 5.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward; if next item cannot fit, penalize mildly.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 20.0;
        } else if next_item_size <= post {
            score -= (post as f64 - next_item_size as f64) * 0.15;
            if (post - next_item_size) % 10 == 0 {
                score -= 4.0;
            }
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: opening a bin should only win when this bin would
    // be left with an awkward tiny residual while fill is poor.
    if bin_residual == cap {
        // base cost of a fresh bin
        score = cap as f64;
        // open new bin if current item is large and would leave bad residual
        // in existing bins; cheaper if item is small (pack it somewhere).
        let awkward = (post > 0 && post < 10) || (post > 40 && post < 50 && next_item_size > post);
        if !awkward {
            score += 10.0;
        }
        // late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
        // many open bins with high mean residual: new bin is fine
        if mean_residual > cap as f64 * 0.4 && open_bins_count > 2 {
            score -= 6.0;
        }
    }

    // Encourage higher fill fraction generally.
    score -= fill * 10.0;

    // Mild penalty for spreading across many bins when mean residual is low.
    if (mean_residual < 15.0) && post > 0 && open_bins_count > 1 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Penalize unusable small dead space: gaps below the minimum item size (1)
    // are worthless; gaps that no typical item (>= 10) can use are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 60.0;
    }

    // Reward leaving gaps that could still fit future items of meaningful size.
    if post_residual >= 20 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly or well,
    // favor this bin (chained packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 15.0; // next item won't fit here; mild penalty
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure scaled by open bins.
        score += 80.0 + 10.0 * open_bins_count as f64;
        // Exception: if current item is small relative to mean residual and no
        // tight fit exists, opening may still win via other terms.
        if item_size as f64 > mean_residual {
            score -= 60.0;
        }
    } else {
        // Mild reward for using existing bins as pressure rises.
        score -= 2.0 * open_bins_count as f64;
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 50.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Reward when next item fits tightly after current placement (small gap remains).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + gap);
    }

    // Penalize placements that leave dead space the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Discourage opening a new bin when a decent fit exists in an open bin.
    if bin_residual == bin_capacity {
        score += 10.0;
        if next_item_size > 0 && item_size >= 50 {
            score += 5.0; // big items: prefer compacting into open bins
        }
    }

    // Prefer bins with residual below mean residual (tighter packing candidates).
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Late in the stream, be more aggressive about closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good, but perfect fits are extra good)
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 15 {
        score -= 4.0;
    } else {
        // Penalize large dead space, scaled by how much of the bin is wasted
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += waste_frac * 20.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // When many bins fit, mild preference for fullest bins (best-fit behavior)
        score -= (bin_residual as f64 / bin_capacity as f64) * 6.0;
    }

    // Lookahead: if next item could exactly fill post_residual, reward heavily
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits after this placement: good chaining
            score -= 6.0;
            // extra reward if next item leaves another perfect fit
            if post_residual - next_item_size <= 5 {
                score -= 5.0;
            }
        } else {
            // next item would NOT fit here: penalize leaving dead space that
            // is smaller than the next item (unusable sliver)
            let sliver = post_residual as f64;
            if sliver < next_item_size as f64 && sliver > 0.0 {
                score += (next_item_size as f64 - sliver).min(20.0);
            }
        }
    }

    // Global state coupling: when many bins are open with high mean residual,
    // prefer packing into existing bins rather than fragmenting
    let mean_coupling = mean_residual / bin_capacity as f64;
    if open_bins_count > 3 {
        score -= mean_coupling * 8.0;
    }

    // Time horizon: early in stream, be more willing to open new bins
    // (explore); late in stream, consolidate aggressively
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    // New-bin candidate has bin_residual == bin_capacity (post_residual == capacity here)
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more so later in the stream
        let open_penalty = 10.0 + 30.0 * progress;
        score += open_penalty;
        // But if current item is huge and would leave a tiny sliver in any bin,
        // opening fresh may be fine: soften penalty for large items early
        if item_size >= 70 && progress < 0.5 {
            score -= 8.0;
        }
    }

    // Late-stream consolidation: extra reward for filling bins nearly full
    if progress > 0.7 {
        let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= fill * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;                       // normalized residual after placement
    let progress = step_index as f64 / total_items.max(1) as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: prefer tight fits (low post residual), with quadratic sharpening
    let mut score = post * (1.0 + 0.9 * norm_post * norm_post);

    // Smooth stream-progress coupling: later in the stream, dead space matters more
    let progress_coupling = 1.0 + 0.8 * progress * (1.0 - progress) * 4.0 * norm_post;
    score *= progress_coupling;

    // Reward if the next item can fit into the post residual (smooth lookahead term)
    let lookahead_fit = (next - post).max(0.0) / cap;
    score += 12.0 * (1.0 - lookahead_fit) * (norm_post / (1.0 + norm_post)) * (next > 0.0) as i32 as f64;

    // Penalize last-chance bins slightly less when fit is tight (avoid opening new bin)
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - norm_post);
    }

    // Mild penalty when this bin's residual deviates strongly from mean residual (balance pressure)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev * (1.0 - progress);

    // Discard-fraction shaping: reward filling bins fully near end of stream
    score -= 4.0 * progress * (item / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue modulo small divisors
    // captures "how well the leftover decomposes" into typical item sizes.
    let r = post_residual;
    let c = bin_capacity;

    // Reward residuals that fall into "friendly" classes (multiples of 10/20/25),
    // since future items (10..80) can pack into them with low waste.
    let class10 = r % 10;
    let class20 = r % 20;
    let class25 = r % 25;
    if class10 == 0 {
        score -= 6.0;
    } else if class20 == 0 {
        score -= 5.0;
    } else if class25 == 0 {
        score -= 4.0;
    } else {
        // Penalize awkward residues proportional to distance from nearest class-10 point.
        let dist = (class10.min(10 - class10)) as f64;
        score += dist * 0.8;
    }

    // Integer-division thresholds: residual quotient classes vs capacity.
    let q = r / (c / 4); // quarter-class of the residual (0..=4)
    match q {
        0 => score += 3.0,          // tiny leftover: near-dead space
        1 => score -= 1.0,          // quarter-full leftover: useful
        2 => score -= 2.0,          // half leftover: very useful
        3 => score -= 1.5,          // three-quarter leftover
        _ => score += 0.0,          // still nearly full
    }

    // Coupling with the next item's harmonic class: if the next item exactly
    // divides into this bin's post residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= r {
        if r % next_item_size == 0 {
            score -= 8.0;
        } else {
            let slack = (r - next_item_size) as f64;
            score += slack * 0.05; // mild penalty for leftover after next fit
        }
    } else if next_item_size > r {
        // Next item cannot use this bin's leftover; penalize hoarding space.
        score += 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < c {
        score -= 12.0;
    }

    // New-bin candidate: make it attractive only when open bins are crowded
    // or the fit here would create bad residue.
    if bin_residual == c {
        // Base cost of opening a new bin.
        score = c as f64 * 0.9;
        // Attractive early in the stream or when few bins are open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
        score -= (open_bins_count.max(1) as f64).recip() * 5.0;
        // If mean residual is large, prefer reusing open bins.
        score += mean_residual * 0.15;
    }

    // Small global noise-free regularizer tied to stream position.
    score += (step_index as f64).sqrt() * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny dead gap: heavily penalize
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits (post_residual very small relative to item).
    if post_residual == 0 {
        score -= 60.0;
    } else if (post_residual as f64) < 0.15 * (item_size as f64) {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it attractive only when item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score -= 10.0;
        score += 0.5 * mean_residual; // if existing bins are roomy, opening new is worse
    }

    // Lookahead coupling: if next item could use the leftover gap, soften penalty.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 10.0; // gap is truly dead for the next item
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect two-step chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving large unusable gaps
            let gap = (next_item_size - post_residual) as f64;
            if post_residual < 10 {
                score += 15.0; // tiny dead space is fine
            } else {
                score += 0.3 * gap;
            }
        }
    }

    // Tight fit reward relative to mean residual of open bins.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    if tightness < mean_residual / bin_capacity as f64 {
        score -= 8.0; // tighter than average: good
    } else {
        score += 4.0 * (tightness - mean_residual / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize wasting a nearly-empty bin's flexibility unless it's a new bin candidate.
    if bin_residual == bin_capacity {
        // New bin: attractive only if current item is large or no good fits exist.
        if item_size >= 50 || fitting_bins_count == 0 {
            score -= 10.0;
        } else {
            score += 25.0;
        }
    }

    // Late in stream: consolidate, prefer filling existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

    // Penalize dead space that becomes unusable for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable slivers
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bins unattractive unless the fit
    // is poor everywhere or the item nearly fills a fresh bin.
    if bin_residual == bin_capacity {
        score += 25.0; // default penalty for opening a new bin
        if item_size >= 80 {
            score -= 40.0; // large items are fine in a fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // Lookahead: if the next item would fit perfectly in the post-residual,
    // reward this placement strongly.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 35.0;
        } else if next_item_size as u32 <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty for leaving large gaps
            score += 0.05 * post_residual as f64;
        }
    }

    // Global state coupling: many open bins with high mean residual ->
    // prefer consolidating into existing bins (penalize new bins implicitly
    // by rewarding tight fits more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64);
    score -= 3.0 * consolidation * (0.5 + progress);

    // Mild preference early on to keep bins balanced; late stream, be greedy.
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: non-linear polynomial in normalized post residual.
    let x = pr / cap; // in [0, 1]
    let mut score = x * x * (3.0 - 2.0 * x) + 0.5 * x * x * x; // smoothstep + cubic tail: penalize large dead space super-linearly

    // Stream-progress coupling: later in stream, dead space matters more (fewer chances to fill).
    score += 2.5 * progress * x * x;

    // Reward tight fits: interaction of item_size with residual.
    let fill = item_size as f64 / cap;
    score -= 1.2 * fill * (1.0 - x);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * progress;
    }

    // Many open bins: prefer consolidation, penalize spreading.
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * x;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = (pr - nxt) / cap;
            score -= 2.0 * (1.0 - gap) * (1.0 - progress * 0.5);
        } else {
            score += 0.8 * (nxt - pr) / cap;
        }
    }

    // Mean residual context: if this bin's residual deviates from mean, slight penalty for outliers (fragmentation).
    let dev = (pr - mean_residual) / cap;
    score += 0.4 * dev * dev;

    // New-bin candidate (empty bin): post_residual = capacity => x = 1, already heavily penalized;
    // add a mild fixed bias so new bins are chosen only when truly better.
    if bin_residual == bin_capacity {
        score += 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 measure "waste class".
    let residue = post_residual % 10;
    let harmonic_penalty: f64 = match residue {
        0 => -8.0,                       // perfectly divisible space -> ideal
        1 | 2 | 3 => 6.0,                // nearly-full slivers -> dead space
        4 | 5 | 6 => 0.0,
        7 | 8 | 9 => 3.0,
        _ => 0.0,
    };
    score += harmonic_penalty;

    // Integer-division threshold: small post_residual classes are bad (waste),
    // but exact zero is excellent (perfect fill).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score += 10.0; // unusable sliver
    }

    // Capacity fraction coupling: favor bins whose fill ratio lands on
    // "harmonic" fractions (1/4, 1/2, 3/4 of capacity).
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    let frac = fill * 4.0;
    if (frac - frac.round()).abs() < 0.05 {
        score -= 5.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this space; penalize proportionally
            score += (next_item_size - post_residual).min(30) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 12.0;
        if post_residual < 5 {
            score -= 8.0;
        }
    }

    // New-bin candidate: make it mildly attractive only when mean residual
    // across open bins is small (all bins nearly full) or many bins open.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score = 40.0 + 60.0 * pressure;
        if open_bins_count == 0 {
            score = -100.0; // must open first bin
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 && mean_residual < 15.0 {
            score -= 20.0; // open fresh bin when existing ones are nearly full
        }
    }

    // Stream progression: early on, be conservative about wasting space;
    // later, tolerate slivers slightly more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any plausible
    // future item are pure waste; penalize them super-linearly.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Reward tight fits (small post_residual) with a mild quadratic discount.
    score -= (100.0 - post_residual as f64).powi(2) * 0.004;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead space is worse late in the stream when fewer chances remain to fill it.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (dead_threshold - post_residual as f64).max(0.0) * progress * 2.0;

    // Open-bin pressure: with many open bins, prefer consolidating into this
    // bin rather than spreading; penalize opening new bins.
    score += open_bins_count as f64 * 1.5;
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 2.0;
    }

    // Last-chance bin: strongly favor using it before it becomes dead space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, this
    // placement leaves a useful gap — reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item cannot use the leftover, small leftovers are extra harmful.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Prefer bins whose residual is already below average (filling fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: post_residual exactly equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Reward near-matches: next item fits snugly into post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / 50.0).max(0.0);
    }
    // Penalize dead space: post_residual too small for the next item (unusable gap).
    if next_item_size > 0 && next_item_size > post_residual {
        let gap = (next_item_size - post_residual) as f64;
        score += 12.0 * (gap / 40.0).min(1.5);
    }

    // Penalize large post_residual relative to mean residual (wasteful spread).
    score += 0.35 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mild penalty for opening a new bin when decent fits exist.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.05 * open_bins_count as f64;
    }

    // Prefer tighter residual fits overall (non-linear coupling).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space, normalized.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining
        } else if next_item_size <= post_residual {
            score -= 25.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use the leftover; penalize leaving large dead space.
            score += 10.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly reward using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = if fitting_bins_count > 0 {
            (bin_capacity as f64 - item_size as f64) / bin_capacity as f64
        } else {
            1.0
        };
        // New bin cost grows with open bins count and shrinks late in the stream.
        score += 20.0 + 6.0 * (open_bins_count as f64).ln().max(0.0)
            - 15.0 * progress
            - 20.0 * fit_quality;
        // If no open bin fits, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Prefer bins below mean residual (they are "tighter"); avoid fragmenting loose bins.
    let delta = mean_residual - bin_residual as f64;
    score += 0.15 * delta;

    // Slight preference for filling larger items into bins with less residual overall.
    score += 0.05 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;
    let nxt = next_item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - t) * (1.0 - t);
    score -= 40.0 * poly;

    // Reward tight fits more strongly as stream progresses
    score -= fit * fit * (0.5 + t) * 10.0;

    // Penalize post_residual that cannot host the lookahead item
    if next_item_size > 0 {
        let gap = (pr - nxt).max(0.0) / cap;
        if pr < nxt {
            score += 15.0 * (nxt - norm_pr) * (1.0 + t);
        } else {
            score -= 12.0 * gap * gap * (1.0 - t);
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - norm_pr) * (0.5 + t);
    }

    // Mild penalty for spreading across many open bins relative to mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual - pr).abs() / cap;

    // Smooth penalty on very small residual dead space, growing with progress
    score += t * (norm_pr * (1.0 - norm_pr)) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class decomposition of post_residual ---
    // Residuals are grouped into capacity-fraction classes: [0,10), [10,25), [25,50), [50,100].
    // Small residuals are "good" (tight fit); mid residuals are dead zones.
    let pr = post_residual;
    if pr == 0 {
        // Perfect closure: heavily reward.
        score -= 60.0;
    } else if pr < 10 {
        // Unusable sliver: reward the near-closure but penalize waste class.
        score -= 45.0 - (pr as f64) * 1.5;
    } else if pr < 25 {
        // Moderately usable.
        score -= 12.0;
    } else if pr < 50 {
        // Half-bin dead zone: mildly penalize.
        score += 8.0;
    } else {
        // Large residual: keep base (already large) plus small penalty.
        score += 5.0;
    }

    // --- Modulo arithmetic on post_residual vs typical small items ---
    // If post_residual is congruent to a small-item-friendly class (divisible by 10),
    // future items of size 10..80 are more likely to tile it exactly.
    if pr > 0 && pr % 10 == 0 {
        score -= 6.0;
    } else if pr % 10 >= 7 {
        // Residual just below a multiple of 10 is awkward for decimal-grid items.
        score += 4.0;
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item can also fit here: strong reward for chaining.
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 + 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit after this placement: mild penalty.
            score += 6.0;
        }
        // Harmonic pair: item_size + next_item_size near capacity multiples
        let pair = item_size + next_item_size;
        if pair % 100 == 0 {
            score -= 10.0;
        }
    }

    // --- Last-chance bin pressure ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This is the only bin that fits; strongly discourage opening a new bin.
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin: base cost so it's chosen only when open bins fit poorly.
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open.
        }
        // If item is small relative to capacity, opening wastes potential.
        if (item_size as f64) < 0.4 * bin_capacity as f64 && fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // --- Stream progression: late in the stream, close bins aggressively ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - pr as f64 / bin_capacity as f64);

    // --- Mean residual coupling: prefer bins below mean residual (more packed) ---
    score += 0.3 * (post_residual as f64 - mean_residual);

    // --- Crowding: with many open bins, favor tightening existing ones ---
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count.min(20) as f64) * (1.0 - pr as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps that are too small for typical future items are "dead space".
    // Penalize post_residual heavily when it falls in an unusable band.
    let pr = post_residual;
    if pr > 0 {
        // Dead-space severity: small gaps (1..=9) are nearly useless.
        if pr < 10 {
            score += 40.0 * (1.0 - pr as f64 / 10.0);
        }
        // Medium gaps (10..=19) usable only by small items; partial penalty.
        else if pr < 20 {
            score += 12.0;
        }
        // Perfect fit gets a strong reward.
        if pr == 0 {
            score -= 60.0;
        }
    } else {
        score -= 60.0; // exact fill
    }

    // Reward tight fits relative to bin residual (waste ratio shaping).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // --- Open bins pressure ---
    // Discourage opening new bins when others can fit.
    if bin_residual == bin_capacity {
        // New-bin candidate: strong penalty scaled by number of fitting bins.
        if fitting_bins_count > 0 {
            score += 30.0 + 8.0 * fitting_bins_count as f64;
        } else {
            score -= 5.0; // no alternative: new bin is fine
        }
        // Late in the stream, prefer reusing existing bins even more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    } else {
        // Reward using existing bins, more so when many are open.
        score -= 3.0 * open_bins_count as f64 * 0.1;
    }

    // --- Lookahead coupling ---
    // If the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // post_residual can't host next item: mild penalty for stranding.
            score += 6.0;
        }
    }

    // Prefer bins whose residual is below the mean (compact the fullest bins).
    score += 0.15 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Last-chance bin: if this is the only fitting bin, strongly favor it
    // over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: does the next item fit into the leftover space?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Excellent: chain placement possible.
            score -= 60.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else if next_item_size > 0 && post_residual > 0 && post_residual < 10 {
            // Tiny dead space the next item can't use — mild penalty already via post_residual.
            score += 5.0;
        }
        // If next item almost fits (within 10), slightly discourage wasting the slot.
        let gap = next_item_size as f64 - post_residual as f64;
        if gap > 0.0 && gap <= 10.0 {
            score += 8.0;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual is near the mean
    // (keeps a balanced portfolio), avoid draining already-small bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: strongly prefer using it rather than leaving it stranded.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let baseline = mean_residual.max(0.0);
        // Open a new bin if the best existing option would leave large dead space.
        score = 55.0 + baseline * 0.2;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 20.0; // existing bins chaining look better; keep new bin expensive
        }
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a bin
        }
    }

    // Late-stream consolidation: favor filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.85 {
        score -= 30.0 * fit_ratio;
    } else if fit_ratio > 0.6 {
        score -= 12.0 * fit_ratio;
    }

    // Penalize small post-residuals that are too small to be useful later
    // (dead space), but reward exact/zero residual heavily.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score += 8.0; // awkward sliver
    } else if post_residual >= 10 && post_residual <= 30 {
        score -= 5.0; // still usable for typical small items
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let next_fit = next_item_size as f64 / post_residual as f64;
            if next_fit > 0.8 {
                score -= 15.0 * next_fit;
            }
        } else {
            // post-residual too small for next item: mild penalty for wasted space
            score += 4.0;
        }
    }

    // New-bin candidate handling: only attractive when this bin is the last chance
    // and the fit is poor, or when global residuals are very fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 25.0;

        // If very few bins can fit this item and the stream is early/mid,
        // opening fresh may be fine.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }

        // If mean residual across open bins is small (bins nearly full),
        // a new bin is natural.
        if mean_residual < item_size as f64 {
            score -= 30.0;
        }

        // Late in the stream, prefer reusing; penalize new bins more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;

        // If next item is large, a fresh bin with full capacity is valuable.
        if next_item_size > 60 {
            score -= 15.0;
        }
    } else {
        // Reusing an existing bin: reward keeping bin count down.
        score -= 3.0;

        // Last-chance bin: strongly prefer using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }

        // Reward keeping mean residual balanced: avoid dumping into the
        // emptiest bin when others are fuller (keeps larger residuals usable).
        let bin_residual_f = bin_residual as f64;
        if bin_residual_f > mean_residual * 1.5 && open_bins_count > 2 {
            score += 6.0;
        }
    }

    // Global pressure: many open bins -> favor consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Stream-progress coupling: late in the stream, waste is more costly
    let late = progress * progress;
    score += 8.0 * late * norm_pr * norm_pr * cap;

    // Penalize leaving dead space that no plausible next item can use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 12.0 * (nxt - pr) * (0.5 + progress);
        } else {
            // reward bins whose residual is close to the next item size
            let gap = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - (gap * 4.0).min(1.0)) * (1.0 - progress);
        }
    } else {
        // last item: strongly prefer tightest fit
        score -= 5.0 * (cap - pr);
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: mild penalty that grows with open bins and progress
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * (open_bins_count as f64).ln().max(0.0) + 20.0 * progress;
    } else {
        // reward using bins that are already relatively full
        let fullness = (bin_residual as f64) / cap;
        score -= 4.0 * fullness * fullness;
    }

    // Mean-residual coupling: if this bin's residual is far below mean, it's scarce space
    let bin_res = bin_residual as f64;
    let scarcity = ((mean_residual - bin_res) / cap).max(0.0);
    score += 5.0 * scarcity * scarcity * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual modulo 10: small residuals (0..9 class)
    // are more likely to be filled by future items; large dead space is penalized.
    let class = post_residual % 10;
    score += (class as f64) * 0.8;

    // Integer-division thresholds: residual blocks of 20 (capacity fractions).
    let block = post_residual / 20; // 0..=5
    score += block as f64 * 6.0;

    // Coupling: if the next item fits exactly into the post residual, strong reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 400.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Reward proportionally to how well the next item fills the leftover.
        let fill = next_item_size as f64 / post_residual as f64;
        score -= 50.0 * fill;
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize dead space more.
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: baseline penalty so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Opening a bin is more attractive when few bins are open or mean residual is high.
        score -= (open_bins_count as f64).sqrt() * 2.0;
        score += (mean_residual / bin_capacity as f64) * 10.0;
    }

    // Stream progression: late in the stream, prefer closing bins tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // Small tie-breaker favoring fuller bins.
    score -= (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are worthless.
    let min_item = 1u32;
    let dead = (post_residual < min_item) as f64;
    score += dead * 1000.0;

    // Non-linear penalty for small-but-nonzero gaps (hard to reuse later).
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 8.0;
    }

    // Reward tight fits strongly (best-fit flavor with superlinear tightness bonus).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 25.0;

    // Last-chance pressure: strongly favor the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; opening new bins is costly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += pressure * 0.5;

    // Mean residual coupling: prefer bins below mean residual (tighter bins) when many bins are open.
    if open_bins_count > 1 {
        score += (mean_residual - post_residual as f64) * 0.3;
    }

    // Lookahead: if next item fits perfectly into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        score -= (leftover as f64).min(20.0) * 1.5;
    }

    // New-bin candidate: keep it attractive early (amortize over long stream), less so late.
    if bin_residual == bin_capacity {
        score -= 30.0 * (1.0 - progress) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item exactly fits the post residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // next item fits too: mild reward proportional to compactness
            score -= 50.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit: penalize dead space creation
            score += 0.5 * post_residual as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.8 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize so we only open when open bins are poor fits
    if bin_residual == bin_capacity {
        score += 120.0 + 0.3 * item_size as f64;
        // if the item is huge relative to capacity, opening a fresh bin is fine
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 100.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward placements that leave room for the lookahead item (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (post_residual - next_item_size) as f64 * 0.05;
    } else if next_item_size > 0 {
        // Penalize leaving a gap just below the next item size (dead space).
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when it enables a tight pairing
    // with the lookahead item (item + next ≈ capacity) or bins are fragmented.
    if bin_residual == bin_capacity {
        score += 25.0; // base penalty: prefer reusing open bins
        if next_item_size > 0 {
            let pair = item_size + next_item_size;
            if pair <= bin_capacity {
                let tightness = (bin_capacity - pair) as f64;
                score -= (30.0 - tightness.min(30.0)) * 1.2;
            }
        }
        // Early in the stream, opening bins is cheaper; later, avoid sprawl.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        score += open_bins_count as f64 * 1.5;
    }

    // Penalize large leftover relative to mean residual (fragmentation).
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Slight preference for filling larger residual bins (best-fit flavor).
    score -= bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: strong preference for small post_residual, with smooth polynomial sharpening.
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: tighten packing more aggressively as stream advances.
    score *= 1.0 + 0.5 * progress * norm_pr;

    // Reward bins whose residual is being consumed efficiently relative to mean residual.
    let mean_ratio = if mean_residual > 0.0 { pr / mean_residual } else { 1.0 };
    score -= 0.3 * (1.0 - mean_ratio.min(2.0)) * (1.0 - progress);

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among multiple fitting bins, mild penalty scaled by competition to spread usage.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if next item fits smoothly into this post_residual, reward; else penalize dead space.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / cap);
    } else if next_item_size > post_residual {
        // Smooth penalty for residual that next item cannot use, weighted by size of dead space.
        score += 4.0 * norm_pr * (1.0 + progress);
    }

    // New-bin candidate: penalize opening a new bin, but less when few bins fit the item
    // or late in the stream where consolidation matters less.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        let new_bin_penalty = 30.0 * (1.0 - 0.6 * scarcity) * (1.0 - 0.3 * progress);
        score += new_bin_penalty;
    }

    // Mild penalty for proliferating open bins early in stream.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual divisible by common item
    // sizes (10, 20, 25, 50) is more "reusable" — reward it.
    if post_residual > 0 {
        let pr = post_residual;
        let mut reusability = 0.0;
        if pr % 50 == 0 { reusability += 12.0; }
        else if pr % 25 == 0 { reusability += 8.0; }
        else if pr % 20 == 0 { reusability += 7.0; }
        else if pr % 10 == 0 { reusability += 5.0; }
        if pr % 5 == 0 { reusability += 2.0; }
        score -= reusability;

        // Dead space penalty: residual below the minimum plausible item
        // (say < 10) is nearly unusable — penalize quadratically.
        if pr < 10 {
            score += (10 - pr) as f64 * (10 - pr) as f64 * 0.5;
        } else if pr < 20 {
            score += (20 - pr) as f64 * 0.8;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (chained perfect fits).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            // Prefer chains that leave another harmonically clean residual.
            if leftover % 10 == 0 { score -= 8.0; }
            if leftover < 5 { score += 4.0; }
        }
        // If next item cannot fit here anyway, mild penalty for wasting
        // a large residual on a small item.
        if next_item_size > post_residual && post_residual > 30 {
            score += 3.0;
        }
    }

    // Integer-division thresholds on bin_residual fraction of capacity.
    let q = bin_residual / 25; // 0..4 quarter classes
    match q {
        0 => score += 2.0,   // nearly full bin, fine
        1 => score -= 1.0,   // 25..49 residual
        2 => score -= 2.0,   // 50..74 residual, good targets
        _ => score -= 0.5,
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item
    // is large relative to capacity or stream is early and mean residual
    // is already small (poor fits everywhere).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 25.0 + progress * 20.0;
        if item_size > 50 { new_bin_score -= 10.0; }
        if mean_residual < item_size as f64 * 0.5 && open_bins_count > 0 {
            new_bin_score -= 12.0;
        }
        if open_bins_count == 0 { new_bin_score = -100.0; }
        score += new_bin_score;
    }

    // Mild pressure to consolidate when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1..10)
    // are nearly worthless; penalize them heavily.
    if post_residual >= 1 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Small gap: value depends on whether next item can use it
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0; // gap is usable by lookahead
        } else {
            score += 25.0;
        }
    } else {
        // Large gap: reward proportional usability by lookahead item
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Reward tight fits (small waste relative to item size)
    let tightness = item_size as f64 / (item_size as f64 + post_residual as f64);
    score -= 40.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidation;
    // but if few bins open, new bin is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + 20.0 * (1.0 - progress));
    score += pressure * (mean_residual / bin_capacity as f64).max(0.0) * 10.0;

    // New-bin candidate: baseline cost, modulated by how bad existing fits are
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * open_bins_count as f64;
        // If current item would leave a dead gap in any open bin, opening new bin is fine
        if post_residual == 0 {
            score -= 20.0; // perfect fit in fresh bin keeps things clean
        }
    } else {
        // Perfect closure of an existing bin is excellent
        if post_residual == 0 {
            score -= 50.0;
        }
        // If bin residual exactly matches next item, reserve it
        if next_item_size > 0 && next_item_size == bin_residual {
            score += 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0; // perfect two-item fill
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover after hypothetically fitting the next item
            score += slack * 0.8;
        } else {
            let gap = (next_item_size - post_residual) as f64;
            // post_residual too small for next item: dead space penalty, softer
            score += gap * 0.3;
        }
        // mild bonus if next item still fits comfortably alongside
        if next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Classic best-fit flavor: tighter post residual preferred.
    score -= (bin_capacity - post_residual) as f64 * 0.1;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize bins far from the mean residual (avoid wasting large residuals).
    let dev = post_residual as f64 - mean_residual;
    score += dev.abs() * 0.25;

    // New-bin candidate: only attractive when current residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual.max(0.0);
        // opening a new bin costs; make it unattractive unless open bins are nearly full
        score += 60.0 + avg_waste * 0.5;
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits nonlinearly
    score -= (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 12.0;

    // Penalize dead space that is too small to be useful later
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits in the post residual, reward; otherwise penalize
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Among multiple fitting bins, prefer fuller ones
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // New-bin candidate: penalize opening new bins, more so early and when mean residual is large
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.5 + (1.0 - progress) * 10.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Late in the stream, prefer closing out bins (use remaining space aggressively)
    score -= progress * (bin_capacity as f64 - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: minimize waste, with smooth polynomial shrink of large residuals over time
    let mut score = pr * (1.0 + 0.35 * t * (1.0 - x));

    // Non-linear coupling: penalize mid-range residuals more as stream progresses
    score += 12.0 * t * x * (1.0 - x) * 4.0;

    // Tight fits rewarded (small post residual), stronger early
    score -= (1.0 - t) * (cap - pr) * 0.05;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * (1.0 - t);
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - (next_item_size as f64) / cap);
    }

    // Slight preference for bins with below-mean residual (keeps big bins for big items)
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // Mild penalty for many open bins to encourage consolidation
    score += 0.5 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "reusable" residue class (multiples of 10 / 25) are more valuable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: best possible outcome
    } else {
        let class = pr % 10;
        match class {
            0 => score -= 18.0,          // decadal leftover stays reusable
            5 => score -= 8.0,           // half-decadal, still decent
            _ => score += (10 - class) as f64 * 1.2, // ragged leftover penalized
        }
        // Dead-space cliff: tiny unusable slivers are worse than medium gaps.
        if pr < 10 {
            score += 25.0;
        } else if pr <= 20 {
            score -= 6.0;
        } else if pr <= 35 {
            score -= 3.0;
        } else {
            score += 4.0; // large leftovers = wasted capacity
        }
    }

    // Integer-division coupling with the lookahead item: if the leftover can
    // exactly host the next item, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if pr >= next_item_size {
            score -= (pr - next_item_size) as f64 * 0.4;
        } else {
            score += (next_item_size - pr) as f64 * 0.6;
        }
        // Harmonic fraction: leftover divisible by next item's size class
        if next_item_size > 0 && pr % next_item_size.max(1) == 0 && pr > 0 {
            score -= 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish baseline, slightly above a good fit but
    // below a wasteful placement into a nearly-empty open bin.
    if bin_residual == bin_capacity {
        score = 40.0 + (mean_residual / 10.0).min(15.0);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Stream progression: late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins below mean residual (denser bins first).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Mild load balancing across many open bins.
    if open_bins_count > 10 {
        score += 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are unusably small are heavily penalized.
    // A residual gap is "dead" if it cannot hold the smallest plausible item (1..=10).
    let dead_threshold: u32 = 10;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Penalize wasting a large bin on a small item (large post_residual relative to capacity).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_ratio * waste_ratio;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // rather than opening new ones.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        if leftover == 0 {
            score -= 45.0;
        } else if leftover <= 10 {
            score -= 15.0;
        }
    }
    // If next item would be blocked by this placement's residual, mild penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Mean-residual coupling: if this bin is tighter than average, prefer it.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: empty bin should only win when it genuinely helps.
    if bin_residual == bin_capacity {
        // Default: discourage opening new bins when existing bins fit decently.
        score += 20.0 + open_bins_count as f64 * 3.0;
        // But if nothing else fits well (item nearly fills a bin), allow new bin.
        if item_size as f64 >= 0.85 * bin_capacity as f64 {
            score -= 70.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 500.0;
    }

    // 2-step lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after = (post_residual - next_item_size) as f64;
            score -= 60.0 + slack_after * 0.5;
            if slack_after == 0.0 {
                score -= 400.0; // perfect chain: item then next item fills bin
            }
        } else {
            // next item won't fit here; penalize large unusable leftovers
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 80.0; // tiny dead space is wasted capacity
            } else {
                score += dead * 0.3;
            }
        }
    } else {
        // last item: minimize leftover strongly
        score += post_residual as f64 * 2.0;
    }

    // Relative to mean residual: bins tighter than average are better targets
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin bonus: only bin that fits -> avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: only attractive if nothing fits well anywhere
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual < next_item_size && post_residual < 10);
        if poor_fit {
            score -= 200.0;
        } else {
            score += 250.0; // discourage opening new bins when fits exist
        }
    }

    // Late in stream: consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits (small post_residual) matter much more
    let late = progress * progress;
    score += pr * late * 3.0;
    score -= 20.0 * late * (1.0 - norm_pr);

    // Penalize dead space that is too small to be useful (smooth sigmoid-like term)
    let useless = (norm_pr * 4.0 - 0.4).max(0.0);
    score += 15.0 * useless * useless;

    // Reward using the last fitting bin (avoid opening a new bin)
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: bonus if next item can fit into post_residual
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 10.0 + 8.0 * (1.0 - norm_pr);
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 1.5 * norm_pr;

    // New-bin candidate handling: neutral-ish baseline, better late if current bins are fragmented
    if bin_residual == bin_capacity {
        score = 60.0 + 40.0 * (1.0 - progress) - 15.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "useful"
    // residue classes (divisible by 10, 20, 25, 50) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fit
    } else {
        let mut bonus = 0.0;
        if pr % 50 == 0 { bonus += 12.0; }
        else if pr % 25 == 0 { bonus += 8.0; }
        else if pr % 20 == 0 { bonus += 6.0; }
        else if pr % 10 == 0 { bonus += 4.0; }
        // small residuals are dead space unless zero
        if pr < 10 { bonus -= 15.0; }
        score -= bonus;

        // Dead-space penalty: residual that no plausible item (1..=80) can use well
        if pr > 80 { score -= 2.0; } // almost any item fits, fine
        else if pr < 10 { score += 6.0; }

        // Harmonic pairing: does post_residual combine with next item?
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 20.0; // exact pairing lookahead
            } else if pr >= next_item_size && (pr - next_item_size) % 10 == 0 {
                score -= 5.0; // harmonic chain
            } else if pr < next_item_size {
                score += 4.0; // next item won't fit here
            }
        }
    }

    // Fraction of capacity used by this placement
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_frac;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when open bins are fragmented or fit is terrible
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // penalize new bins mildly; worse when many bins already open and fragmented low
        score += 14.0 + 6.0 * (1.0 - fragmentation) - 8.0 * progress;
        if item_size > 60 && fragmentation > 0.5 {
            score -= 10.0; // big item deserves fresh bin when existing space is fragmented
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 4.0; // fresh bin can host current + next item
        }
    }

    // Prefer tighter bins overall (closest fit wins via post_residual already)
    score += 0.05 * (bin_residual as f64 - post_residual as f64) * 0.0; // no-op keep signature clean

    // Mild penalty scaling with open bins count to encourage consolidation
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space disproportionately.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += (10.0 - dead) * 8.0;
    }
    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += pressure * 2.0;

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
        } else if next_item_size > bin_residual {
            // next item needs a new bin anyway; keep current bin flexible
            score += (post_residual as f64) * 0.1;
        }
    }

    // Prefer bins with residual close to mean (avoid fragmenting outliers).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item -> huge reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits in the post residual: reward proportional to fit tightness
    else if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = (post_residual - next_item_size) as f64;
        score -= 300.0 - tightness.min(300.0);
    }
    // Next item does NOT fit: dead space penalty scaled by wasted amount
    else if next_item_size > 0 {
        let waste = (next_item_size - post_residual) as f64;
        score += waste * 1.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 500.0;
    }

    // Penalize bins far below mean residual (fragmented bins)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // New empty bin candidate: make it attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score += 400.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 150.0;
        }
        // More open bins -> slightly prefer reusing existing bins
        score += open_bins_count as f64 * 5.0;
    }

    // Late in the stream: tighten packing, prefer tightest fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio (dynamic time horizon)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Strong preference for tight fits (best-fit core)
        score += (post_residual as f64).powi(2) / bin_capacity as f64;
    }

    // Lookahead: reward bins whose residual can host the next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            score -= 60.0 * (post_residual as f64 / (next_item_size as f64 + 1.0)).ln().max(0.0);
        } else {
            // next item can't use leftover: penalize wasted space more
            score += 25.0 + 0.3 * post_residual as f64;
        }
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0 + 0.5 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate handling: prefer opening a fresh bin only when
    // existing residuals are fragmented or mean residual is small
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 90.0;
        // early in stream, opening bins is cheap (build diversity)
        score -= 120.0 * (1.0 - progress);
        // if mean residual is large and item fits poorly, opening is attractive
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        if fit_quality > 0.5 {
            score -= 80.0 * fit_quality;
        }
        // many open bins with low mean residual -> consolidation is better
        if mean_residual > item_size as f64 {
            score += 40.0;
        }
        // few open bins -> prefer opening to keep options
        if open_bins_count < 3 {
            score -= 70.0;
        }
    } else {
        // Using an existing bin reduces open-bin count pressure; reward it
        score -= 10.0;
        // penalize placing into bins with residual much larger than needed
        // (waste) when many alternatives exist
        if fitting_bins_count > 3 && post_residual > 40 {
            score += 0.4 * (post_residual - 40) as f64;
        }
    }

    // Late-stream tightening: as stream ends, squeeze every bin
    score -= 50.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty for spreading across many bins when mean residual is high
    score += 0.02 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 0.5 * (1.0 - (std::f64::consts::PI * t).cos());
    score += poly * (pr * pr / cap) * 0.05;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - pr / cap;
    score -= tightness * tightness * (1.0 + t) * 3.0;

    // Penalize dead space relative to mean residual, smoothly scaled by progress
    let dead = (pr - mean_residual).max(0.0);
    score += dead * (0.02 + 0.06 * t * t);

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * t;
    }

    // Lookahead: favor leaving room for the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = (pr - ni) / cap;
            score -= (1.0 - slack * slack) * 2.0 * (1.0 - t);
        } else {
            score += ((ni - pr) / cap) * 5.0;
        }
    }

    // Mild penalty for spreading across many bins, growing with progress
    score += (open_bins_count as f64).ln() * (0.5 + 1.5 * t);

    // Prefer filling near-full bins; smooth cubic coupling
    let fill = 1.0 - pr / cap;
    score -= fill * fill * fill * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 and coarse capacity fractions.
    let r = post_residual % 10;
    let q = post_residual / 10;

    // Penalize "dead" residuals that no typical item can use.
    let dead = |x: u32| -> f64 {
        let m = x % 10;
        if x == 0 { 0.0 }
        else if m >= 1 && m <= 3 { 4.0 }   // tiny unusable slivers
        else if m >= 7 && m <= 9 { 1.0 }   // near-round, likely fillable
        else { 2.0 }
    };
    score += dead(post_residual);

    // Reward tight fits (small post_residual) super-linearly.
    if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 10 {
        score -= 6.0;
    }

    // Harmonic coupling: if next item exactly matches post_residual, huge reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Reward residuals that leave room for the next item.
        let slack = post_residual - next_item_size;
        score -= (slack as f64).min(10.0) * 0.5;
        score += dead(post_residual - next_item_size) * 0.5;
    } else if next_item_size > post_residual {
        // Next item won't fit here; slight penalty proportional to overflow.
        score += ((next_item_size - post_residual) as f64) * 0.15;
    }

    // Integer-division thresholds on post_residual (capacity fractions).
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.5 {
        score += 3.0; // bin more than half empty -> low priority
    } else if frac < 0.1 {
        score -= 2.0; // nearly full bin, finish it
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // New-bin candidate: only prefer when open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Bias against opening new bins early; allow it when residuals are dead-heavy.
        score = 100.0 + fragmentation * 20.0 - progress * 5.0;
        if post_residual == 0 { score -= 5.0; }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05 * (q as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose residual can still host the next item after this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize if this placement kills the chance for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage spreading when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize by open-bin pressure and progress.
        score += 15.0 + 2.0 * pressure + 10.0 * progress;
        // But a new bin is fine if the item fits poorly everywhere (few fitting bins).
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    } else {
        // Slight reward for packing into already-open bins.
        score -= 1.0 + 0.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins tighter than the mean residual (good fits).
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: post_residual == next_item_size
    // (item now + next item perfectly fill the bin).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // next item fits after current one: reward proportionally to closeness
            score -= 40.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item would not fit: penalize dead space relative to mean residual
            score += (post_residual as f64 / bin_capacity as f64) * 25.0;
        }
        // extra penalty if post_residual is small but nonzero (unusable sliver)
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins tighter than average (better packing density).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Mild bonus for using existing bins vs opening new ones early in stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more when many open bins / early stream
        score += 8.0 + 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits (small post-residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 30.0;

    // Penalize opening a new bin unless existing bins fit poorly
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0;
        // If this bin is the only fitting option elsewhere, opening new bin is fine
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // Late in stream, prefer reusing bins
        let t = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - t) * 10.0;
    }

    // Last-chance bin: strong reward to use it and avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly into post-residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // leaving room for next item is good
            score -= (next_item_size as f64).min(20.0) * 0.5;
        } else {
            // next item can't fit here; slight penalty for wasting space
            score += (next_item_size as f64 - post_residual as f64) * 0.2;
        }
    }

    // Prefer bins below mean residual (consolidating space)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Reward filling bins nearly full regardless
    if post_residual < 10 {
        score -= 12.0;
    }

    // Mild penalty for many open bins (encourage closing out bins)
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: non-linear polynomial in post_residual (quadratic + cubic waste term)
    let pn = post / cap;
    let mut score = post * (1.0 + 0.9 * pn + 0.6 * pn * pn);

    // Tight fit reward: smooth bell around small post_residual
    score -= 18.0 * (-post * post / 90.0).exp();

    // Exact-fill bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: penalize residual that next item cannot use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            // next item fits here -> reward keeping useful residual
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // dead space for lookahead -> smooth penalty
            score += 8.0 * (1.0 - nxt / post.max(1.0)) * pn;
        }
    }

    // Last-chance bin: strong reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Stream progress: later in stream, prefer compacting into existing bins
    score -= 10.0 * progress * (item / cap);

    // Mean residual coupling: bins deviating from mean residual get smoothed preference
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: penalize opening a new bin unless existing fits are poor
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (1.0 - progress);
        // allow new bin if item is large relative to capacity
        score -= 25.0 * (item / cap);
    }

    // Slight preference for fuller bins among many open bins
    score -= 3.0 * (1.0 - bin_residual as f64 / cap) / (open_bins_count as f64 + 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space?
    // Class the residual into capacity fractions (eighths) — leftover in the
    // lowest eighth is dead space, leftover in high classes is reusable.
    let eighth = bin_capacity / 8;
    let class = (post_residual / eighth.max(1)) as f64;

    // Reward residuals that sit in "harmonic" classes matching common item sizes
    // (multiples of 10 up to 80): leftover exactly divisible by 10 is a perfect
    // slot for a future item.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0 + class * 1.5;
    } else {
        score += 4.0;
    }

    // Penalize tiny dead space (unusable leftovers) more than mid-range leftovers
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, strongly favor
    let progress = step_index as f64 / total_items.max(1) as f64;
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves another residue: evaluate that chain
            let chain = post_residual - next_item_size;
            score -= 15.0 - (chain as f64) * 0.2;
            if chain % 10 == 0 { score -= 6.0; }
        } else {
            // next item won't fit: this bin may become dead; penalize if residual small
            if post_residual < 20 { score += 12.0; }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 * (1.0 - progress * 0.3);
    }

    // New-bin candidate handling: empty bin gets a neutral baseline that competes
    // with poorly fitting open bins but loses to good fits.
    if bin_residual == bin_capacity {
        // baseline: prefer new bin when open bins are fragmented (high mean residual spread)
        score = 55.0 + mean_residual * 0.35 - (open_bins_count as f64) * 0.8;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 8.0;
        }
        return score;
    }

    // Tight-fit reward: fraction of bin used by this item
    let fill_ratio = item_size as f64 / cap;
    score -= fill_ratio * 20.0;

    // Prefer bins whose residual deviates favorably from the mean (consolidating space)
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized,
    // since typical item sizes (>=10) can never fill them.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 30.0;

    // Open-bin pressure: penalize placements that keep many bins open,
    // encouraging consolidation into fewer bins.
    score += open_bins_count as f64 * 3.0;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it's a "close-to-full" bin; finishing it is good.
    let res_gap = mean_residual - bin_residual as f64;
    score += res_gap * 0.5;

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    }
    // Penalize leaving a residual that is just barely too small for the next item
    // (dead space from the lookahead's perspective).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 20 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well. Penalize new-bin slightly so consolidation wins
    // unless dead space elsewhere is severe.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 2.0;
        // But if the item is large, a fresh bin is natural (large items leave
        // little residual anywhere).
        if item_size >= 60 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item's size (perfect two-item packing).
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nr).abs();
        // Strong reward when the next item exactly fills the leftover space.
        if diff == 0.0 {
            score -= 60.0 + pr * 0.5;
        } else if pr >= nr {
            // Next item fits too: reward proportional to how much slack remains
            // after both items (smaller final slack is better).
            let double_residual = pr - nr;
            score -= 25.0 - double_residual.min(50.0) * 0.3;
        } else {
            // Next item won't fit here: penalize wasted potential.
            score += diff * 0.4;
        }
    }

    // Penalize creating tiny unusable dead space (1..10 units).
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // Prefer bins with residuals below the mean (tighter bins close out faster).
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Slight preference for keeping few open bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer filling larger fraction of the bin now.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream completed.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of the fit: reward near-perfect packing strongly.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness * tightness;

    // Penalize large dead space, especially small residuals that waste capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers are bad
    } else {
        score += 0.05 * post_residual as f64;
    }

    // Lookahead coupling: if the next item fits into the post-residual, reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // Extra reward if next item fills it almost exactly.
            let gap = post_residual as f64 - next_item_size as f64;
            score -= 4.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize slightly if we leave big residual.
            score += 2.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer consolidating.
    let pressure = mean_residual * (open_bins_count as f64).ln1p();
    if bin_residual as f64 > mean_residual {
        score -= 0.3 * pressure * 0.1;
    } else {
        score += 0.3 * pressure * 0.1;
    }

    // Time horizon: early in the stream, be picky (penalize mediocre fits);
    // late in the stream, accept placements more readily to avoid bin sprawl.
    let pickiness = 1.0 - t;
    score += pickiness * 4.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: only attractive when no open bin is a decent fit
    // or when global residual fragmentation is high.
    if bin_residual == bin_capacity && item_size > 0 {
        let fragmentation = if open_bins_count > 0 { mean_residual / (bin_capacity as f64 * 0.5) } else { 1.0 };
        let decent_fit_exists = fitting_bins_count > 0 && mean_residual >= item_size as f64 * 1.5;
        if decent_fit_exists && fragmentation < 1.2 {
            score += 25.0; // discourage opening new bins when reuse is fine
        } else {
            score -= 5.0 + 3.0 * fragmentation; // open fresh bin to reorganize
        }
    }

    // Mild preference for bins with larger residuals when fitting many bins exist
    // (keeps small residual bins for small future items).
    if fitting_bins_count > 2 {
        score += 0.02 * (bin_capacity as f64 - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling of post_residual with progress
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Polynomial interaction: tight fits (small post_residual) get extra reward,
    // amplified as the stream progresses (bins become scarcer to reuse well).
    let tightness = (1.0 - pr_norm).powi(3); // high when post_residual small
    score -= 18.0 * tightness * (0.5 + progress);

    // Penalize large dead space with a convex term, stronger early in the stream
    score += 6.0 * pr_norm * pr_norm * (1.5 - progress);

    // Reward exact/near-exact fills smoothly
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead coupling: if next item fits the post_residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            let fit_quality = 1.0 - (slack / cap);
            score -= 12.0 * fit_quality * fit_quality;
        } else {
            // Next item won't fit here; mild penalty scaled by how much it misses
            let miss = (nxt - pr) / cap;
            score += 8.0 * miss * miss;
        }
    }

    // Crowd penalty: with many open bins, prefer consolidating into fewer bins
    let crowd = (open_bins_count as f64) / (1.0 + open_bins_count as f64);
    score += 4.0 * crowd * pr_norm;

    // Mean-residual coupling: bins deviating from mean residual get a smooth nudge
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod common divisors.
    let r = post_residual;
    let class10 = (r % 10) as f64;
    let class5 = (r % 5) as f64;
    let class20 = (r % 20) as f64;

    // Reward residuals that are "harmonic" (divisible by 10 or 5): likely reusable.
    if r % 10 == 0 {
        score -= 8.0;
    } else if r % 5 == 0 {
        score -= 4.0;
    } else {
        score += class10 * 0.4; // penalize awkward remainders
    }

    // Dead-space thresholds: residuals too small to fit typical items are worthless.
    if r < 10 {
        score += 25.0;
    } else if r < 20 {
        score += 10.0;
    }

    // Integer-division class: r / 20 bucket — prefer fuller bins.
    let depth_class = r / 20;
    score -= depth_class as f64 * 3.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == r {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= r {
        // Harmonic check: does next item leave another divisible residual?
        let r2 = r - next_item_size;
        if r2 % 10 == 0 {
            score -= 12.0;
        } else if r2 % 5 == 0 {
            score -= 6.0;
        }
        score += (r2 % 10) as f64 * 0.3;
    } else if next_item_size > r && next_item_size > 0 {
        // Next item can't use this residual: penalize hoarding space.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize so we only open when open bins look bad.
    if bin_residual == bin_capacity {
        score += 35.0 + mean_residual * 0.2;
        // But early in the stream or when mean residual is tight, opening is fine.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 20.0;
        if mean_residual < 15.0 {
            score -= 25.0;
        }
    }

    // Congestion: many open bins -> prefer packing into existing ones.
    if open_bins_count > 4 {
        score -= (open_bins_count as f64).ln() * 2.0;
    }

    // Fractional capacity coupling: item size classes mod 25.
    let item_class = (item_size % 25) as f64;
    score += item_class * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps hard.
    // A post_residual that is too small for the smallest plausible item is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Small gap: risky, mildly penalize relative to a clean fill
        score += 8.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Exact match for the next item is ideal
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use this gap: penalize proportionally to wasted potential
        let waste_ratio = (post_residual as f64) / (bin_capacity as f64);
        score += waste_ratio * 10.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: with many open bins, discourage spreading into new space
    // unless the fit is tight; encourage consolidation.
    let ob = open_bins_count as f64;
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score += ob * 1.5 * (1.0 - tightness);

    // Mean residual coupling: prefer bins below the mean residual (tighter bins),
    // pushing item into bins that are already mostly full.
    let dev = (bin_residual as f64) - mean_residual;
    score += dev * 0.15;

    // New-bin candidate: only attractive when current fit is terrible
    if bin_residual == bin_capacity {
        // Baseline neutral score; penalize more when many bins are open (avoid proliferation)
        score = (bin_capacity as f64) * 0.5 + ob * 2.0;
        if post_residual >= 0 && item_size <= bin_capacity {
            // allow new bin if this would leave a large dead gap in existing bins
            // handled by comparisons; give slight edge when stream is early
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score -= progress * 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly (or nearly) matches the next item's size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for the next item: strong reward.
        if diff == 0.0 {
            score -= 25.0 + 0.5 * item_size as f64;
        } else {
            // Proximity reward: closer post_residual to next item is better.
            let proximity = 10.0 / (1.0 + diff / 8.0);
            // Only reward if the next item actually fits this residual.
            if post_residual >= next_item_size {
                score -= proximity;
            } else {
                // Next item cannot fit: penalize wasted residual proportionally.
                score += 3.0 + diff / 20.0;
            }
        }
        // Bonus if this placement enables a perfect two-item chain fill.
        if post_residual == next_item_size && next_item_size >= 10 {
            score -= 5.0;
        }
    } else {
        // Last item: strongly prefer minimal leftover.
        score += 2.0 * post_residual as f64 / bin_capacity as f64;
    }

    // Relative-to-mean-residual coupling: prefer bins that are tighter
    // than average (small residual), penalize bins much looser than mean.
    if mean_residual > 0.0 {
        let ratio = post_residual as f64 / mean_residual;
        if ratio < 0.5 {
            score -= 4.0 * (1.0 - ratio);
        } else if ratio > 1.5 {
            score += 3.0 * (ratio - 1.5);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 6.0;
        if post_residual as f64 > 0.4 * bin_capacity as f64 {
            score += 8.0; // poor fit in the only bin -> maybe open new bin
        }
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    // or all fits would leave big dead space.
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size >= 50 {
            score -= 10.0;
        }
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 30.0; // fresh bin perfectly chains with next item
        }
    }

    // Slight stream-progression pressure: later in stream, prefer tighter
    // packing (consolidate).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits: reward small post-residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize leaving dead space that can't fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 15.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        } else if post_residual >= next_item_size {
            // Reward bins that can still host the lookahead item.
            score -= 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: penalize opening a new bin unless the item
    // fits poorly everywhere else or the stream is young with many bins.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Early in the stream, allow new bins more freely.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If the item is large relative to capacity, a fresh bin is attractive.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
        // If many bins are open and mean residual is high, prefer existing bins.
        score += 0.5 * open_bins_count as f64;
        score += 10.0 * (mean_residual / bin_capacity as f64).min(1.0);
    }

    // Mild preference for bins with residuals close to the mean (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 2.0 * (dev / bin_capacity as f64);

    // Slight bias toward fuller bins as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let prn = pr / bin_capacity as f64;

    // Reward tight fits: subtract a bonus that grows as post_residual shrinks,
    // modulated by a smooth non-linear function of stream progress.
    let tightness = (1.0 - prn).powi(3);
    let progress_coupling = 0.5 + 0.5 * (progress * std::f64::consts::PI).sin();
    score -= 12.0 * tightness * progress_coupling;

    // Non-linear polynomial coupling of post_residual with progress:
    // mid-stream, prefer bins whose residual matches item-size scale;
    // penalize large wasted residuals quadratically late in the stream.
    let waste = prn * prn;
    score += waste * (6.0 + 14.0 * progress * progress);

    // Penalize leaving residuals that are too small to be useful (dead space),
    // unless the bin is the last fitting option.
    let dead = if pr > 0.0 && pr < 10.0 { (10.0 - pr) / 10.0 } else { 0.0 };
    score += dead * dead * 8.0 * (1.0 - progress);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Lookahead: reward residuals that can host the next item smoothly.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let fit_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score += 0.05 * gap - 4.0 * fit_next * (1.0 - progress);
    }

    // New-bin candidate: mildly penalize opening bins when many are open,
    // but relax late in the stream via smooth term.
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * (open_bins_count as f64).ln1p() * (1.0 - progress);
    }

    // Mild alignment with mean residual across open bins.
    score += 0.02 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into residue classes
    // modulo 10 (typical item granularity) and modulo 25 (quarter-capacity classes).
    let post = post_residual;
    let class10 = post % 10;            // fine-grained harmonic class
    let class25 = post % 25;            // coarse harmonic class
    let div25 = post / 25;              // integer division tier

    // Reward post-residuals that lie in "harmonic" classes likely to be exactly
    // filled by future items (multiples of 10 and 25 are natural fill targets).
    if class10 == 0 {
        score -= 6.0;
    } else if class10 <= 3 {
        score += 2.0 + 2.0 * class10 as f64; // small unusable slivers are penalized
    }
    if class25 == 0 {
        score -= 4.0;
    } else if class25 <= 5 {
        score += 1.5;
    }

    // Tier penalty: each quarter-capacity tier of wasted space costs a bit more
    // than linear (encourage tight fits beyond raw post_residual).
    score += 0.8 * div25 as f64 * (div25 as f64).max(1.0);

    // Lookahead coupling: does next_item_size harmonize with post_residual?
    if next_item_size > 0 {
        let nxt = next_item_size.min(bin_capacity);
        if nxt <= post {
            // Reward if next item's class matches the residual class (exact-fill potential)
            let compat = (post % 10) == (nxt % 10);
            let compat25 = (post % 25) == (nxt % 25);
            let mut reward = 3.0;
            if compat { reward += 3.0; }
            if compat25 { reward += 2.0; }
            // Extra reward when the next item nearly exactly fills the residual
            let gap = post - nxt;
            if gap <= 5 { reward += 4.0; }
            score -= reward;
        } else {
            // Next item cannot fit here: penalize residuals that are just barely
            // too small (dead space), scaled by how close it is.
            let miss = nxt - post;
            if miss <= 10 {
                score += 3.0 + 0.5 * miss as f64;
            }
        }
    } else {
        // Last item: prefer the bin that ends with the least waste overall.
        score += 0.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has post_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is discouraged unless current open bins are crowded
        // or the item is large relative to remaining residuals.
        let crowded = open_bins_count == 0
            || mean_residual < item_size as f64 * 0.5;
        let big_item = (item_size as f64) > 0.7 * bin_capacity as f64;
        if crowded || big_item {
            score -= 5.0;
        } else {
            score += 8.0;
        }
        // Harmonic nudge: items whose size is a multiple of 10 pack cleanly
        // into a fresh bin's harmonic structure.
        if item_size % 10 == 0 {
            score -= 2.0;
        }
    }

    // Stream progression: late in the stream, be greedier about filling existing
    // bins (less chance to amortize newly opened bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    // Mild tie-breaker toward fewer open bins to consolidate.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=12) are heavily penalized.
    if post_residual >= 1 && post_residual <= 12 {
        score += 60.0 - (post_residual as f64) * 3.0;
    } else if post_residual > 12 && post_residual <= 25 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 20.0;

    // Pressure from number of open bins: discourage spreading across many bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }
    // If next item cannot use the leftover space, penalize slightly.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate handling: prefer new bin only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened by stream progress and open-bin pressure.
        score = 55.0 + (open_bins_count as f64) * 2.0 - (step_index as f64 / total_items.max(1) as f64) * 10.0;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= 60 {
            score -= 20.0;
        }
    }

    // Mild alignment with mean residual: bins far from mean residual are slightly penalized.
    score += ((post_residual as f64) - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer placements whose post_residual exactly matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.8;
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain: next item fills this bin exactly
        }
        // Penalize leaving dead space the next item cannot use.
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 1.2;
        }
    } else {
        // Last item: prefer tightest fit overall.
        score += post_residual as f64 * 0.5;
    }

    // Prefer small post_residual (tight fit) nonlinearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Reward using bins with residual close to mean (balance), penalize outliers.
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // Last-chance bin: strong incentive to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New empty bin candidate: penalize unless nothing else fits well.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in stream, opening bins is cheaper; later, discourage it more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // If next item is large, a fresh bin may be worth it.
        if next_item_size > 50 {
            score -= 15.0;
        }
    }

    // Mild reward for keeping open bin count from exploding.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward near-perfect packing by discounting small post_residuals
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tight) * (1.0 - tight) * 8.0;

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 + 4.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            // Next item won't fit here; penalize leaving large unusable gaps
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last chance bin: strongly favor using the only bin that can fit this item
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize bins far from the mean residual (avoid fragmenting the pool unevenly)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Late in the stream, prefer filling existing bins rather than opening new ones
    if bin_residual == bin_capacity {
        // Candidate for a brand-new bin: penalize more as stream progresses
        // and when several bins are already open with usable space
        score += 10.0 + 30.0 * progress + (open_bins_count as f64) * 2.0;
        // But early on, a new bin is cheap and keeps options open
        if progress < 0.2 && open_bins_count < 3 {
            score -= 12.0;
        }
    } else {
        // Reward using existing bins more heavily later in the stream
        score -= 5.0 * progress;
    }

    // Slight preference for bins with smaller residual among fitting bins (best-fit flavor)
    score += (bin_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let fill = 1.0 - pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr * pr / (cap * cap); // normalized quadratic dead-space term
    let mut score = pr * (1.0 + 0.8 * poly) - 40.0 * fill * fill * (0.5 + 0.5 * t);

    // Tight fit reward, stronger late in the stream
    let tight = 1.0 - (pr / cap).powi(3);
    score -= 25.0 * tight * (0.3 + 0.7 * t);

    // Lookahead: reward residual that matches next item size
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let match_term = 1.0 - ((pr - nx).abs() / cap);
        score -= 15.0 * match_term * match_term;
        // penalize residual too small for next item if it's wasted
        if pr < nx {
            score += 8.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 0 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Mean residual pressure: prefer bins deviating below mean late in stream
    score += 0.3 * (pr - mean_residual) * (1.0 - t);

    // New-bin candidate: keep it competitive only when open bins have poor fits
    if bin_residual == bin_capacity {
        let pressure = (fitting_bins_count == 0) as i32 as f64;
        score = 60.0 - 70.0 * pressure + 10.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1 fraction of wasted capacity

    // Integer-division thresholds on post_residual: classify leftover space
    // Small leftovers (<15) are nearly perfect fits -> reward strongly.
    if post_residual < 15 {
        score -= 30.0;
    } else if post_residual < 30 {
        score -= 10.0;
    } else if post_residual > 70 {
        // Large leftover: still very usable, mildly reward
        score -= 5.0;
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of common
    // item sizes (10,20,25,50) are reusable by future harmonic classes.
    let harmonic_bonus = if post_residual % 10 == 0 {
        8.0
    } else if post_residual % 25 == 0 {
        6.0
    } else if post_residual % 5 == 0 {
        3.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Next-item coupling: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits: leftover after that pair
            let double_left = post_residual - next_item_size;
            score -= 12.0 - (double_left as f64) * 0.1;
        } else {
            // next item won't fit here: penalize bins that will strand residual
            score += (next_item_size - post_residual) as f64 * 0.08;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        // Base penalty to prefer existing bins; reduced when open bins have low mean residual
        let crowding = mean_residual / cap; // high = bins are full
        score += 45.0 - 30.0 * crowding.min(1.0);
        // Late in the stream, opening fresh bins is fine (no need to hoard)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // If item is large and next item is large, a fresh bin pairs them well
        if item_size >= 50 && next_item_size >= 40 {
            score -= 15.0;
        }
    }

    // Mild penalty for spreading too thin across many open bins
    if open_bins_count > 8 {
        score += 0.5 * ((open_bins_count - 8) as f64).min(6.0);
    }

    // Coupling with mean residual: prefer bins below mean residual (fuller bins)
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Fine-grained non-linear waste term on capacity fraction
    score += 10.0 * frac * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 12] are unusable for
    // future items (min item size 1, but tiny gaps rarely match) -> heavy penalty.
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 * (13.0 - post_residual as f64) / 13.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward good tight fits (small waste relative to capacity).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 25.0 * (1.0 - waste_ratio);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Pressure from many open bins: discourage spreading, prefer consolidation.
    score += 2.0 * open_bins_count as f64;

    // If this bin is looser than average, mild penalty (prefer fuller bins).
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 40.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover: penalize proportional dead space.
        score += 8.0;
    }

    // New empty bin candidate: only attractive when no open bin fits well
    // (many fitting bins means consolidation is better; keep new bin costly).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 50.0;
        } else {
            score += 35.0 + 10.0 * fitting_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly favor bins whose post_residual is tiny.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // can exactly or nearly host the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 == next {
            score -= 400.0; // exact chain fit
        } else if (post_residual as f64 - next).abs() <= 3.0 {
            score -= 250.0; // near chain fit
        } else if post_residual >= next_item_size {
            // residual can host next item but not perfectly: mild reward
            score -= 0.5 * (post_residual as f64 - next);
        } else {
            // next item cannot fit in the residual: penalize dead space
            score += 0.8 * (next - post_residual as f64);
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving a residual close to the mean keeps flexibility.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the item is
    // large relative to capacity and few bins are open.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let new_bin_bonus = 300.0 * (frac - 0.5).max(0.0) * (1.0 - progress)
            - 50.0 * open_bins_count as f64;
        score += new_bin_bonus;
        // if lookahead fits perfectly into a fresh bin residual (=capacity - item)
        if next_item_size > 0 && post_residual as u32 == next_item_size {
            score -= 350.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit pull: reward tight fits nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize small dead space only if a future item could use it (lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0; // this bin stays useful for the next item
        } else {
            score += 4.0; // dead space the next item can't use
        }
        // If next item exactly fills remaining space, heavily favor this bin.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is expensive when many bins
    // are already open or mean residual is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_penalty = 8.0 * (open_bins_count as f64).sqrt();
        let residual_pull = 0.35 * mean_residual;
        // Late in the stream, be more willing to open fresh bins (fewer future
        // items to consolidate), so discount the penalty slightly.
        score += 20.0 + open_penalty + residual_pull - 6.0 * progress;
        // Don't open a new bin when plenty of bins fit the item.
        if fitting_bins_count > 2 {
            score += 15.0;
        }
        // Opening a bin is attractive if the item is large and would leave
        // awkward space in any existing bin.
        if item_size > bin_capacity / 2 && post_residual == 0 {
            score -= 25.0;
        }
    }

    // Mild preference for bins with smaller residuals (denser bins first).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Slight consolidation pressure: favor bins when many are open.
    score -= 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;

    // Tightness: quadratic reward for small post_residual, amplified by stream progress
    let tightness = 1.0 - (post / cap);
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Perfect fill reward (non-linear)
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Penalize dead space that is too small to ever be useful: smooth coupling
        let min_useful = 1.0f64.max(next_item_size as f64);
        let waste = (min_useful - post).max(0.0) / cap;
        score += 18.0 * waste * waste * (1.0 + progress);
    }

    // Lookahead coupling: reward if next item fits the post residual (smooth sigmoid-like)
    if next_item_size > 0 {
        let fits_next = (post - next_item_size as f64) / cap;
        let s = 1.0 / (1.0 + (-fits_next * 20.0).exp());
        score -= 10.0 * s * (0.6 + 0.4 * progress);
    }

    // Last-chance bin: strong reward to use the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + progress);
    }

    // New-bin candidate handling: penalize opening a new bin unless it enables a great fit
    if bin_residual == bin_capacity {
        let load_ratio = item / cap;
        // prefer opening new bins early, or for large items; penalize late/small items
        score += 8.0 * (1.0 - load_ratio) * (0.3 + progress);
        score -= 6.0 * load_ratio * load_ratio;
        // if many bins already open, discourage further opening mildly
        score += 0.4 * open_bins_count as f64;
    }

    // Mild preference for bins with residual below mean (consolidation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev.abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    }

    // Harmonic dead-space class: post_residual in (0,10) seals the bin perfectly.
    if post_residual > 0 && post_residual < 10 {
        score -= 2.0;
    }

    // Awkward class: residual >= 10 but too small for the next item -> future dead space.
    if next_item_size > 0 && post_residual >= 10 && post_residual < next_item_size {
        score += 4.0;
    }

    // Exact-fill harmonic class (item_size divides capacity nicely, e.g. 50, 25, 20).
    if item_size > 0 && bin_capacity % item_size == 0 && post_residual > 0 {
        score += 1.0; // mildly discourage fragmenting a bin that could take a divisor item exactly
    }
    if item_size > 0 && bin_capacity % item_size == 0 && post_residual == 0 {
        score -= 5.0; // perfect fill, always excellent
    }

    // Modulo-10 granularity: items on the 10-grid pair cleanly with typical residuals.
    if item_size % 10 == 0 && post_residual % 10 == 0 && post_residual > 0 {
        score -= 1.5;
    }

    // New-bin candidate: penalize slightly so it only wins when open bins are truly bad.
    if bin_residual == bin_capacity {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible item are pure waste -> heavy penalty.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Penalize large leftover gaps that will likely never be used well
    // unless they can fit the lookahead item.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual >= next_item_size {
            // Gap is reusable by the next item -> mild reward.
            score -= 8.0;
            // Extra reward if the next item fits snugly.
            let slack = post_residual - next_item_size;
            if slack < dead_threshold {
                score -= 12.0;
            }
        } else {
            // Gap cannot host the lookahead item -> dead-space pressure grows
            // with the gap size (wasted capacity).
            score += 0.25 * post_residual as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open and
    // their mean residual could accommodate the item.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins are underused.
        score += 20.0 + 3.0 * open_bins_count as f64;
        if mean_residual >= item_size as f64 {
            score += 30.0;
        }
    } else {
        // Reward using existing bins, scaled by how much they relieve pressure.
        score -= 1.5 * open_bins_count as f64;
    }

    // Early in the stream, be slightly more willing to open bins (better
    // packing structure later); late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tightest fit, scaled slightly by progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.05 * progress * post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - gap / 100.0).max(0.0) * (1.0 - gap / 100.0).max(0.0);
        // Perfect chain: this bin becomes exactly usable by the next item.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving residual that neither fits next item nor is reusable.
        if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 15.0;
        }
    }

    // Coupling with mean residual: avoid creating dead space relative to average slack.
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are all poor fits.
    if bin_residual == bin_capacity {
        score += 55.0 + 10.0 * progress;
        // If no existing bin leaves a reasonable residual, allow opening.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Penalize very small unusable fragments.
    if post_residual > 0 && post_residual < 5 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strong reward for tight placements.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Non-linear dead-space penalty: small leftovers are worse than medium ones.
        let pr = post_residual as f64;
        score += (bin_capacity as f64 / pr) * 2.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item (chained packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_quality = (post_residual - next_item_size) as f64;
        score -= 60.0 - 0.3 * chain_quality.min(100.0);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Penalize creating residual too small for the lookahead item (likely dead space).
        score += 15.0 + 0.2 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer filling existing bins.
    let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
    score -= pressure * 3.0;

    // Time horizon: early in the stream, be more willing to open new bins (score for
    // new-bin candidate relatively better); late in stream, consolidate.
    let t = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty so it only wins when open bins are bad fits.
        score = 0.5 * bin_capacity as f64 + 40.0 * (1.0 - t) - 25.0 * pressure;
        if item_size as f64 >= 0.7 * bin_capacity as f64 {
            // Large item: opening a fresh bin is often fine.
            score -= 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a bin
        }
    } else {
        // Existing bin: late-stream consolidation reward.
        score -= 20.0 * t;
    }

    // Mild preference for bins with residual close to item (best-fit sharpening).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: minimize post residual, with non-linear shrink of large dead space
    let mut score = pr * (1.0 + 0.8 * x * x);

    // Smooth coupling with stream progress: late in stream, tolerate tight fits more
    let prog_term = 6.0 * progress * (x - 0.25) * (x - 0.25) * cap;
    score += prog_term;

    // Reward near-perfect packing quadratically
    score -= 12.0 * (1.0 - x) * (1.0 - x) * (1.0 - x) * (item_size as f64 / cap);

    // Penalize waste relative to mean residual (dead space worse than average)
    score += 0.5 * (pr - mean_residual).abs() * (1.0 + progress);

    // Lookahead: if next item fits in post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strong incentive to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: mildly penalize early, more later (prefer existing bins)
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    // Crowding: many open bins -> prefer filling existing ones
    score += 0.3 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity-fraction buckets. Residuals in "usable" classes get rewarded.
    let frac = post_residual as f64 / bin_capacity as f64; // 0..1

    // Integer-division thresholds on post_residual (harmonic bands)
    let band = post_residual / 25; // 0,1,2,3 (0..25,25..50,50..75,75..100)
    let band_bonus: f64 = match band {
        0 => 40.0,                 // dead space <= 25 is worst -> penalize
        1 => 10.0,
        2 => -15.0,
        _ => -30.0,                // large leftover is reusable
    };
    score += band_bonus;

    // Modulo-class logic: residuals congruent to small values mod 10 are
    // "almost exact" fits for typical item sizes (multiples of 10).
    let m = post_residual % 10;
    if m == 0 {
        score -= 12.0; // leftover aligns with decimal item grid
    } else if m >= 7 {
        score += 6.0; // awkward sliver
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins lose against decent fits
        score = 100.0 + post_residual as f64;
        // If the item leaves a harmonic-friendly residual in a fresh bin
        // (i.e., next item likely fits), opening a new bin can win.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 35.0;
        }
        // Early in stream: prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.25 {
            score += 25.0;
        }
        // Many open bins with low mean residual: prefer fresh bin
        if open_bins_count > 4 && mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    // Lookahead: if next item exactly fills the post-residual, big reward
    if next_item_size == post_residual && post_residual > 0 {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use this leftover; mild penalty proportional to waste
        score += (post_residual as f64) * 0.15;
    }

    // Tight fits (small post_residual but nonzero) are good unless tiny
    if post_residual > 0 && post_residual <= 5 {
        score -= 20.0;
    }

    // Mean-residual coupling: placing into a bin below mean residual
    // (larger hole than average) balances the bin set
    if !is_new_bin && (bin_residual as f64) > mean_residual {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for even the minimum
    // item (1) are already minimal, but residuals that can only hold tiny
    // items are near-wasted. Penalize gaps in the "unusable band".
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 1000.0;
    } else if post_residual < 10 {
        // Dead space: nothing meaningful fits later (items >= 10 in classic
        // regime, but sizes can be 1..100; still, tiny gaps are poor).
        score += 25.0;
    } else if post_residual <= 20 {
        // Marginal gap: only very small items can use it.
        score += 8.0;
    }

    // Reward tight fits relative to item size (fill ratio).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits: mild reward proportional to how well it uses the gap.
        score -= 10.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // Next item cannot use this gap: penalize leaving a gap the immediate
        // future cannot fill.
        score += 5.0;
    }

    // Open-bin pressure: discourage proliferation of bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new one (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Mean residual coupling: prefer placing into bins whose residual is
    // close to the mean (keeps bin states homogeneous, avoids stragglers).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if the item is large and no
        // good squeeze exists. Penalize mildly by default; the base score
        // (post_residual == capacity - item) is high anyway for small items.
        score += 30.0;
        // But for very large items (>= 70), a fresh bin is fine — reduce penalty.
        if item_size >= 70 {
            score -= 25.0;
        }
        // Late in the stream, avoid opening new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Early stream: allow opening bins more freely (less pressure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tightest fit, scaled against mean residual pressure.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // ---- 2-step lookahead coupling ----
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let diff = post - next;
        if diff == 0.0 {
            // Perfect chain: this bin becomes exactly usable by the next item.
            score -= 40.0;
        } else if diff > 0.0 {
            // Next item still fits here: reward proportionally to how snugly.
            let snug = 1.0 - diff / (bin_capacity as f64);
            score -= 25.0 * snug * snug;
            // Penalize leaving a large, likely-unusable gap (dead space).
            if diff > 60.0 {
                score += 0.4 * (diff - 60.0);
            }
        } else {
            // Next item cannot follow into this bin: mild penalty,
            // stronger when the leftover sliver is tiny (wasted space).
            score += 6.0;
            if post < 10.0 {
                score += 4.0; // near-dead sliver
            }
        }
    } else {
        // Last item: just fill as tightly as possible.
        score -= 10.0;
    }

    // ---- Last-chance bonus: only bin that can fit the item ----
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when nothing fits well:
        // reward it if no existing bin fits, or if the item is large.
        if fitting_bins_count == 0 || item_size > 50 {
            score -= 20.0;
        } else {
            score += 25.0; // discourage wasting fresh bins on easy fits
        }
        // Late in the stream, keep bins consolidated.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer keeping number of open bins low (consolidation pressure).
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: reward small post_residual relative to item size
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score -= 30.0 / (1.0 + tightness);

    // Penalize creating dead space: post_residual too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is attractive when current bin would leave a large,
        // awkward residual or when mean residual across bins is already small.
        let waste = post_residual as f64;
        let open_penalty = 50.0 + 0.5 * open_bins_count as f64;
        // If this bin is the only fitting option, discourage new bin
        if fitting_bins_count == 1 {
            score += 200.0;
        } else {
            // Prefer new bin when residual waste elsewhere would be high
            score += open_penalty - 0.3 * waste;
        }
    }

    // Lookahead: if next item fits the post residual exactly, big bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            score -= 0.5 * next_item_size as f64 * (post_residual as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for leaving residual it can't use
            score += 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // Time horizon: early in stream, be more selective (penalize loose fits);
    // late in stream, just fill bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into bins with residual near mean (balance load)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Mild preference for bins with larger residual when few bins are open
    if open_bins_count <= 2 {
        score += 0.05 * (bin_capacity as f64 - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: waste after placement
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 1.0 + 2.0 * t - 3.0 * t * t + 2.0 * t * t * t;
    score += 30.0 * (pr_norm * pr_norm) * poly;

    // Penalize residuals that cannot fit the lookahead item (smooth soft gate)
    if next_item_size > 0 {
        let fits_next = (pr >= next_item_size as f64) as i32 as f64;
        let slack = (pr - next_item_size as f64).abs();
        score -= 25.0 * fits_next * (1.0 - t) - 0.1 * slack;
    }

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - pr_norm);
    }

    // Mild preference for tight fits relative to mean residual
    score -= (mean_residual - pr) * 0.15;

    // New-bin candidate: neutral-ish baseline with progress-aware pull
    if bin_residual == bin_capacity {
        score = cap * 0.6 + 20.0 * t - 0.5 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: modulo classes of capacity fractions.
    // Residuals in the "small dead zone" (0..=10) are nearly perfect fits -> strong reward.
    if post_residual == 0 {
        score -= 120.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 90.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    } else {
        // Dead-space penalty grows quadratically beyond the small zone.
        let dead = (post_residual as f64 - 10.0).max(0.0);
        score += 0.35 * dead * dead;
    }

    // Harmonic quarter classes: residuals near multiples of 25 are reusable
    // by typical mid-size items (25/50/75 classes).
    let mod25 = post_residual % 25;
    if mod25 == 0 && post_residual > 0 {
        score -= 25.0;
    } else if mod25 <= 5 || mod25 >= 20 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward heavily;
    // if next item cannot fit anything else well, this bin becomes critical.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (post_residual as f64) >= ni {
            score -= 15.0 + 0.2 * ni;
        } else {
            // Next item won't chain here; penalize leaving medium-large residuals unused.
            score += 0.15 * ni;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a fresh bin wastes capacity if the item
    // would fit reasonably in an existing bin with decent post-residual.
    if bin_residual == bin_capacity {
        // Base cost of a new bin: large, but reduced when existing fits are poor.
        score = cap + 30.0;
        if post_residual == 0 { score -= 0.0; } // (post_residual == cap here)
        if next_item_size > 0 && (bin_capacity - next_item_size) >= 0 {
            // A fresh bin pairs perfectly with the next item if item is large.
            if next_item_size >= 50 { score -= 40.0; }
        }
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open
        }
    }

    // Progress modulation: late in the stream, prefer tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is too small to hold the next item
    // (or any plausible small item when lookahead is unavailable).
    let min_useful = if next_item_size > 0 { next_item_size } else { 10 };
    let min_useful = min_useful.min(bin_capacity / 2).max(1) as f64;

    if (post_residual as f64) < min_useful {
        // Dead space: penalize quadratically with closeness to zero gap.
        let deadness = 1.0 - (post_residual as f64) / min_useful;
        score += 40.0 * deadness * deadness;
    } else {
        // Usable leftover space: mild reward scaled by how much room remains.
        score -= 2.0 * (post_residual as f64) / bin_capacity as f64;
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Open-bin pressure: discourage spreading across many bins,
    // but relax pressure late in the stream when consolidation matters less.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = 3.0 + 5.0 * (1.0 - progress);
    score += pressure * (open_bins_count as f64).ln().max(0.0);

    // If this bin is the last chance to fit the item, favor it to avoid
    // opening a fresh bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when the item would leave
    // a nicely reusable gap, or when existing bins would create dead space.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; slight penalty so we prefer existing
        // bins unless they are truly bad fits.
        score += 10.0;
        // A fresh bin gives a full residual: reward if item is large.
        if item_size >= bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Nudge toward bins whose residual is close to the mean (typicality),
    // slightly penalizing outliers with abnormal slack.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Lookahead synergy: if the next item could exactly fill this bin's
    // post-residual, strongly favor this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fits (small post_residual already favored).

    // 2-step lookahead: perfect match between post_residual and next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post_residual == next_item_size {
            // Next item exactly fills this bin -> excellent chaining.
            score -= 40.0 + 0.5 * nxt;
        } else if post_residual >= next_item_size {
            // Next item can also go here; reward proportionally to how snug.
            let snug = 1.0 - ((post - nxt) / bin_capacity as f64);
            score -= 10.0 + 20.0 * snug * snug;
        } else {
            // Next item cannot fit here; penalize dead space relative to gap.
            let gap = nxt - post as f64;
            score += 0.3 * gap;
        }

        // Penalize leaving residual slightly larger than typical item sizes
        // (wasted space that likely cannot be filled).
        if post_residual > 0 && post_residual < 10 {
            score -= 5.0; // tiny residual is fine, bin nearly full
        }
    } else {
        // Last item: just prefer tightest fit.
        score -= 5.0;
    }

    // Compare against mean residual of open bins: prefer bins tighter than average.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to remaining space or no good fits exist.
    if bin_residual == bin_capacity {
        // New bin starts with full residual; give it a neutral-to-slightly-high
        // score so it wins only when open bins leave big unusable residuals.
        score += 8.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            // Fresh bin can chain the next item too: make it competitive.
            score -= 12.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative
        }
    }

    // Late in the stream, consolidate: penalize opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Slight penalty when many bins are open: encourage filling existing ones.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: bins with small post_residual get priority.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize leaving awkward dead space (< smallest plausible item, ~10),
    // unless it's an exact fit.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward proportional to how well it fills
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use the residual: penalize large wasted space
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins below mean residual (i.e., emptier bins used when others
    // are tight) — keep tight bins for tight fits.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 4.0 * dev;
    }

    // New-bin candidate handling: opening a new bin is expensive early,
    // cheaper late when many bins are open and fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let horizon = 1.0 - progress;
        score += 10.0 * fragmentation * horizon;
        // But if the current item is huge and no bin is a good fit, allow new bin
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 6.0;
        }
    }

    // Mild time pressure: late in the stream, consolidate to avoid opening bins
    score -= 2.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Small penalty for bins that would be nearly full but not full —
    // prefer exact 0 residual above all.
    if post_residual > 0 && post_residual <= 5 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let norm_pr = pr / bin_capacity as f64;
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress) + norm_pr * progress * (1.0 - progress) * 4.0;
    score += poly * bin_capacity as f64 * 0.5;

    // Reward tight fits more strongly as stream progresses
    let tightness = (item_size as f64 / bin_capacity as f64).powi(2);
    score -= tightness * 20.0 * (0.5 + progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let gap = if post_residual > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += gap * (next_item_size as f64) * (1.0 + progress) * 0.8;
        // Reward leaving room for the next item
        if post_residual >= next_item_size {
            score -= (next_item_size as f64 / bin_capacity as f64) * 15.0;
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 1.5 * norm_pr;

    // Deviation from mean residual: prefer bins near mean to balance
    let dev = (pr - mean_residual).abs() / bin_capacity as f64;
    score += dev * dev * 10.0;

    // New-bin candidate: penalize opening a new bin unless residuals are tiny
    if bin_residual == bin_capacity {
        let mean_ratio = mean_residual / bin_capacity as f64;
        score += 30.0 * (1.0 - mean_ratio * mean_ratio) * (1.0 + 2.0 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: partition residual space into
    // capacity-fraction classes (1/4, 1/2, 3/4) and treat them differently.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * quarter;

    // Dead-space penalty: residuals that no typical item (1..=80) can use well.
    // A residual in (0, quarter) is nearly unusable -> heavy penalty.
    if post_residual > 0 && post_residual < quarter {
        score += 30.0;
    } else if post_residual == 0 {
        // Perfect fill: reward strongly.
        score -= 50.0;
    } else if post_residual <= half {
        // Small residual classes: mild reward for tight packing.
        score -= 5.0;
    } else if post_residual <= three_quarter {
        score += 3.0;
    }

    // Modulo arithmetic on post_residual: residuals divisible by small
    // harmonics (4, 8) tend to admit more future integer item splits.
    if post_residual % 8 == 0 && post_residual > 0 {
        score -= 4.0;
    } else if post_residual % 4 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this placement is excellent.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits: the tighter, the better.
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot fit here: slight penalty for stranding space.
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has large residual; penalize
    // opening a new bin unless the item is large and open bins are fragmented.
    if bin_residual == bin_capacity {
        score += 12.0;
        if item_size > three_quarter {
            score -= 15.0; // big items deserve fresh bins
        }
        // If existing bins are fragmented (mean residual low), new bin is fine.
        if mean_residual < quarter as f64 && open_bins_count > 0 {
            score -= 8.0;
        }
    }

    // Stream progression: early on, encourage consolidation (prefer filling
    // existing bins); late in the stream, exploit best fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Penalize bins whose residual deviates far from the mean (keeps class
    // structure coherent across the bin pool).
    score += 0.05 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1) are pure waste,
    // but residuals too small for typical items (>= 10) are effectively dead too.
    if post_residual < 10 {
        // Unusable gap: heavy penalty proportional to how "trapped" the space is.
        score += 60.0 + 0.5 * (10 - post_residual) as f64;
    } else if post_residual < 20 {
        // Marginal zone: likely dead space for most item sizes.
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Tight-fit reward: item consumes most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 15.0 * fill_ratio;
    } else if fill_ratio < 0.3 && bin_residual < bin_capacity {
        // Sparse fill into an already-open bin wastes its potential.
        score += 10.0 * (1.0 - fill_ratio);
    }

    // Open-bin pressure: discourage spreading across many bins when few bins fit the item.
    score += 2.0 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in the post-residual, this placement is synergistic.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual blocks the next item: penalize mildly.
        score += 5.0;
    }

    // New-bin candidate handling: an empty bin has no dead space yet; make it attractive
    // only when existing bins would leave bad gaps.
    if bin_residual == bin_capacity {
        // Neutral baseline for fresh bin; the dead-space penalties above on open bins
        // will naturally make a fresh bin win when fits are poor.
        score += 3.0 * open_bins_count as f64;
    }

    // Stream progression: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a convex penalty
    // that grows super-linearly as leftover space becomes large (dead space).
    score += 0.045 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward exact/near-exact matching of the
    // post_residual with the next item size (perfect two-item packing).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 6.0 * (1.0 - gap / bin_capacity as f64).max(0.0).powi(3);

        // If the next item fits EXACTLY in the leftover, strong reward.
        if post_residual == next_item_size {
            score -= 12.0;
        }
        // If the next item would also fit here after this placement, mild
        // penalty for hoarding space that the current bin could still use —
        // unless the match is exact (handled above).
        else if next_item_size <= post_residual {
            score += 2.0;
        }
    }

    // Relative-to-mean coupling: bins with residual well below the mean are
    // already "cramped"; using them is good (they are nearly done).
    let rel = post_residual as f64 - mean_residual;
    score += 0.15 * rel;

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): penalize opening a new
    // bin unless the item is large and leaves a small, usable residual.
    if bin_residual == bin_capacity {
        score += 8.0;
        // Large items pack efficiently into fresh bins; ease the penalty.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 6.0;
        }
        // Late in the stream, avoid proliferating bins with tiny leftovers.
        if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 4.0;
        }
    }

    // Mild consolidation pressure: with many open bins, favor filling existing
    // ones rather than spreading items out.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Perfect or near-perfect fill gets a strong discount.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Dead space penalty: residuals too small for the smallest item (1) are fine,
    // but residuals that are small-yet-nonzero waste capacity.
    if post_residual > 0 && post_residual < 15 {
        score += 6.0;
    }

    // Lookahead: if the next item exactly fits the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let waste_next = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - waste_next / bin_capacity as f64);
        } else {
            // next item cannot follow here; slight penalty for leaving a "trap" residual
            score += 3.0;
        }
    } else {
        // Last item: strongly prefer fullest bin.
        score -= 30.0 * tightness;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // When many bins fit the item, prefer the one with smallest residual (already
    // captured by post_residual), but add mild penalty scaled by competition to
    // break ties toward conserving large-residual bins.
    if fitting_bins_count > 1 {
        score += 2.0 * ((bin_residual as f64 - mean_residual).abs() / bin_capacity as f64);
    }

    // New-bin candidate logic: opening a bin is only attractive when no existing
    // bin fits well, or the stream is early and we want many bins open.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 15.0;
        // Early in the stream, opening bins is cheaper (builds flexibility).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If many bins already fit, discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 10.0 + 5.0 * fitting_bins_count as f64;
        }
        // If the item is large, a fresh bin is more attractive.
        score -= 0.1 * item_size as f64;
    }

    // Global state coupling: when mean residual across open bins is high,
    // prefer filling existing bins harder.
    score -= 4.0 * (mean_residual / bin_capacity as f64) * tightness;

    // Mild time-dependent tightening: later in stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: prefer filling bins nearly full (penalize leftover quadratically).
    // Late stream: leftover matters less, allow opening/spreading.
    let p1 = pr / cap;
    let p2 = p1 * p1;
    let p3 = p2 * p1;

    // Quadratic + cubic penalty on residual, modulated by progress.
    let mut score = pr as f64
        + 6.0 * p2 * cap * (1.0 - 0.5 * progress)
        + 2.5 * p3 * cap * (1.0 - progress);

    // Reward tight fits: small post_residual relative to item size.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 8.0 * tightness * (1.0 - progress);

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0 * (next_item_size as f64) / cap;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space unusable by next item: penalize proportionally.
        score += 3.0 * pr / cap;
    }

    // New-bin candidate handling: mildly discourage opening new bins unless
    // existing residuals are large or the item is huge relative to residual.
    if bin_residual == bin_capacity {
        let spread = mean_residual / cap;
        let pressure = fit_ratio * fit_ratio;
        score = cap as f64 * (0.35 + 0.5 * spread + 0.6 * pressure * (1.0 - progress))
            - 10.0 * progress;
        // If no existing bin fits well, opening is fine.
        if fitting_bins_count == 0 {
            score -= 12.0;
        }
        // If this is the only fitting option among open bins, discourage new bin.
        if fitting_bins_count == 1 {
            score += 20.0;
        }
    }

    // Mild open-bin congestion term: many open bins -> prefer consolidation.
    score += 0.15 * open_bins_count as f64 * (1.0 - progress) * p1;

    // Mean residual coupling: when average residual is large, filling a bin is valuable.
    score -= 2.0 * (mean_residual / cap) * (1.0 - p1) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    let post = post_residual as u32;
    let class = post % 25; // quarters of capacity
    match class {
        0 => score -= 40.0,          // post residual exactly a quarter multiple => very reusable
        10 => score -= 25.0,         // classic leftover for small items
        20 => score -= 30.0,
        _ => {}
    }

    // Integer division thresholds: post_residual bucketed by 10s
    let bucket = post / 10;
    score -= (bucket as f64) * 2.0;

    // Lookahead: reward if next item fits exactly into post residual (perfect pairing)
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 60.0;
        } else if next_item_size <= post {
            // harmonic class of next item relative to post residual
            let diff = post - next_item_size;
            if diff % 25 == 0 { score -= 35.0; }
            score -= (post as f64 - next_item_size as f64) * 0.3;
        } else {
            // next item cannot fit: dead space penalty scaled by dead fraction
            score += (next_item_size as f64 - post as f64) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else {
        score += (fitting_bins_count as f64) * 1.5;
    }

    // Tight fit bonus: fraction of capacity consumed by this placement
    let fill = item_size as f64 / cap;
    score -= fill * 20.0;

    // Penalize creating tiny unusable residuals (dead space classes 1..=9)
    if post > 0 && post < 10 {
        score += 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive early in the stream
    // or when mean residual of open bins is very low.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fresh_bonus = 25.0 * (1.0 - progress) + (mean_residual / cap) * 30.0;
        score -= fresh_bonus;
        // empty bin has post_residual = capacity - item; keep its natural score otherwise
    }

    // Mild penalty for proliferating bins when existing mean residual is high
    score += open_bins_count as f64 * 0.4 - (mean_residual / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum plausible item size (1..=12)
    // are essentially unusable "dead" space -> strong penalty.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }

    // Reward near-perfect fills strongly (waste < 5 is gold).
    if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 10 {
        score -= 6.0;
    }

    // Penalize creating a gap that can't fit the lookahead item but is large enough
    // to be wasted otherwise.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 3.0 + 0.1 * (next_item_size - post_residual) as f64;
    }
    // Reward if the next item fits exactly into the post residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (penalize the new-bin option implicitly by rewarding this).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins;
    // the new-bin candidate gets penalized via its full residual (== capacity),
    // but add explicit pressure proportional to open bins.
    if bin_residual == bin_capacity {
        score += 5.0 + 1.5 * open_bins_count as f64;
    } else {
        score -= 0.5 * open_bins_count as f64;
    }

    // Early in the stream, allow opening bins more freely (exploration).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    // Prefer bins whose residual deviates favorably from the mean residual
    // (tighter-than-average bins should be filled first).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (post residual close to 0 or exactly matching next item).
    let pr = post_residual as f64;
    if pr == 0.0 {
        score -= 60.0;
    }

    // 2-step lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            // next item fits, penalize leftover after that hypothetical placement
            let second_left = post_residual - next_item_size;
            score += second_left as f64 * 0.3;
            score -= 5.0;
        } else {
            // next item won't fit here; penalize bins that leave awkward gaps
            score += 8.0;
        }
    }

    // Prefer bins whose residual is tight relative to mean residual (good packing density).
    score += (pr - mean_residual) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize opening a new bin when existing bins fit decently (post_residual small).
    if bin_residual == bin_capacity && bin_capacity != 0 {
        // new bin candidate: baseline cost plus its post residual
        score += 25.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Slight preference for filling bins more as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * tightness * tightness;

    // Reward filling a bin completely (post_residual == 0 strongly favored).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 80.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Lookahead: penalize if placing here leaves a residual that neither
    // fits the next item nor is likely useful.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0; // residual stays useful for the lookahead item
        } else if post_residual > 0 {
            // dead space relative to the next item's need
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    } else {
        // Last item overall: just close bins as tightly as possible.
        score += 0.0;
    }

    // New-bin candidate handling: an empty bin has huge post_residual,
    // so make it attractive only when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how fragmented
        // open bins are and how many could fit the item.
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = bin_capacity as f64 - 40.0 * fragmentation;
        if fitting_bins_count == 0 {
            score -= 500.0; // no open bin fits: must open new bin
        }
        if fitting_bins_count == 1 {
            score += 120.0; // a last-chance open bin exists: prefer it
        }
        // Later in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 60.0 * progress;
    }

    // Mild preference for bins that are already more filled than average
    // (best-fit flavor), scaled by stream progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let fill_gap = mean_residual - bin_residual as f64;
    score += 0.3 * fill_gap * (0.5 + 0.5 * progress);

    // Penalize leaving residuals that are too small to ever be useful
    // (dead space below the minimum plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: prefer small post-residual, with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * fit_norm * fit_norm);

    // Smooth progress coupling: tighten packing later in the stream
    let tighten = 1.0 + 0.8 * progress * progress;
    score *= tighten;

    // Penalize dead space relative to mean residual (smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Last-chance bonus: if this is the only fitting bin, reward using it
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else {
        // Mild reward when many bins compete (encourages best-fit selection)
        score -= (fitting_bins_count as f64).ln() * 1.5;
    }

    // Lookahead: reward residual that can fit the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = (pr - nxt).max(0.0) / cap;
        score -= 8.0 * (1.0 - (fits * cap / cap).abs()) * (if pr >= nxt { 1.0 } else { 0.0 });
        // smooth penalty if next item cannot fit
        if pr < nxt {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // New-bin candidate: penalize opening new bins unless current residual is badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).min(1.0);
        score = cap + 20.0 * (1.0 - fragmentation * fragmentation) - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 25.0;
    } else {
        // Harmonic class: penalize dead space in coarse modulo classes
        let class = post_residual % 20;
        score += class as f64 * 0.8;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 30.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize leaving awkward residual
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        // Base penalty so we prefer existing bins with decent fits.
        score += 35.0;
        // Early in stream, opening bins is cheaper (spread items).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If mean residual of open bins is small, new bin is attractive.
        score -= (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 25.0;
        // If no open bin fits at all, new bin is required.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Large items start fresh bins preferentially.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    } else {
        // Existing bin: mild reward proportional to how full the bin already is.
        let used_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= used_frac * 12.0;
    }

    // Slight preference to keep number of open bins bounded.
    if open_bins_count > 10 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Mid-range dead space that likely cannot host future items (min item 10,
    // but unknown distribution: keep graded penalty).
    if post_residual > 0 && post_residual < 25 {
        score += 15.0;
    }

    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 8.0 * open_bins_count as f64;
    } else {
        score -= 3.0 * open_bins_count as f64;
    }

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    }
    // If next item cannot fit in the gap, penalize leaving a tempting dead gap.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins whose residual tracks the mean (balance),
    // penalize creating outliers far above mean residual.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Late in the stream, tighten tolerance for waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but keep a floor so a
    // perfect 2-step match can beat an exact-fill-only candidate.
    score = 0.35 * (post_residual as f64) + 0.65 * ((post_residual as f64) / bin_capacity as f64) * 50.0;

    // Aggressive 2-step lookahead: reward when the next item exactly fills
    // the post residual (chained perfect fit).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward when next item fits and leaves minimal slack again.
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportional to overshoot.
            score += 0.5 * gap;
        }
        // Exact 2-step match: big bonus.
        if next_item_size == post_residual {
            score -= 45.0;
        }
    } else {
        // Last item: only absolute tightness matters.
        score = post_residual as f64;
    }

    // Relative to mean residual: placing in a below-average-residual bin
    // (tighter bin) is good; leaving lots of slack in a loose bin is bad.
    let pr = post_residual as f64;
    score += 0.4 * (pr - mean_residual).max(-80.0).min(80.0);

    // Dead-space penalty: residuals too small for the smallest item are waste.
    if post_residual < 1 {
        score -= 10.0; // exact fill is ideal
    } else if post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when no good chain fit exists.
    if bin_residual == bin_capacity {
        // Neutral-ish base; lookahead on empty bin: next item gets fresh space.
        score = 40.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // Fresh bin can host next item too; slightly favor if current item is small.
            score -= 0.1 * item_size as f64;
        }
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize by how much slack remains relative to item size.
    let tightness = item_size as f64 / bin_residual as f64; // in (0,1]
    score -= 20.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 {
        score += 15.0;
    } else if post_residual < 20 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward; if this bin would be
    // perfect for the next item but wasted on current one, penalize.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 8.0;
        }
        // If next item would fit this bin exactly but current placement leaves it worse.
        if next_item_size == bin_residual {
            score += 30.0; // save this bin for the exact-fit next item
        }
        // If next item is large and current item is small, prefer spreading load.
        if next_item_size > item_size && next_item_size > post_residual as u32 {
            score += 4.0;
        }
    }

    // New-bin candidate handling: empty bin gets a baseline cost so we only open
    // a new bin when fits elsewhere are poor.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Early in stream, opening bins is cheaper (build capacity).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // If many bins are open with large residuals, discourage new bin.
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 8.0;
        }
        // If next item is huge, having a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 6.0;
        }
    } else {
        // Prefer bins with below-average residual (fill emptier bins first)
        let dev = bin_residual as f64 - mean_residual;
        score += 0.15 * dev;
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: normalized post residual, penalized more as stream progresses
    let norm_post = post / cap;
    let mut score = norm_post * (1.0 + 2.0 * progress);

    // Non-linear polynomial coupling: squared and cubic residual terms
    score += 0.8 * norm_post * norm_post;
    score -= 0.3 * norm_post * norm_post * norm_post;

    // Interaction: residual waste relative to mean residual across open bins
    let mean_n = mean_residual / cap;
    score += 0.5 * (norm_post - mean_n) * (norm_post - mean_n);

    // Reward tight fits: small post residual relative to item size
    let item = item_size as f64;
    let tightness = 1.0 - (post / (bin_residual as f64).max(1.0));
    score -= 1.5 * tightness * tightness * (item / cap);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 3.0;
    } else {
        // Mild penalty when many bins compete (spread items to avoid fragmentation)
        score += 0.05 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: penalize if next item could use this residual better
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let overlap = (next_item_size as f64) / post.max(1.0);
        score -= 0.6 * overlap * (1.0 - progress);
    } else if next_item_size > 0 {
        // next item won't fit in residual: dead-space penalty grows with progress
        score += 0.4 * norm_post * progress;
    }

    // Slight preference for consolidating into fewer bins early on
    score += 0.02 * (open_bins_count as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect closure, strongly favored.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement chains perfectly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Residual keeps the next item placeable: mild reward.
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // This placement kills the bin for the known next item: penalize
        // proportionally to how much usable space is destroyed.
        score += 60.0 + (next_item_size - post_residual) as f64 * 2.0;
    }

    // Harmonic class of post_residual (mod capacity fractions):
    // small residuals (< 10) are dead space; large residuals are flexible.
    let small_dead = post_residual < 10;
    if small_dead {
        score += 40.0; // discourage leaving tiny unusable slivers
    }

    // Integer-division thresholds: classify residual into harmonic bands
    // using capacity/4 and capacity/8 boundaries.
    let c = bin_capacity;
    let band = match post_residual {
        0 => 0,
        x if x <= c / 8 => 1,
        x if x <= c / 4 => 2,
        x if x <= c / 2 => 3,
        _ => 4,
    };
    // Favor bands with high reusability (large residual) mildly.
    score -= band as f64 * 8.0;

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a good fit. Make the fresh bin moderately expensive
    // so tight fits in existing bins win, but cheap when existing fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of a new bin.
        score = (bin_capacity - item_size) as f64 + 50.0;
        // If many bins fit the item, opening a new bin is wasteful.
        score += fitting_bins_count as f64 * 25.0;
        // If the mean residual is large, existing bins likely suffice.
        if mean_residual > item_size as f64 * 1.5 {
            score += 100.0;
        }
        // Early in the stream, opening bins is cheaper (future items benefit).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 40.0;
        // Perfect packing classes: items that are divisors of capacity leave
        // no waste when starting fresh (e.g. 50, 25, 20, 10).
        if bin_capacity % item_size == 0 {
            score -= 30.0;
        }
    }

    // Modulo coupling: residual congruent to common item sizes (multiples of 10)
    // is more likely reusable; reward that alignment.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Slight preference for fuller bins among comparable options.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward tight fits (near-perfect packing).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tight use.
    let pressure = open_bins_count as f64 / 20.0;
    score += pressure * post_residual as f64 * 0.3;

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && (post_residual as u32) > 0 {
        score += 8.0;
    }

    // New empty bin: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 35.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        if gap == 0.0 {
            score -= 500.0; // perfect 2-step chain
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // dead space: post_residual too small for next item
        score += 40.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Penalize wasted residual relative to mean residual of open bins
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 150.0 * pressure;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0; // new bin may host next item too
        }
    }

    // Late in stream: consolidate, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 50.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for typical items (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if the next item fits exactly in post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (post_residual as f64 - next_item_size as f64) / cap;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins with below-average residual (consolidate emptier bins).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Time horizon: early on, be more willing to open new bins (favor tight fits anyway);
    // late in the stream, penalize opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 + 40.0 * progress;
    }

    // Mild penalty for accumulating too many open bins.
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) * 40.0
                 + norm_pr * progress * 25.0;
    score += coupling;

    // Penalize near-full waste smoothly (dead space that is hard to reuse)
    let waste = (norm_pr - 0.2).max(0.0);
    score += waste * waste * cap * 0.5;

    // Reward tight fits: small post_residual relative to item size
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= tightness * 30.0 * (1.0 - progress * 0.5);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let diff = pr - next_item_size as f64;
        if diff >= 0.0 {
            score -= 15.0 + diff * 0.1;
        } else {
            score += (-diff) * 0.3;
        }
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: make it attractive only for large items or poor fits elsewhere
    if bin_residual == bin_capacity {
        score -= 10.0 + item_size as f64 * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo 10: waste classes
    let m = post_residual % 10;
    // Dead-space penalty grows for awkward classes (1,2,3 tiny slivers; 7,8,9 near-full awkward)
    let class_penalty: f64 = match m {
        0 => -6.0,
        5 => -3.0,
        4 | 6 => -1.0,
        1 | 2 | 3 => 4.0 + 2.0 * m as f64,
        7 | 8 | 9 => 1.0 + 0.5 * (m as f64 - 6.0),
        _ => 0.0,
    };
    score += class_penalty;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Capacity fraction of residual
    let frac = post_residual as f64 / bin_capacity as f64;
    // Penalize residuals in dead zone (0.05..0.20) that few next items can use
    if frac > 0.02 && frac < 0.20 {
        score += 8.0 * (0.20 - frac);
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chainability reward, scaled by how snugly it fits
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 4.0 + 6.0 * snug;
        } else {
            score += 2.0;
        }
        // Harmonic threshold: next item exactly complements residual to a multiple of 10
        if (post_residual + next_item_size) % 10 == 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin gets baseline score
    if bin_residual == bin_capacity {
        // competitive with moderately wasteful placements; worse than good fits
        score = bin_capacity as f64 * 0.35 + 8.0;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 3.0; // fresh bin good for sequence of similar items
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Stream progression: late in stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).abs().min(10.0) * 0.3;

    // Prefer bins whose residual is above mean (keep tight bins for tight fits)
    if (post_residual as f64) < mean_residual {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 8.0;
    }
    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // leftover too small for next item -> dead space risk
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Relative tightness coupling: reward filling well relative to mean residual.
    if bin_residual as f64 >= mean_residual {
        score -= 4.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: only attractive when nothing fits well or stream is early.
    if bin_residual == bin_capacity {
        let bad_fit = fitting_bins_count == 0
            || (fitting_bins_count == 1 && (bin_residual - item_size) < 10 && next_item_size > post_residual);
        if bad_fit {
            score -= 30.0;
        } else {
            score += 35.0 + 10.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the next item exactly fills the post
    // residual, this is a perfect chain placement -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 45.0;
        } else if next_item_size as u32 <= post_residual {
            score -= 22.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // Next item cannot fit in the leftover: dead-space penalty scaled
            // by how much is wasted.
            score += 0.15 * (post_residual as f64);
        }
    }

    // Compare residual against mean residual: prefer bins with below-average
    // residual (denser bins) to keep large residuals available for large items.
    score += 0.35 * ((bin_residual as f64) - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a brand-new bin unless the current item is large and
    // no open bin has a good fit (post residual would be small).
    if bin_residual == bin_capacity {
        let new_bin_base = 55.0
            - 20.0 * tightness
            + 0.4 * open_bins_count as f64
            - 8.0 * (item_size as f64 / bin_capacity as f64);
        if next_item_size > 0 && post_residual == next_item_size {
            // Opening a new bin enables a perfect next-item chain.
            score -= 25.0;
        }
        score += new_bin_base;
    }

    // Slight preference early in the stream to consolidate into fewer bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.05 * (1.0 - progress) * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual so small leftovers dominate.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64).powi(2) * 40.0;

    // Penalize bins whose residual is much tighter than the average open bin
    // (preserving flexible bins is valuable; prefer to drain loose bins).
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (res_f - mean_residual).abs() * 0.15;
        if res_f < mean_residual {
            score += 6.0; // extra penalty for using the tightest bins
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + item_size as f64 * 0.2;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement;
    // if next item would fit bin_residual but not post_residual, penalize.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual as f64 >= n {
            score -= 8.0;
        } else if res_f >= n && item_size as f64 > n * 0.6 {
            score += 10.0; // we consumed space the next item needed
        }
    }

    // New-bin candidate handling: opening a fresh bin is attractive early in the
    // stream (future flexibility) but wasteful late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress); // early: new bins are cheap
        score += 30.0 * progress;         // late: prefer existing bins
        // If many bins are open already, discourage yet another one.
        score += open_bins_count as f64 * 1.5;
        // But if no open bin fits well (post_residual large relative), allow it.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild time-horizon shaping: as the stream progresses, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += score * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic decay of the fit ratio
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize large leftover relative to capacity, smoothed by progress
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * waste_frac * waste_frac * (0.5 + progress);

    // Penalize bins whose residual is far below the mean (fragmented bins)
    score += 0.3 * (mean_residual - bin_residual as f64).abs();

    // Last-chance bonus: only one bin can fit this item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: reward leaving space exactly matching the next item
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= 10.0 * (-gap / 20.0);
    }

    // Mild pressure to prefer existing bins as stream progresses
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 5.0 + 10.0 * (1.0 - progress) + open_bins_count as f64;
    }

    // Non-linear coupling of post_residual with progress
    score += 8.0 * (post_residual as f64 / bin_capacity as f64).powi(3) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residual classes mod 10 and integer-division tiers
    let cls = post_residual % 10;
    let tier = post_residual / 10; // 0..=10

    // Penalize "awkward" dead space classes that few item sizes can fill
    // (odd non-multiples of 5 are hardest to fill exactly)
    let awkward = match cls {
        1 | 3 | 7 | 9 => 6.0,
        2 | 4 | 6 | 8 => 2.5,
        _ => 0.0, // multiples of 5 or exact 0 are friendly
    };
    score += awkward * (tier.min(5) as f64);

    // Reward small tiers (tight packing) super-linearly
    score -= (10 - tier as f64) * (10 - tier as f64) * 0.35;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Next-item lookahead: reward residuals that the next item fits into (harmonic match)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + (post_residual - next_item_size) as f64 * 0.3;
            // exact match for next item is excellent
            if next_item_size == post_residual {
                score -= 25.0;
            }
        } else {
            // next item cannot use this residual: penalize proportionally to waste
            score += (next_item_size - post_residual).min(40) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize mildly so we only open new bins when open bins are bad
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if item is large relative to mean residual, opening fresh is attractive
        let mean_r = mean_residual.max(0.0);
        if (item_size as f64) > mean_r * 0.8 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size > mean_r.max(0.0) as u32 {
            score -= 10.0;
        }
    }

    // Stream progression: later in the stream, consolidate harder (avoid many half-empty bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.15 * progress;

    // Slight preference toward bins whose residual is close to item (best-fit core)
    score += (bin_residual as f64 - item_size as f64).abs() * 0.05;

    // Cap score to keep comparisons stable
    if score < -200.0 { score = -200.0; }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to hold
    // even the minimum item are pure waste — penalize them hard.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 + (10 - post_residual) as f64 * 5.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else {
        // Smooth penalty on small-but-usable gaps (harder to reuse).
        let t = post_residual as f64 / bin_capacity as f64;
        score += 12.0 * (1.0 - t) * (1.0 - t);
    }

    // Reward bins whose residual tightly matches the item (low slack ratio).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in the post-residual,
    // this placement chains nicely — reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_tightness = next_item_size as f64 / post_residual as f64;
        score -= 15.0 * chain_tightness;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        // Next item can't use the dead space we'd create: extra penalty.
        score += 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is great.
    score += (open_bins_count as f64) * 2.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.3;

    // New-bin candidate handling: opening a fresh bin is only attractive early
    // in the stream or when no bin offers a decent fit; otherwise penalize it.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit_exists = fitting_bins_count > 0
            && fitting_bins_count == open_bins_count
            && (bin_residual - item_size) as f64 > mean_residual;
        if fitting_bins_count > 0 && !poor_fit_exists {
            score += 30.0 + 40.0 * progress;
        } else if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but strongly reward exact 2-step matches.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chain: this bin's leftover exactly fits the next item.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Leftover can still host the next item: mild reward proportional to closeness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Leftover cannot host next item: dead space penalty, worse when very small.
            let dead = next_item_size - post_residual;
            score += 12.0 * dead as f64 / next_item_size as f64;
        }
    }

    // Compare against mean residual: bins below mean residual are already tight,
    // filling them further is good (reward); bins far above mean are wasteful targets.
    let r = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (r - mean_residual) / mean_residual;
        score += 8.0 * rel.max(-2.0).min(2.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is catastrophically loose).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins fit badly.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Pairing both items in a fresh bin is attractive.
            score -= 10.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild penalty for leaving tiny unusable slivers (hard-to-fill residue).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    } else {
        // Penalize large dead space quadratically, scaled by how unusable it is
        // relative to the smallest plausible item.
        let waste = post_residual as f64;
        score += 0.08 * waste * waste / 10.0;
    }

    // Tightness of the fit: fraction of bin consumed by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Lookahead: if the next item fits into the resulting residual, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // good chaining: residual still useful
            score -= 12.0 * (1.0 - nxt / 100.0);
        } else if (post_residual as f64) >= nxt * 0.5 {
            // marginal chaining
            score -= 3.0;
        } else {
            // residual becomes dead space for the known next item
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
        if post_residual <= 15 {
            score -= 25.0;
        }
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Make the empty bin's baseline score depend on global state.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: higher when many bins are already open.
        score += 30.0 + 1.5 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper (builds a pool of residuals);
        // late in the stream, prefer consolidating into existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If mean residual across open bins is small, existing bins are nearly full,
        // so a new bin is more acceptable.
        score -= 0.3 * mean_residual;
        // If the item is large, it will dominate a fresh bin anyway.
        score -= 10.0 * fill;
    }

    // Slight preference for bins with below-average residual (pack big items into
    // tighter bins, keep roomy bins for roomy future items).
    score -= 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = norm_pr * (1.0 + 2.0 * progress * norm_pr);

    // Penalize large dead space more aggressively as the stream matures
    score += 0.8 * norm_pr * norm_pr * (1.0 + progress);

    // Reward tight fits: subtract when post_residual is small
    score -= 0.5 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead coupling: penalize if the next item cannot use the leftover space
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 0.6 * (1.0 - pr / nxt.max(1.0)) * (0.5 + progress);
        } else {
            score -= 0.3 * (pr - nxt) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.5;
    }

    // Slight bias against opening new bins when many bins are open with slack
    if bin_residual == bin_capacity {
        score += 0.4 + 0.3 * (mean_residual / cap) + 0.2 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "small" residue class (post_residual < 10) are nearly perfect fits.
    let small_class = if post_residual == 0 { 3.0 } else if post_residual < 10 { 2.0 } else { 0.0 };
    score -= small_class * 6.0;

    // Modulo-10 harmony: leftover that is a multiple of 10 pairs well with
    // future items (sizes 1..100 commonly quantized in 10s).
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 4.0;
    }
    // Odd/awkward leftovers are penalized.
    if post_residual % 2 == 1 && post_residual > 0 {
        score += 2.0;
    }

    // Integer-division threshold classes on post_residual.
    let class = post_residual / 10; // 0..10 harmonic band
    score += class as f64 * 0.8;

    // Lookahead coupling: if the next item exactly fills the leftover,
    // strongly reward this bin (perfect chaining).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits: reward proportional to how well it uses leftover.
        let fill = next_item_size as f64 / post_residual as f64;
        score -= 8.0 * fill;
        // Harmonic check: post_residual - next_item_size stays in a good class.
        let chain = post_residual - next_item_size;
        if chain % 10 == 0 || chain < 10 {
            score -= 3.0;
        }
    } else if next_item_size > post_residual && post_residual < 10 {
        // Dead space too small for the next item: mild penalty only if
        // alternatives exist.
        score += 3.0 * (fitting_bins_count as f64).min(3.0);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin for a decent fit.
    if fitting_bins_count == 1 && post_residual < bin_capacity as f64 as u32 {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so that
    // good fits into existing bins win, but poor fits (large leftover in
    // an open bin relative to mean) push toward a fresh bin.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.9;
        // Early in the stream or few open bins: opening a bin is cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
        // If next item is large and current item is small, new bin is attractive.
        if next_item_size > 60 && item_size < 40 {
            score -= 8.0;
        }
    } else {
        // Penalize bins whose residual is far above the mean (hoarded space).
        let dev = bin_residual as f64 - mean_residual;
        score += 0.15 * dev.max(0.0);
    }

    // Mild pressure to consolidate when many bins are open.
    score -= 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0 * (1.0 - (post_residual as f64) / 20.0);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Prefer bins whose residual is "explained": post_residual close to bin fill ratio.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 25.0 * tightness;

    // Open-bin pressure: discourage spreading when many bins are open,
    // but encourage using existing bins when few are open.
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when pressure is high,
        // reward opening a bin only when it's early or nothing fits well.
        score += 20.0 + 8.0 * pressure;
    } else {
        score -= 5.0 + 3.0 * pressure.min(10.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item would be blocked by this placement's small gap, penalize.
    if next_item_size > post_residual && next_item_size <= post_residual + 10 {
        score += 12.0;
    }

    // Mean residual coupling: prefer bins near the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: bin closes exactly after next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Perfect 1-step match: bin closes exactly now.
    if post_residual == 0 {
        score -= 900.0;
    }

    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item still fits: reward tightness of the fit.
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space for the lookahead item: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 2.0 * waste;
        }
    } else {
        // Last item: prefer zero residual strongly.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        score += 300.0 + 3.0 * mean_residual;
    }

    // Mild pressure toward consolidating into fewer bins over time.
    score += 0.1 * open_bins_count as f64;
    score += 50.0 * (step_index as f64 / total_items.max(1) as f64);

    // Favor bins tighter than the mean residual (good packing).
    score -= 0.5 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (small post_residual).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness).powi(4);

    // Penalize dead space that cannot hold the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual as f64 / 100.0)).min(0.5);
        } else {
            score += 8.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    } else {
        // Last item: reward zero-waste placements heavily.
        score -= 20.0 * (1.0 - tightness);
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when fits are poor
    // or residuals across open bins are already fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fit = mean_residual / bin_capacity as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs() / 100.0;
        // Penalize new bin normally; discount penalty when open bins are fragmented.
        let penalty = 18.0 - 10.0 * fragmentation.min(1.0) - 5.0 * (1.0 - avg_fit);
        score += penalty.max(0.0) * (0.5 + 0.5 * progress);
    }

    // Mild preference for bins below mean residual (balance large gaps).
    score += 0.05 * ((bin_residual as f64 - mean_residual) / 100.0);

    // Slight pressure to consolidate as stream progresses.
    score += 0.02 * (open_bins_count as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual and its polynomial coupling with stream progress
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Smooth quadratic dead-space penalty: small residuals are punished super-linearly
    score += 30.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - progress);

    // Cubic interaction: tight fits favored more as stream progresses
    score -= 20.0 * (1.0 - pr_norm).powi(3) * progress;

    // Reward near-perfect fits (post_residual close to 0), smoothly
    score -= 15.0 * (-pr / 8.0).exp();

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: favor bins whose post-residual can host the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 5.0 * (1.0 - pr / cap);
    }

    // Crowding penalty: prefer spreading across many open bins mildly
    score += (open_bins_count as f64).ln() * 2.0 * pr_norm;

    // Deviation from mean residual: prefer bins near the mean, smooth Gaussian term
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) strongly rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty grows for residuals in "unusable" harmonic classes.
        // Small residuals (< 10) can never fit any future item -> heavy penalty.
        if post_residual < 10 {
            score += 60.0;
        }
        // Harmonic class: residual divisible by common item sizes is reusable.
        let divis = if post_residual % 10 == 0 {
            3.0
        } else if post_residual % 5 == 0 {
            2.0
        } else if post_residual % 2 == 0 {
            1.0
        } else {
            0.0
        };
        score -= 8.0 * divis;

        // Integer-division thresholds: residual in [10,20] band is fragile.
        let band = post_residual / 20; // 0: [0,20), 1: [20,40), 2: [40,60), ...
        score -= 3.0 * band as f64;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 250.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; mildly penalize wasting this bin's space.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // current item is large and open bins are fragmented (high mean residual).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // Prefer new bin when existing residuals are large (poor fits likely)
        // and the item is big; otherwise penalize new bins.
        let new_bin_bias = 40.0 * fragmentation + 0.5 * item_size as f64
            - 30.0 * (1.0 - progress);
        score += new_bin_bias;
        // Empty bin leaves residual = capacity - item_size; compare fairly.
        score += 0.1 * post_residual as f64;
    } else {
        // Prefer tighter bins overall: reward closeness of fit.
        let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 50.0 * fit_ratio;
    }

    // Slight preference for bins whose residual is below the mean (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 2.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward very tight fits (post_residual near zero but exact fill is best).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 10.0;
    }

    // Perfect-fit lookahead: if the next item exactly fills the post_residual,
    // strongly prefer this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Penalize if next item would be forced into a dead gap here.
    if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 12.0;
    }

    // Open-bin pressure: discourage spreading across many open bins;
    // encourage consolidation when few bins are open.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mean-residual coupling: if this bin is much tighter than average, prefer it.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate handling: an empty bin is only attractive when the fit
    // elsewhere would create dead space or no bin fits well.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        } else if post_residual < 10 {
            score -= 25.0; // dead space would be created elsewhere
        }
    }

    // Late-stream consolidation: near the end, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual closely
    // matches the next item size (perfect chain placement).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post >= next {
            // Next item fits here afterwards: reward tight match.
            let gap = post - next;
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item would not fit: penalize proportionally to overflow.
            score += 0.35 * (next - post);
        }
    }

    // Penalize dead space relative to mean residual of open bins.
    let post_f = post_residual as f64;
    if post_f > mean_residual {
        score += 0.25 * (post_f - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_f);
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current item is large and
    // no open bin offers a good fit; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.5 * (bin_capacity as f64 - item_size as f64);
        if next_item_size > 0 && (item_size as f64 + next_item_size as f64) <= bin_capacity as f64 {
            score -= 15.0; // pair fits fresh: opening a new bin is reasonable
        }
    }

    // Slight preference for tighter fits as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (bin_capacity as f64 - post_f) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness * (item_size as f64);

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize leaving dead space that no plausible future item can use.
    if post_residual > 0 && (next_item_size == 0 || (next_item_size as u32) > post_residual) {
        score += 8.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && (next_item_size as u32) == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin wastes residual elsewhere.
    if bin_residual == bin_capacity {
        // Prefer new bin only if existing fit is terrible (large post_residual)
        // or the item is large relative to capacity.
        let waste_pressure = (post_residual as f64) * 0.9;
        let crowding = (open_bins_count as f64).ln().max(1.0);
        score += 25.0 + waste_pressure - 5.0 * crowding;
        // Early in stream, slight preference for new bins to build diversity.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    } else {
        // Mild penalty for bins whose residual deviates far from the mean
        // (keeps a balanced portfolio of residuals).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Prefer bins with larger residual when item is large (avoid fragmentation).
    score -= 0.02 * (bin_residual as f64) * (item_size as f64) / 100.0;

    // Late in the stream, consolidate: penalize opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress * (1.0 - pr_norm);
    score += 40.0 * poly;

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 + 2.0 * progress) * 25.0;

    // Penalize dead space relative to mean residual of open bins
    score += ((pr - mean_residual) / cap).powi(3) * 15.0;

    // Lookahead: reward if next item fits the post residual, smoothly scaled
    if next_item_size > 0 {
        let fits_next = (pr - next_norm * cap).max(0.0) / cap;
        score -= (1.0 - fits_next) * next_norm * 10.0 * (0.5 + progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many bins early on
    score += open_bins_count as f64 * item_norm * (1.0 - progress) * 2.0;

    // New-bin candidate: encourage opening a new bin when item is large and fit is poor
    if bin_residual == bin_capacity {
        score = pr + 50.0 * (1.0 - item_norm) - 20.0 * item_norm * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction buckets
    let frac = post_residual as f64 / bin_capacity as f64;
    // Dead-space penalty grows non-linearly for small unusable residuals
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // nearly-full bin is excellent; reward via base low value
        } else {
            // penalize residuals that no typical item (1..100) can use well
            let worst_gap = (10..=100).map(|s| (post_residual as i64 - s as i64).abs()).min().unwrap() as f64;
            score += worst_gap * 0.5;
        }
    }

    // Modulo arithmetic on post_residual: harmonic alignment with common item sizes
    let harmonic_bonus = match post_residual % 10 {
        0 => 8.0,
        5 => 4.0,
        2 | 8 => 2.0,
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Integer division thresholds on post_residual: which item classes still fit
    let fits_next = next_item_size > 0 && post_residual >= next_item_size;
    if fits_next {
        score -= 12.0;
        // extra reward if post_residual exactly equals next item size (perfect pair)
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // reward if post_residual - next_item_size lands in a good harmonic class (<10)
        if next_item_size > 0 && post_residual - next_item_size < 10 {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        score += 10.0; // dead end for lookahead
    }

    // Capacity-fraction thresholds
    if frac <= 0.1 {
        score -= 20.0; // bin essentially closed
    } else if frac > 0.5 && frac < 0.9 {
        score += 6.0 * frac; // awkward middle residual
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer fresh bin when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity && bin_capacity == 100;
    if is_new_bin {
        if fitting_bins_count == 0 {
            score = -1000.0; // forced: must open new bin
        } else if mean_residual < item_size as f64 {
            score = 500.0; // open bins too full anyway
        } else {
            score = post_residual as f64 + 45.0; // discourage wasteful new bin
        }
    }

    // Slight preference to fill bins as stream progresses
    score -= (step_index as f64 / total_items.max(1) as f64) * (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical items are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable gap
        } else if post_residual < 20 {
            score += 25.0; // nearly unusable
        } else if post_residual < 35 {
            score += 8.0;  // marginal gap
        } else {
            score -= 5.0;  // still-flexible residual
        }
    } else {
        score -= 40.0; // perfect fit: zero waste, strongly rewarded
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Open-bin pressure: penalize using bins when many are already open,
    // encouraging consolidation rather than spreading items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
        score -= 12.0;
    }
    // If next item would leave the post-residual as dead space, penalize slightly.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (tighter bins) to keep loose bins available for large future items.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin
    // offers a decent fit (post_residual large) or under heavy bin pressure.
    if bin_residual == bin_capacity {
        let base_penalty = 25.0 + 0.3 * open_bins_count as f64;
        score += base_penalty;
        // Fresh bin is attractive if the item is large and would leave a
        // flexible residual, especially late in the stream.
        if item_size >= 50 {
            score -= 15.0 + 10.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead coupling: reward post_residual matching next_item_size ---
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        // Perfect chain fit: next item exactly fills the leftover space
        if diff < 0.5 {
            score -= 60.0 + 40.0 * (1.0 - progress);
        } else {
            // Penalize mismatch, stronger when the leftover is too small for the next item
            if post_residual < next_item_size {
                score += (next - post_residual as f64) * 0.9;
            } else {
                score -= 10.0 * (1.0 - diff / bin_capacity as f64);
            }
        }
        // Bonus if placing here leaves a gap the next item can partially exploit
        if post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 15.0;
        }
    }

    // --- Dead-space penalty: tiny unusable leftovers are bad ---
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }
    // Perfect closure is excellent
    if post_residual == 0 {
        score -= 50.0;
    }

    // --- Last-chance bin: strongly prefer using it rather than opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // --- Relative-to-mean-residual term: prefer bins tighter than average ---
    score += (mean_residual - post_residual as f64) * 0.3;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins would create bad fits
        // (large dead space) or few bins fit the item.
        let dead_space_risk = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        let pressure = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).clamp(0.0, 1.0)
        } else { 1.0 };
        // Base cost of a fresh bin: high, but reduced when open bins are nearly full
        score = 70.0 + 30.0 * (1.0 - pressure) + 40.0 * dead_space_risk;
        if fitting_bins_count <= 1 {
            score -= 55.0; // no good alternative exists
        }
        if next_item_size > 0 && next_item_size as f64 <= bin_capacity as f64 * 0.5 {
            score -= 5.0; // fresh bin can chain the next item well
        }
    }

    // Mild urgency late in the stream: consolidate into existing bins
    if progress > 0.7 && bin_residual != bin_capacity {
        score -= 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Core: prefer tight fits (small post_residual), scaled non-linearly.
    let mut score = (post_residual as f64).powf(1.35) / 10.0;

    // Waste ratio: fraction of bin that will be dead space after placement.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * waste_ratio * 40.0;

    // Perfect fit bonus: exact fill is always excellent.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Near-perfect fit bonus (dead space <= 5 is often unusable anyway).
    if post_residual > 0 && post_residual <= 5 {
        score -= 60.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 120.0 + 40.0 * progress;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    // (keeps future options open), penalize bins that would strand it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            score += 15.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
        // If next item fits exactly in post_residual, big bonus.
        if post_residual == next_item_size {
            score -= 90.0;
        }
    }

    // Compare against mean residual: placing into a bin that is already
    // tighter than average consolidates waste into fewer bins.
    let dev = bin_residual as f64 - mean_residual;
    score -= dev * 0.35;

    // New-bin candidate handling: opening a bin is expensive early and late.
    if is_new_bin {
        let open_cost = 300.0
            - 100.0 * (fitting_bins_count == 0) as i32 as f64
            + 60.0 * progress;
        // Penalize new bin when decent alternatives exist; reward when
        // the item fits poorly everywhere (large item, few fitting bins).
        let poor_alternatives = (fitting_bins_count == 0) as i32 as f64
            + (item_size > 60) as i32 as f64 * 0.5
            + (post_residual as f64 / bin_capacity as f64 > 0.25 && fitting_bins_count <= 1) as i32 as f64;
        score += open_cost - poor_alternatives * 350.0;
    } else {
        // Mild preference for filling bins that are already mostly full.
        let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= fullness * 45.0;
    }

    // Late-stream consolidation: as the stream ends, avoid spreading items.
    score += (1.0 - progress) * 10.0;

    // Many open bins: encourage packing into existing bins rather than
    // proliferating bins.
    score += open_bins_count as f64 * (if is_new_bin { 8.0 } else { -0.5 });

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling: post_residual shaped by progress
    let prn = pr / cap;
    let coupling = prn * (1.0 + 2.0 * progress * prn) * (1.0 + progress);
    score += 20.0 * coupling;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    let tightness = (1.0 - prn).powi(3);
    score -= 15.0 * tightness * (0.5 + progress);

    // Penalize bins whose residual deviates from mean residual (fragmentation)
    let dev = (br - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let fit_q = next_item_size as f64 / cap;
        score -= 8.0 * fit_q * (1.0 - prn);
    } else if next_item_size > 0 {
        // penalize leaving residual that nothing upcoming can use
        score += 6.0 * prn * (1.0 - (next_item_size as f64 / pr).min(1.0));
    }

    // Slight penalty for opening a new bin when many bins already open
    if bin_residual == bin_capacity {
        score += 3.0 + 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let mut score = pr as f64;

    // --- Harmonic class logic on post_residual ---
    if pr == 0 {
        // perfect fit: strongest reward
        score -= 60.0;
    } else {
        // Quarter-class of residual (integer division): lower quarter = tighter bin
        let quarter = pr / 25;
        score += quarter as f64 * 2.0;

        // Dead-space class: residual too small to ever hold next item
        if next_item_size > 0 {
            if (pr as u64) < next_item_size as u64 {
                // unusable sliver for the lookahead
                score += 6.0 + 0.15 * next_item_size as f64;
            } else {
                let gap = pr as i64 - next_item_size as i64;
                if gap == 0 {
                    // exact room for next item: excellent chaining
                    score -= 30.0;
                } else {
                    score += gap as f64 * 0.35;
                }
            }
        }

        // Modulo-10 harmonic classes: residuals in 1..=10 are near-dead space
        if pr <= 10 {
            score += (11 - pr) as f64 * 0.6;
        }
        // residuals that are exact fractions of capacity are more reusable
        if bin_capacity % pr == 0 {
            score -= 4.0;
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count == 0 {
            // no open bin can fit: must open new bin
            score -= 120.0;
        } else if fitting_bins_count == 1 {
            // last-chance bin exists: strongly prefer it over new bin
            score += 20.0;
        }
        // large items justify fresh bins more than small ones
        if item_size as f64 > cap * 0.5 {
            score -= 14.0;
        }
        if item_size as f64 > cap * 0.75 {
            score -= 8.0;
        }
    } else {
        // using the last bin that fits avoids opening a new bin
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
    }

    // Prefer fuller bins (less residual wasted overall)
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Stream progression: early stream, be pickier about fit quality;
    // late stream, consolidate aggressively into open bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += mean_residual * 0.02 * (1.0 - t);
    score -= t * 3.0;

    // Slight penalty proportional to open bins to discourage bin sprawl
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps heavily.
    // A residual gap is "dead" if no plausible future item (>=1..100) can use it well.
    if post_residual > 0 {
        if post_residual < 10 {
            // Tiny sliver: almost unusable dead space -> heavy penalty.
            score += 60.0;
        } else if post_residual < 20 {
            // Small gap: only very small items fit; risky.
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        }
    }

    // Reward near-perfect fits strongly (waste-free placement).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing ones
    // (penalize the new-bin candidate as open_bins_count grows).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when it enables a good future fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so we only open when existing bins fit poorly.
        score += 45.0 + 2.0 * open_bins_count as f64;
        // If the next item would fit perfectly in a fresh bin alongside current item,
        // opening a new bin becomes attractive.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let pair_left = bin_capacity - item_size - next_item_size;
            if pair_left <= 10 {
                score -= 55.0;
            }
        }
        // Early in the stream, opening bins is cheaper.
        score -= 25.0 * (1.0 - progress);
    } else {
        // Prefer bins whose residual stays large enough for the lookahead item.
        if next_item_size > 0 {
            if post_residual as f64 >= next_item_size as f64 {
                score -= 12.0;
            } else {
                score += 6.0;
            }
        }
        // Prefer bins tighter than average (good fits), but avoid extreme fragmentation.
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: exact fill is always ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: strongly favor bins whose post_residual
    // exactly matches the next item size (chain placement).
    if next_item_size > 0 {
        let look = next_item_size as f64;
        let diff = (post_residual as f64 - look).abs();
        if diff == 0.0 {
            score -= 400.0;
        } else if post_residual as f64 >= look {
            // Next item fits: reward tightness of the chain.
            score -= 200.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Dead space the next item cannot use: penalize proportionally.
            score += 50.0 * (1.0 - post_residual as f64 / look);
        }
    }

    // Favor bins with residual below the mean (tight bins get closed out).
    if (bin_residual as f64) < mean_residual {
        score -= 30.0;
    } else {
        score += 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize creating large unusable dead space relative to capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.0 && frac < 0.1 {
        score += 80.0; // tiny sliver is wasted capacity
    }

    // Early in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += tightness * 4.0;

    // Perfect fill: post_residual zero is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item exactly fills the post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item can still fit here: mild bonus proportional to leftover after next.
            let after_next = post_residual - next_item_size;
            score -= 10.0 - (after_next as f64) * 0.2;
        } else {
            // Next item won't fit here: penalize proportionally to wasted potential.
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible (large dead space).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 0.3 * (bin_residual - item_size) as f64;
    }

    // Penalize creating dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable slivers are wasted capacity
    }

    // Global state coupling: if mean residual is high, prefer consolidating
    // into bins with below-average residual (tighter bins).
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.25;

    // Time horizon: early in the stream, be more willing to spread items
    // (keep flexibility); late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0 * (1.0 - tightness.min(1.0));

    // New-bin candidate: only attractive when current bins are crowded
    // (high mean residual) or the item fits nowhere well.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let poor_fit = if fitting_bins_count == 0 { 0.0 } else { (bin_residual - item_size) as f64 };
        score += 30.0 - crowding * 45.0 + poor_fit * 0.1;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0; // fresh bin can host the next item too
        }
    }

    // Mild penalty for proliferating bins when many are already open.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual
    let p = progress;
    // Early phase: tolerate leftovers; late phase: punish dead space quadratically.
    let dead_penalty = x * x * (0.6 + 2.4 * p * p) * cap;
    score += dead_penalty;

    // Reward tight fits (small post_residual) with smooth saturating term.
    let tight_reward = (1.0 - x).powi(3) * cap * (0.35 + 0.35 * p);
    score -= tight_reward;

    // Exact-fill bonus via smooth Gaussian-like coupling.
    let exact = (-((pr * pr) / 4.0)).exp() * (8.0 + 12.0 * p);
    score -= exact;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 25.0 * p;
    }

    // Lookahead: penalize if leftover can't fit next item (waste for k=2).
    if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) {
        let gap = (next_item_size as f64 - post_residual as f64).min(40.0);
        score += gap * (0.4 + 0.6 * p);
    } else if next_item_size > 0 {
        // Smooth reward if leftover still useful for next item.
        score -= 4.0 * (1.0 - ((post_residual as f64 - next_item_size as f64) / cap).abs());
    }

    // New-bin candidate: keep it moderately attractive only when fits are bad
    // or stream is early (building capacity pool).
    if bin_residual == bin_capacity {
        let bad_fit = (pr / cap); // = 1.0 for empty bin; use item fit signal instead
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let openness = (1.0 - p) * 20.0 + scarcity * 30.0;
        score = score * 0.0 + cap as f64 - openness + bad_fit * 0.0;
        score += (item_size as f64 / cap) * 5.0;
    }

    // Mild tie-break: prefer fuller bins relative to mean residual.
    score -= ((mean_residual - pr) / cap) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: mod-10 classes on capacity 100.
    let class = post_residual % 10;
    // Residuals that are "dead" (small, hard to fill) get penalized progressively.
    if post_residual > 0 {
        match class {
            0 => score -= 12.0,            // perfectly aligned residual (10,20,...)
            1 | 2 | 3 => score += 6.0,     // awkward slivers
            4 | 5 | 6 => score -= 3.0,     // decent mid-class
            _ => score += 2.0,             // 7,8,9 moderately awkward
        }
    } else {
        // Perfect closure is strongly rewarded.
        score -= 40.0;
    }

    // Integer-division thresholds: how many items of the lookahead size fit the residual.
    if next_item_size > 0 {
        let fits_next = post_residual >= next_item_size;
        if fits_next {
            let n = post_residual / next_item_size;
            score -= 8.0 * (n as f64).min(3.0);
        } else {
            score += 5.0; // residual too small for the next item: dead space risk
        }
        // Harmonic coupling: residual divisible by next item size is ideal.
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when current bins are crowded
    // or the fit here would create large dead space.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins by default; relax if mean residual is small (bins nearly full)
        // or if this bin would be the only fitting option.
        let mut penalty = 30.0 + 20.0 * (1.0 - progress);
        if mean_residual < 15.0 {
            penalty -= 40.0;
        }
        if fitting_bins_count == 0 {
            penalty -= 60.0;
        }
        // A fresh bin wastes capacity equal to (capacity - item) unless more comes.
        score += penalty;
    } else {
        // Mild preference for tighter existing bins (best-fit flavor).
        score += (bin_residual as f64) * 0.05;
        // Spread awareness: if mean residual is high, prefer bins below mean (tight ones).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // Early stream: keep bins open and flexible; late stream: close bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.3 && post_residual > 30 {
        score -= 4.0;
    }
    if progress > 0.7 && post_residual <= 10 && post_residual > 0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any post_residual that is nonzero but too
    // small to hold the next item is wasted space — penalize it heavily,
    // scaled by how "stuck" the gap is relative to the lookahead demand.
    if next_item_size > 0 {
        let gap = post_residual as f64;
        if gap > 0.0 && (next_item_size as f64) > gap {
            // Dead space: unusable for the lookahead item.
            let unusability = (next_item_size as f64 - gap) / bin_capacity as f64;
            score += 40.0 + 60.0 * unusability;
        }
        // If the next item fits exactly into the remaining gap, reward strongly.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // General dead-space floor: gaps below the minimum plausible item size
    // (1..100 unknown distribution, so use a conservative small-gap threshold).
    if post_residual > 0 && post_residual < 5 {
        score += 30.0;
    }

    // Perfect fit is the ideal placement.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bins pressure: mildly discourage spreading across many bins when
    // the mean residual is already low (bins nearly full anyway).
    if open_bins_count > 0 {
        let pressure = (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64);
        score += 3.0 * pressure;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Slight preference to place into existing (non-empty) bins over a new
    // empty bin, all else equal.
    if bin_residual < bin_capacity {
        score -= 2.0;
    }

    // Progress-aware tightening: later in the stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Brand-new empty bin candidate: mildly discourage unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 25.0;
        // If no other bin fits, opening a new bin is the only sane choice.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        return score;
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // 2-step lookahead: reward bins where the leftover after this item
    // can still accommodate the next item exactly-ish.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post >= nxt {
            let slack = post - nxt;
            // Perfect match is best; degrade quadratically with slack.
            score -= 30.0 * (1.0 - (slack / bin_capacity as f64));
            score -= (post - nxt).abs() as f64 * 0.15;
        } else {
            // Leftover too small for next item: penalize dead space.
            score += 10.0 + (nxt - post) * 0.2;
        }
    }

    // Tight fits are good: reward small post_residual relative to mean residual.
    let mean = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    score -= (mean - post_residual as f64) * 0.3;

    // Slight preference for using more-filled bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_capacity as f64 - bin_residual as f64) * (-0.05 + 0.05 * progress);

    // With many open bins, prefer consolidation into existing ones.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits: reward small post_residual non-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that nothing in the plausible size range can use.
    if post_residual > 0 {
        let unusable = (post_residual as f64 / bin_capacity as f64).powi(3);
        score += 25.0 * unusable;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 3.0;
        }
        // If next item fits perfectly after this placement, extra reward.
        if post_residual == next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bins attractive only when open
    // bins are badly fragmented or the item is large relative to residuals.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 {
            mean_residual / bin_capacity as f64
        } else {
            1.0
        };
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Open new bin when mean residual is small (poor fits elsewhere) or
        // when many bins are already open and residual space is scarce.
        let new_bin_bias = 30.0 * (1.0 - fragmentation) + 10.0 * progress;
        score = (bin_capacity - item_size) as f64 - new_bin_bias;
        // If only one bin fits and it's this new-bin call, discourage slightly.
        if fitting_bins_count <= 1 && open_bins_count > 0 {
            score += 12.0;
        }
    }

    // Mild global pressure: when many bins are open, prefer filling existing ones.
    score += 0.15 * open_bins_count as f64;

    // Prefer bins with residual close to mean (avoid extreme fragmentation).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in [0,1]
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Non-linear coupling: waste penalty grows as a smooth polynomial in progress.
    // Early in the stream, small residuals are acceptable (room to fill later);
    // late in the stream, dead space is increasingly costly.
    let norm_pr = pr / cap;
    let waste_curve = norm_pr * norm_pr * (1.0 + 2.0 * progress * progress);
    score += waste_curve * cap * 0.5;

    // Smooth interaction between post_residual and mean residual across open bins:
    // placing an item leaving a residual far below the mean creates fragmentation.
    let frag = (pr - mean_residual) / cap;
    score += frag * frag * cap * 0.3;

    // Reward tight fits (small post_residual) with a saturating non-linear bonus.
    let tight = 1.0 - norm_pr;
    score -= tight * tight * tight * 10.0;

    // Lookahead coupling: if the next item fits into the post-residual, reward it
    // smoothly; penalize if it nearly fits but not quite (near-miss dead space).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fill = nxt / cap;
            score -= fill * fill * 8.0 * (1.0 - progress * 0.5);
        } else {
            let miss = (nxt - pr) / cap;
            score += miss * miss * cap * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Many open bins: prefer consolidation into existing bins smoothly.
    let ob = open_bins_count as f64;
    score += (ob / (ob + 5.0)) * (pr / cap) * 6.0;

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity (then a fresh bin is a clean canvas).
    if bin_residual == bin_capacity {
        let size_ratio = item_size as f64 / cap;
        score += 12.0 - 20.0 * size_ratio * size_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: small leftovers are golden.
    // Class 0: post_residual == 0 (perfect close) -> huge reward.
    // Class 1: post_residual < 10 -> nearly perfect.
    // Class 2: post_residual divisible by 10 (common item sizes align).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 300.0 - (post_residual as f64) * 20.0;
    } else if post_residual % 10 == 0 {
        score -= 50.0;
    } else if post_residual % 5 == 0 {
        score -= 10.0;
    }

    // Penalize leftovers that no typical item can use: dead space classes.
    // post_residual in (0,10) already rewarded; penalize awkward middles.
    if post_residual > 50 {
        score += (post_residual as f64 - 50.0) * 0.8;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        // next item fits: mild reward scaled by tightness
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 120.0 - slack as f64 * 8.0;
        } else {
            score -= 20.0;
        }
    } else if next_item_size > 0 {
        // next item cannot fit here: penalize leaving a bin that blocks nothing anyway
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Prefer fuller bins (best-fit style): reward small residual relative to capacity.
    let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fullness * 30.0;

    // Harmonic threshold on bin_residual via integer division: bins with residual
    // in [item_size, item_size+9) are "exact class" fits.
    if bin_residual >= item_size && (bin_residual - item_size) < 10 {
        score -= 80.0;
    }

    // Early in stream, be conservative: keep bins mergeable (avoid tiny residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 5 && progress < 0.5 {
        score += 15.0;
    }

    // New-bin candidate: make it unattractive unless it's genuinely better.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin only wins when open bins score poorly.
        score += 40.0;
        // If many bins open and mean residual is high, opening fresh is fine.
        if mean_residual > 40.0 {
            score -= 30.0;
        }
        // No next item known: closing out, new bin neutral.
        if next_item_size == 0 {
            score -= 20.0;
        }
    }

    // Mild tie-breaker: fewer open bins is better (consolidation).
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible item (<= 12) are pure waste. Penalize hard.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 + (12 - post_residual) as f64 * 4.0;
    }
    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 100.0;
    }
    // Residual large enough to host a typical future item is acceptable;
    // mildly reward keeping gaps in the "usable" band (12..40).
    if post_residual >= 12 && post_residual <= 40 {
        score -= 8.0;
    } else if post_residual > 40 {
        // Large leftover: mostly fine unless bin was nearly full already.
        score -= 2.0;
    }

    // Reward tight fits relative to bin residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins when a new
    // bin could consolidate, but only mildly so tight fits still win.
    score += 1.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise the item forces a new bin anyway.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate logic: an empty bin is attractive when no existing
    // bin fits well, or when mean residual across open bins is small.
    if bin_residual == bin_capacity {
        // Base mild penalty so a decent existing fit wins over opening.
        score += 25.0;
        // But if open bins are nearly full on average, opening is good.
        score -= mean_residual * 0.6;
        // If the next item is large and this item would leave a bad gap,
        // opening a fresh bin preserves flexibility.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 20.0;
        }
        // Late in the stream, prefer reusing bins to cap total count.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Lookahead: if this placement leaves exactly room for the next item,
    // reward chaining.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize placements that strand space smaller than the next item
    // while larger than the minimum (unusable for the known future).
    if next_item_size > 0 && post_residual >= 12 && post_residual < next_item_size.min(40) {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the post-residual (perfect 2-step chain).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize leaving residual too small for next item (dead space risk)
        if post_residual < next_item_size && post_residual > 0 {
            score += 15.0;
        }
    } else {
        // Last item: prefer tightest fit
        score += 5.0;
    }

    // Prefer bins whose residual is close to the mean (avoid fragmenting outliers)
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Reward using bins that would otherwise be wasted (low residual relative to item)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize opening a new bin when open bins fit well, especially early in the stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 40.0 * (1.0 - progress);
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size {
            score += 50.0; // an open bin can chain the next item; don't open new bin
        }
    }

    // Slight preference to keep number of open bins manageable
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits (small post-residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 30.0;

    // Reward using bins that would otherwise be "dead" (small residual that
    // few future items can use anyway).
    if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin, but less when
    // the item is large relative to capacity (hard to place later) or when
    // the lookahead item would pair poorly with the residual this item leaves.
    if bin_residual == bin_capacity {
        let mut open_penalty = 35.0;
        // Large items are valuable to place in a fresh bin.
        if item_size > bin_capacity / 2 {
            open_penalty -= 20.0;
        }
        // Lookahead synergy: if next item fits exactly into post_residual,
        // opening a new bin is great.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 15 {
                open_penalty -= 30.0;
            }
        }
        // Early in the stream, keep bins open to allow future pairing.
        let progress = step_index as f64 / total_items as f64;
        open_penalty += (1.0 - progress) * 10.0;
        // Many open bins: prefer packing into existing ones.
        open_penalty += (open_bins_count as f64) * 2.0;
        score += open_penalty;
    } else {
        // Existing bin: bonus for leaving a residual the next item can use.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        // Penalize bins whose residual deviates badly from the mean
        // (prefer to drain bins with unusually large residuals).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.3;
    }

    // Mild global pressure: when many bins are open relative to items seen,
    // encourage consolidation into existing bins.
    if open_bins_count > 0 {
        let ratio = open_bins_count as f64 / (step_index as f64 + 1.0);
        if bin_residual != bin_capacity {
            score -= ratio * 5.0;
        }
    }

    // Endgame: as the stream nears its end, residual space is wasted value;
    // fill whatever fits.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.9 && bin_residual != bin_capacity {
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual in (0,1]
    let pr = post_residual as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling: post_residual scaled by progress-dependent factor.
    // Early in the stream, prefer filling bins loosely; later, penalize large residuals harder.
    let poly = 1.0 + 1.6 * progress * progress - 0.6 * progress;
    score *= poly;

    // Smooth quadratic dead-space penalty for large unusable residuals
    score += 3.0 * pr * pr * bin_capacity as f64;

    // Tight fit reward: subtract smoothly when post_residual is small
    score -= 4.0 * (1.0 - pr) * (1.0 - pr) * (1.0 - pr) * item_size as f64 * 0.05;

    // Last-chance bin bonus (only fitting bin): reward smoothly
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Lookahead coupling: reward residual that can still host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 2.0 + 3.0 * (next_item_size as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        score += 1.5 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Slight preference against opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 2.0 + 0.3 * open_bins_count as f64 * (1.0 - progress);
    }

    // Mean-residual coupling: bins far from mean get gentle penalty
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: mod-10 buckets capture "waste class"
    let waste_class = post_residual % 10;
    score += waste_class as f64 * 0.8;

    // Perfect fit reward: post residual in {0, 5, 10} are reusable sizes
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual % 25 == 0 {
        score -= 15.0;
    }

    // Integer-division threshold: small post residuals are dead space
    let dead = post_residual / 20; // 0..5 classes
    score += dead as f64 * 3.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score += gap as f64 * 0.3;
            // harmonic check: next item leaves another clean residual
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 8.0;
            }
        } else {
            // next item won't fit here; penalize mildly, worse for large overflow
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets neutral baseline
    if bin_residual == bin_capacity {
        // opening a new bin: cost grows with number of open bins and stream progress
        score = bin_capacity as f64
            + open_bins_count as f64 * 2.0
            + (step_index as f64 / total_items.max(1) as f64) * 20.0;
        // but if no open bin fits well, allow new bin
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mean residual coupling: prefer bins far from mean (extreme fits)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev * 0.1;

    // Progress-based tightening: later in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - post_residual) as f64 * 0.2 * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any plausible future item
    // (min item size 1, but practically small gaps) are heavily penalized.
    let dead_zone = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 8.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight-fit reward: fraction of bin used by this placement
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 20.0;

    // Open-bin pressure: discourage opening new bins when many bins are open
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost, softened when few bins open
        score += 15.0 + 3.0 * open_bins_count as f64;
        // if only one fitting bin exists, opening a new bin is less attractive
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    } else if fitting_bins_count == 1 {
        // last-chance bin: strongly favor using it
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // If next item would fit, mild reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // Mean residual coupling: prefer bins deviating below mean residual
    // (placing into emptier-than-average bins keeps tight bins for tight items)
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Stream progression: early on, be more willing to open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is highly desirable.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward tight match of post_residual with next item size.
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);

        // Exact match for the next item: extremely strong reward.
        if post_residual == next_item_size {
            score -= 100.0;
        }
        // Post-residual too small for next item: penalize dead space that
        // cannot serve the lookahead item.
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize very small unusable dead space (fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Compare against mean residual: prefer bins with residual below average
    // (tighter bins get filled first, keeping looser bins flexible).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin fits well;
    // make empty bin slightly unattractive by default.
    if bin_residual == bin_capacity {
        score += 25.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // forced new bin
        }
    }

    // Early in the stream, allow slightly more freedom to open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (best-fit core).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * 8.0;

    // Reward near-exact fills aggressively.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item won't fit here: mild penalty for leaving a residual that
            // can't chain, scaled by how "dead" the residual is.
            let deadness = post_residual as f64 / (bin_capacity as f64);
            score += 6.0 * deadness;
        }
    } else {
        // Last item: prefer the bin that ends up fullest.
        score -= 20.0;
    }

    // Last-chance bonus: this is the only open bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; modulated by stream progress and
        // how fragmented the existing bins are.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut open_cost = 55.0;

        // Late in the stream, opening new bins is less costly (fewer future items
        // to fill them); early on, avoid bin proliferation.
        open_cost *= 1.0 - 0.5 * progress;

        // If existing bins are fragmented (high mean residual relative to item),
        // opening a new bin is more attractive.
        if mean_residual > item_size as f64 * 2.0 {
            open_cost -= 10.0;
        }

        // If only one bin fits and it's very loose, opening fresh may be better.
        if fitting_bins_count <= 1 && post_residual > 30 {
            open_cost -= 15.0;
        }

        score = open_cost + post_residual as f64;
    }

    // Mild penalty for using bins that are already nearly full when many
    // alternatives exist (keep big residuals for big future items).
    if bin_residual > item_size && bin_residual < item_size + 10 && fitting_bins_count > 2 {
        score += 5.0;
    }

    // Small regularization: prefer consolidating into fewer bins when many open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // smooth non-linear coupling of post_residual with stream progress
    let coupling = (norm_pr * norm_pr) * (1.0 + 2.0 * progress) - 0.5 * (norm_pr * (1.0 - progress));
    score += 60.0 * coupling;
    // penalize large residual later in stream (dead space)
    score += 40.0 * norm_pr * norm_pr * progress;
    // reward tight fits, more so early
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }
    // lookahead: reward leaving room for next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let diff = pr - ni;
        if diff >= 0.0 {
            score -= 15.0 * (diff / cap);
        } else {
            score += 10.0 * (-diff / cap);
        }
    }
    // mild penalty for many open bins with high mean residual
    score += 0.5 * (open_bins_count as f64) * (mean_residual / cap - norm_pr).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // "dead" classes via integer division thresholds on capacity.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class boundaries (harmonic fractions of capacity)
    let dead = pr <= 0.0;
    let tiny = pr > 0.0 && pr <= 10.0;          // only 1..10 items fit
    let small = pr > 10.0 && pr <= 25.0;        // awkward zone
    let medium = pr > 25.0 && pr <= 50.0;       // half-bin class
    let large = pr > 50.0;                      // more than half free

    if dead {
        score -= 60.0; // perfect fill, strongly prefer
    } else if tiny {
        score -= 25.0; // near-perfect, but not exact
    } else if small {
        // dead-space zone: penalize unless next item fits exactly
        score += 15.0;
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 20.0;
        }
        if next_item_size > 0 && (next_item_size as f64) > pr {
            score += 10.0; // next item won't reuse this leftover
        }
    } else if medium {
        score -= 5.0;
        // reward if next item consumes a harmonic chunk (>= half of leftover)
        if next_item_size > 0 && (next_item_size as u32) * 2 >= post_residual {
            score -= 12.0;
        }
    } else {
        // large leftover: this bin stays flexible, mildly neutral
        score += 3.0;
    }

    // Tightness reward: fraction of bin consumed by this placement
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * fill;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer the tighter fit among many candidates
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Prefer filling bins whose residual deviates below the mean (consolidation)
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Late in the stream: consolidate aggressively, avoid new half-empty bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if large && progress > 0.7 {
        score += 10.0 * progress;
    }

    // Exact harmonic hit: post_residual is an exact divisor-class multiple of 10
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit even the
    // smallest item (<= 10) are pure waste; penalize them extra hard.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Near-perfect fits are gold: reward tight packing.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness * tightness;

    // If leftover can exactly accommodate the lookahead item, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 30.0;
        } else {
            score -= 12.0 * (1.0 - gap as f64 / 100.0);
        }
    } else if next_item_size > 0 {
        // Lookahead won't fit here; mild penalty if this bin becomes dead.
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, modulated by pressure.
        score = 55.0 + 2.0 * open_bins_count as f64;
        // If this is the only fitting option, opening is fine.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Early in stream, tolerate new bins more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // If mean residual of open bins is large, prefer reusing them.
        score += 0.4 * mean_residual;
        // If lookahead fits a fresh bin perfectly, boost new-bin appeal.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Open-bin pressure: with many bins open, favor consolidating into
    // existing bins rather than spreading out.
    if bin_residual != bin_capacity {
        score += 0.15 * open_bins_count as f64;
        // Penalize bins whose residual deviates wildly from the mean
        // (isolated hoarded space) unless this placement fixes it.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.1 * dev;
    }

    // Small absolute bonus for exact fills.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled mildly.
    score *= 1.0;

    // Aggressive 2-step lookahead: perfect match of next item into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // exact two-item closure
        } else if next_item_size <= post_residual {
            // next item fits; reward small leftover after the pair
            let pair_left = post_residual - next_item_size;
            score -= 20.0 - (pair_left as f64) * 0.3;
        } else {
            // next item won't fit here: penalize large stranded residuals
            let stranded = post_residual as f64;
            score += stranded * 0.25;
        }
    }

    // Relative to mean residual: bins already tighter than average are good targets.
    let rel = post_residual as f64 - mean_residual;
    score += rel * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and no bin fits well (post_residual would be tiny in a fresh bin anyway).
    if bin_residual == bin_capacity {
        // Fresh bin residual after placement = capacity - item_size; make it
        // attractive only when the item is big (would leave most open bins wasted).
        score += 25.0;
        if item_size >= 60 && (next_item_size == 0 || next_item_size > (bin_capacity - item_size)) {
            score -= 35.0;
        }
        // Early in stream, slightly discourage hoarding many bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 5.0;
    }

    // Mild pressure to prefer bins among many fitting options with least waste.
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post_residual as f64;

    // Reward tight fits proportionally to item size (big items placed tightly are valuable)
    score -= 0.6 * (item_size as f64 / bin_capacity as f64);

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 12.0; // near-perfect fit, dead space is negligible
    }

    // Lookahead coupling: if the next item fits the post-residual, this placement chains well
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 4.0 + 0.05 * (post_residual - next_item_size) as f64;
        } else {
            // creates dead space relative to lookahead
            score += 1.5 + 0.08 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Prefer the fullest bin among open bins (smallest residual relative to mean)
    score -= 0.35 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: penalize mildly; allow early in the stream or when fit is loose
    if bin_residual == bin_capacity {
        let loose_fit = post_residual as f64 / bin_capacity as f64;
        score += 6.0 + 12.0 * (1.0 - progress) * (1.0 - loose_fit);
    }

    // Mild penalty for spawning many open bins late in the stream
    if open_bins_count > 4 {
        score += 0.02 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;

    // Smooth polynomial coupling of post_residual with progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (0.5 - progress);

    let mut score = pr * (1.0 + 0.8 * poly);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 8.0 * (1.0 - progress) * (next_item_size as f64 - pr) / cap;
    }

    // Reward tight fits and last-chance bins
    score -= (fit * fit) * 6.0;
    if fitting_bins_count == 1 {
        score -= 4.0 * (1.0 - progress);
    }

    // Mild preference to reuse existing bins vs opening new ones
    if bin_residual == bin_capacity {
        score += 3.0 + 2.0 * (1.0 - progress) + 0.5 * (open_bins_count as f64).sqrt();
    }

    // Smooth mean-residual coupling
    score += 0.05 * (mean_residual - pr) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets (eighths of capacity) and reward small ones.
    let eighth = bin_capacity / 8;
    let class = post_residual / eighth; // 0..=8
    let class_bonus: f64 = match class {
        0 => 40.0,                       // near-perfect fit
        1 => 26.0,                       // tiny dead space
        2 => 14.0,
        3 => 6.0,
        4 => 0.0,
        5 => -4.0,                       // half-empty: mildly penalize
        6 => -8.0,
        7 => -12.0,
        _ => -16.0,                      // nearly empty bin placement
    };
    score -= class_bonus;

    // Modulo coupling: leftover divisible by small sizes is reusable.
    let r = post_residual;
    if r > 0 {
        if r % 10 == 0 { score -= 8.0; }
        else if r % 5 == 0 { score -= 4.0; }
        if r % 3 == 0 { score -= 2.0; }
        // Dead space that no plausible item (1..=100) can ever use well:
        if r < 10 { score += 12.0 * (10 - r) as f64; }
    }

    // Lookahead: prefer leaving room for the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect two-item chain
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 12.0 - (slack as f64).min(12.0) * 0.5;
            if slack % 10 == 0 { score -= 4.0; }
        } else {
            // next item cannot reuse this bin's leftover
            score += 10.0;
        }
    } else {
        // last item: any residual is pure waste; minimize it harder
        score *= 1.5;
    }

    // Last-chance bin before opening a new bin: reward using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // early in the stream or when existing residuals are all tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = 1.0 - (mean_residual / bin_capacity as f64);
        score = 55.0 + 60.0 * progress - 40.0 * tightness;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big next item: fresh bin useful
        }
    }

    // Many open bins: prefer consolidating into existing ones.
    score += (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: unusable gaps are worse the smaller they are.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 20.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, prefer tightening fills
    // (low post_residual) rather than spreading items.
    let pressure = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)).sqrt();
    score += pressure * post_residual as f64 * 0.5;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }
    // Penalize leaving a gap that only a tiny item could use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // New-bin candidate: give it a moderate baseline score so it wins only
    // when existing bins are poor fits (their dead-space penalties push them up).
    if bin_residual == bin_capacity {
        score = 70.0 + (open_bins_count as f64).sqrt() * 5.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0;
        }
    }

    // Early in the stream, slightly prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = post_residual as f64 / (bin_residual as f64).max(1.0);
    score += tightness * 30.0;

    // Aggressive 2-step lookahead: reward if next item fits the post residual exactly or near-exactly
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            // Perfect 2-step completion: strong reward
            score -= 60.0;
        } else {
            // Partial lookahead match, scaled by how close
            let match_frac = 1.0 - (gap as f64) / (post_residual as f64).max(1.0);
            score -= match_frac * 25.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here: penalize leaving residual that is too small to be useful
        if post_residual < 10 {
            score += 20.0; // dead space penalty
        }
    }

    // Relative to mean residual: prefer bins whose post residual is below mean (consolidating)
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin offers a good fit
    if bin_residual == bin_capacity {
        // Base penalty so new bins are not opened casually
        score += 25.0;
        // But if next item is large and current fitting options are poor, soften
        if next_item_size > 60 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // Late in the stream, opening fresh bins is less wasteful
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    }

    // Prefer filling bins that are already quite full (low residual)
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let item = item_size as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = post;

    // Reward tight fits strongly (small post_residual wins).
    score -= (1.0 - post / cap) * 40.0;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 1.0 {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (1.0 - (post - nxt) / cap);
        } else {
            // next item won't fit here; mild penalty proportional to waste
            score += 10.0 * (1.0 - post / cap);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 3 {
        score += 3.0 * (fitting_bins_count as f64 - 3.0);
    }

    // Late in the stream, consolidate: prefer bins with small residuals relative to mean.
    score += t * (resid - mean_residual) * 0.5;

    // Early in the stream, allow spreading to new bins; later, discourage new bins.
    let new_bin = (bin_residual as u32 == bin_capacity) && item_size <= bin_residual;
    if new_bin {
        // Base penalty so a new bin is chosen only when fits are poor.
        score += 45.0 - 30.0 * t;
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 20.0;
        }
    }

    // Prefer bins whose residual is close to the item (minimize fragmentation).
    score += (resid - item) * 0.2;

    // Slight pressure against accumulating many open bins.
    score += open_bins_count as f64 * 0.3 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: minimize leftover, with quadratic penalty on small-but-nonzero waste
    let mut score = pr * (1.0 + 2.0 * norm_pr * (1.0 - progress));

    // Smooth non-linear coupling: large residuals late in stream are bad
    score += norm_pr * norm_pr * cap * (0.5 + progress);

    // Reward near-perfect fills smoothly
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness.powi(3);

    // Lookahead: bonus if next item fits the post residual exactly-ish
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let fits_next = if next_item_size as f64 <= pr { 1.0 } else { 0.0 };
        score -= 12.0 * fits_next * (-gap / 20.0).exp();
        // Penalize leaving a residual too small for anything useful
        score += 8.0 * (1.0 - fits_next) * (-norm_pr * 10.0).exp();
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Spread pressure: prefer bins far from mean residual (diversity of sizes)
    let dev = (pr - mean_residual) / cap;
    score -= 5.0 * dev * dev;

    // Mild penalty for many open bins late in stream
    score += open_bins_count as f64 * progress * 0.5;

    // New-bin candidate: keep it competitive only when no good fit exists
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - progress) - 10.0 * (fitting_bins_count as f64).recip();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into
    // capacity-fraction buckets. Leftovers in low classes (tiny slivers)
    // are nearly dead space; leftovers in high classes are reusable.
    let quarter = (bin_capacity / 4).max(1);
    let eighth = (bin_capacity / 8).max(1);
    let post_class = post_residual / quarter; // 0..=3 harmonic class
    match post_class {
        0 => score -= 12.0, // tiny sliver left: excellent packing, reward
        1 => score -= 5.0,  // quarter-ish leftover: still useful
        2 => score += 3.0,  // half-ish leftover: mediocre
        _ => score += 8.0,  // large leftover: wasteful placement
    }

    // Fine-grained harmonic residue: exact-fit modulo structure.
    // If post_residual is a multiple of a small unit (common item size
    // quantum), the leftover is likely reusable by future items.
    if post_residual > 0 && post_residual % eighth == 0 {
        score -= 4.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    }

    // Next-item lookahead coupling: strongly reward bins whose leftover
    // exactly accommodates the next item (harmonic chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            // penalize leftover that overshoots next item slightly
            score += (slack as f64) * 0.15;
        } else {
            // leftover too small for next item: dead-space risk grows
            score += (next_item_size - post_residual) as f64 * 0.08;
        }
    }

    // Integer-division threshold on residual vs mean: prefer bins whose
    // resulting residual stays near the fleet mean (balance residuals).
    let drift = (post_residual as f64 - mean_residual).abs();
    score += drift * 0.05;

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible (huge dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual <= quarter * 2 {
            score -= 20.0;
        } else {
            score -= 6.0;
        }
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin fits well (its raw score is high,
    // so subtract only when current item is large / stream is early).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / cap;
        // large items early: fresh bin is good (clean harmonic slate)
        let bonus = 30.0 * item_frac + 10.0 * (1.0 - progress);
        score -= bonus;
        // never open a new bin when a perfect/next-fit exists
        if post_residual == 0 {
            score -= 5.0;
        }
    }

    // Mild penalty per open bin to encourage consolidation.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize small unusable dead space (gaps < 10 can never be filled,
    // since items are >= 1 but tiny gaps waste capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    } else if post_residual < 20 {
        score += 120.0;
    }

    // Reward near-perfect fits (very low post_residual).
    if post_residual == 0 {
        score -= 300.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a
    // much better structure. Opening a fresh bin leaves full residual,
    // which is good only if existing bins would create dead space.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin, growing with number of open bins.
        score += 200.0 + (open_bins_count as f64) * 15.0;
        // If this is the only fitting bin among open ones, opening a new bin
        // is more acceptable (avoid forcing a bad fit).
        if fitting_bins_count <= 1 {
            score -= 250.0;
        }
        // If the next item is large and current mean residual is small,
        // a fresh bin may be needed anyway.
        if (next_item_size as f64) > mean_residual {
            score -= 60.0;
        }
    }

    // Dead-space coupling: if post_residual cannot fit the lookahead item,
    // penalize proportionally to how much capacity is stranded.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 3.0;
    }
    // Reward bins whose post_residual can exactly or nearly fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= ((post_residual - next_item_size) as f64).min(50.0) * 1.5;
    }

    // Open-bins pressure: when many bins are open, prefer consolidating into
    // existing bins rather than spreading; penalize bins that deviate from mean.
    if open_bins_count > 3 {
        score += (open_bins_count as f64 - 3.0) * 4.0;
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // Slight preference for tighter bins overall.
    score += (bin_capacity - bin_residual) as f64 * 0.3;

    // Late in the stream, be more aggressive about filling bins completely.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let next = next_item_size as f64;
    let post = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // ---- Aggressive 2-step lookahead matching ----
    if next_item_size > 0 {
        if (post - next).abs() < 0.5 {
            // Perfect chain: leftover exactly matches the next item
            score -= 18.0;
        } else if post >= next {
            // Leftover can host the next item; reward closeness of the match
            score -= 6.0 * (1.0 - (post - next) / cap);
        } else {
            // Leftover too small for the next item: penalize the unusable gap
            score += 0.35 * (next - post);
        }
    } else {
        // No lookahead available (last item): pure best-fit
        score -= 5.0;
    }

    // ---- Last-chance bin: strongly avoid opening a new bin ----
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0 + 0.1 * item_size as f64;
    }

    // ---- New-bin candidate handling ----
    if is_new_bin {
        // Penalize opening a new bin proportionally to how much room
        // remains in already-open bins (mean free fraction).
        let room = (mean_residual / cap).clamp(0.0, 1.0);
        score += 10.0 * room + 4.0;
        // Soften the penalty if the fresh bin's leftover also chains
        // with the next item (good future capacity).
        if next_item_size > 0 && post >= next {
            score -= 4.0;
        }
    }

    // ---- Mild stream-progression tie-breaker ----
    if total_items > 0 {
        score += 0.5 * (step_index as f64 / total_items as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that likely becomes unusable (items >= 1, so any residual is
    // technically usable, but tiny residuals waste capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive if the item fits poorly
    // everywhere else or the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let early = step_index as f64 / (total_items.max(1) as f64);
        let spread_pressure = (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64;
        // Penalize new bins mildly; reward when lookahead item is large (pairing potential).
        let mut new_bin_score = 30.0 + spread_pressure * 20.0;
        if next_item_size > 0 {
            let pair_waste = (bin_capacity - item_size - next_item_size.min(bin_capacity - item_size)) as f64;
            new_bin_score -= 0.25 * (bin_capacity as f64 - pair_waste);
            if next_item_size <= bin_capacity - item_size {
                new_bin_score -= 15.0;
            }
        }
        // Slightly cheaper to open new bins late in the stream (fewer future items to serve).
        new_bin_score -= 10.0 * early;
        score = new_bin_score;
    } else {
        // Lookahead synergy: reward placing into a bin whose post-residual matches next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else if next_item_size > post_residual as u32 && next_item_size > 0 {
            // Next item won't fit here; slight penalty for hogging residual.
            score += 4.0;
        }
    }

    // Global fragmentation pressure: when mean residual is low, conserve open bins tightly.
    let frag = 1.0 - (mean_residual / bin_capacity as f64);
    score += 6.0 * frag * (post_residual as f64 / bin_capacity as f64);

    // Prefer fuller bins overall (best-fit bias amplified by number of open bins).
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;
    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits (low post_residual) mildly; late, punish large residuals harder.
    let poly = base * base * (1.0 - base) * (1.0 - base);
    score += 40.0 * poly * (0.5 + progress);

    // Progress-scaled quadratic penalty on wasted space
    score += 15.0 * progress * base * base;

    // Reward filling bins nearly full, more strongly as stream advances
    score -= 20.0 * progress * (1.0 - base) * (1.0 - base);

    // Last-chance bonus: only bin that fits -> strong reward, smoothed by progress
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 25.0 * progress;
    }

    // Penalize opening new bins when many bins are open with slack
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64 + 5.0 * (mean_residual / cap);
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 30.0 * (1.0 - progress);
    } else if next_item_size > 0 && (next_item_size as f64) > pr {
        // next item won't fit here anyway; slight penalty if we leave awkward gap
        score += 5.0 * (pr / cap) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot band" does the leftover fall in?
    // Classes via integer division on capacity fractions (capacity=100 -> bands of 10).
    let band = (post_residual / 10) as f64;

    // Dead space penalty: residuals below the smallest item (<=10) are pure waste.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward residual sizes that form "harmonic" complements: a residual that many
    // typical item sizes can still fill is valuable. Residuals that are multiples
    // of 10 or 25 pair well with common item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual % 25 == 0 {
        score -= 8.0;
    }

    // Modulo-3 / modulo-7 style class coupling between post_residual and next item:
    // if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 30.0; // perfect pairing: bin closed next step
        } else if (post_residual - next_item_size) % 10 == 0 {
            score -= 15.0; // leaves a harmonic leftover again
        } else {
            score -= 6.0; // next item still fits
        }
    } else if next_item_size > 0 {
        // Next item cannot use this residual: penalize proportionally to how wasted it is.
        score += band * 2.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate logic: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer a new bin only when existing fits are poor (large post_residual waste)
        // or nothing else fits; otherwise bias against opening new bins.
        score += 55.0 + 0.15 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Mild pressure toward tight packing as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * band * progress;

    // Tie-break: prefer bins whose residual is close to the mean residual (keeps
    // the bin pool balanced and preserves large residuals for large items).
    score += 0.1 * ((post_residual as f64 - mean_residual).abs());

    // Exact-fit reward dominates everything.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0; // tiny gap: nearly unusable
        } else if post_residual < 25 {
            score += 25.0; // poor gap: fits only very small items
        } else if post_residual < 40 {
            score += 8.0; // moderate gap
        }
    } else {
        score -= 40.0; // perfect fit: strongly reward
    }

    // Reward tight fits relative to the bin residual (fill ratio).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill;

    // Pressure from number of open bins: discourage spreading into many bins
    // unless the fit is excellent.
    score += (open_bins_count as f64).sqrt() * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make a fresh bin moderately attractive only
    // when the item fits poorly everywhere else (large item, few fitting bins).
    if bin_residual == bin_capacity {
        let poor_fit = (fitting_bins_count as f64) <= 1.0 || item_size > 60;
        if poor_fit {
            score -= 15.0;
        } else {
            score += 35.0; // keep using open bins when fits are decent
        }
    }

    // Lookahead: if the next item fits into this bin's post-residual, reward;
    // if the next item would waste this bin, penalize slightly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else if post_residual > 0 && next_item_size > post_residual && post_residual < next_item_size {
            score += 5.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Late in the stream, prefer closing bins tightly (avoid leftover slivers).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for next item: strong reward.
        if post_residual == next_item_size {
            score -= 50.0;
        } else {
            score += diff * 0.6;
        }
        // Next item cannot fit here afterwards: penalize if bin would become near-dead.
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Dead-space penalty: residual too small to fit any plausible item (min size 1..10).
    if post_residual < 10 && post_residual > 0 {
        score += 30.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Last chance: only bin that fits -> strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate handling: neutral-ish baseline; only attractive when
    // no open bin offers a good fit (post_residual would be very small or huge waste).
    if bin_residual == bin_capacity {
        // Penalize opening new bins mildly; lookahead perfect match in a fresh bin is fine.
        score += 5.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Late in stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 8.0;
    } else {
        score += progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize time horizon
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight-fit reward: strongly favor bins where the item nearly fills residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space nonlinearly (waste grows superlinearly).
    let waste = post_residual as f64;
    score += 0.05 * waste * waste / bin_capacity as f64;

    // Lookahead: reward if the next item can fit into the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_quality = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 12.0 * chain_quality;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't chain here; penalize leaving awkward mid-size gaps.
        if post_residual > 0 && post_residual < 10 {
            score -= 5.0; // tiny gap is fine (near-perfect close)
        } else {
            score += 3.0;
        }
    } else if next_item_size == 0 {
        // Last item: close bins as tightly as possible.
        score -= 20.0 * fit_ratio;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if fit_ratio < 0.2 {
            score += 15.0; // terrible fit in the only candidate
        }
    }

    // New-bin candidate logic: an empty bin has high baseline residual; make it
    // attractive only when open bins are fragmented or fit is poor.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - waste).abs();
        // Prefer new bin when mean residual of open bins is small (they're full-ish)
        // or when this item is large relative to typical residual.
        let scarcity = 1.0 - (mean_residual / bin_capacity as f64).min(1.0);
        score -= 10.0 * scarcity;
        score += 0.5 * open_bins_count as f64 * (1.0 - t);
        // Late in the stream, avoid opening bins for small items.
        if item_size < 30 && t > 0.7 {
            score += 40.0 * t;
        }
        let _ = fragmentation;
    } else {
        // Prefer reusing bins with smaller residual (best-fit coupling), scaled
        // by global mean residual to avoid over-fragmentation.
        score += 0.3 * (bin_residual as f64 - mean_residual).abs();
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64 * (waste / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: quadratic-ish waste penalty on post residual
    let mut score = norm_pr * (1.0 + 0.8 * norm_pr) * 100.0;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on prefer tight fills (low post residual), later tolerate slack
    let progress_weight = 0.5 + 0.5 * (progress * std::f64::consts::PI).sin();
    score += norm_pr * norm_pr * progress_weight * 60.0;

    // Reward near-perfect fits with smooth saturating term
    let tightness = (-norm_pr * 12.0).exp();
    score -= tightness * 25.0;

    // Penalize bins whose residual deviates from mean residual (dispersion control)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.15 * dev * dev * cap;

    // Lookahead: reward residual that can fit next item smoothly
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let gap = ((post_residual as f64 - next_item_size as f64).abs()) / cap;
        score -= fits_next * 18.0 * (-gap * 6.0).exp();
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer it when open bins are crowded / residuals low
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / cap * 10.0);
        score += 20.0 + 0.5 * crowding - 40.0 * (1.0 - norm_pr);
        // at end of stream, opening fresh bins is fine
        score -= 30.0 * progress;
    }

    // Slight preference for fewer open bins
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: integer division into bands of 10.
    let pr = post_residual;
    let class = pr / 10; // 0..10

    // Reward small residuals (tight fits) non-linearly.
    score -= 12.0 * ((cap - post_residual as f64) / cap).powi(3);

    // Penalize residual classes that are historically hard to fill:
    // residuals of 1..9 are nearly dead; 10..19 moderately useful; 50 exactly half is fine.
    match class {
        0 => score += 18.0,           // 0..9: dead space
        1 => score += 6.0,            // 10..19
        2 => score += 2.0,            // 20..29
        3 => score -= 2.0,            // 30..39
        4 => score -= 4.0,            // 40..49
        5 => score -= 6.0,            // exactly-half sweet spot
        6 => score -= 3.0,
        7 => score -= 1.0,
        8 => score += 1.0,
        9 => score += 3.0,
        _ => {}                        // 100: new bin candidate
    }

    // Perfect fit: zero residual is ideal.
    if pr == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // chain perfect fit
        } else if next_item_size <= pr {
            // harmonic class match: next item leaves a "nice" residual again
            let next_post = pr - next_item_size;
            if next_post % 10 == 0 {
                score -= 10.0;
            }
            if next_post / 10 == 5 {
                score -= 6.0;
            }
            score -= 4.0 * (next_post as f64 / cap);
        } else {
            // next item cannot use this residual: penalize large leftovers
            score += 5.0 * (pr as f64 / cap);
        }
    } else {
        // last item: minimize leftover maximally
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make it attractive only when many bins exist
    // and the current fit is poor (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / cap; // = 1.0 for empty bin
        let pressure = (open_bins_count as f64 / 20.0).min(1.0);
        // Base new-bin score: moderately high so only chosen when open fits are bad.
        score = 40.0 + 25.0 * pressure - poor_fit * 0.0;
        // If item is large (>60), fresh bin is reasonable.
        if item_size > 60 {
            score -= 10.0;
        }
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.5 * open_bins_count as f64;

    // Mean-residual coupling: prefer bins whose residual is below mean (more filled).
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 && bin_residual != bin_capacity {
        score += 3.0 * ((bin_res_f - mean_residual) / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible follow-up item are pure waste -> heavy penalty.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    }

    // Tight fits are excellent: reward near-full packing.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Penalize leaving a gap that exactly neither helps nor hurts is neutral;
    // penalize large leftover space only mildly (score already = post_residual).

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.3;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // unattractive unless existing bins fit poorly (very small residuals).
    if bin_residual == bin_capacity {
        let best_existing = mean_residual.min(bin_residual as f64);
        // Base cost of a fresh bin.
        score += 60.0;
        // If all open bins are nearly full, opening a new bin is fine.
        if mean_residual < 20.0 {
            score -= 55.0;
        }
        let _ = best_existing;
    }

    // Lookahead: if next item would fit exactly into the post_residual,
    // reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // Next item cannot use the leftover: mild penalty proportional to waste.
        score += 3.0;
    }

    // Mild preference for bins below mean residual (balancing load).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item can't use the leftover space
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize leftover space far from mean residual (dead space)
    score += 0.4 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin bonus: avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: prefer it only when item is large relative to capacity
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Prefer tight fits early
    score += 0.2 * (post_residual as f64) * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (dead space penalty, quadratic).
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tight * tight;

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // mild reward proportional to how much of the residual the next item consumes
            let use_frac = (next_item_size as f64) / (post_residual as f64);
            score -= 12.0 * use_frac;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 6.0 * ((next_item_size - post_residual) as f64) / (bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Discourage spreading across many open bins when residuals are large.
    if open_bins_count > 1 {
        let spread = (open_bins_count as f64).ln();
        score += 3.0 * spread * (1.0 - (item_size as f64) / (bin_capacity as f64));
    }

    // Time horizon: early in the stream, be more open to new bins (explore);
    // later, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (1.0 - tight);

    // Prefer bins whose residual is below the current mean (keep mean residual balanced).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.15 * dev;

    // Slight preference for filling fuller bins overall.
    score -= 0.05 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = 1.0 + 0.8 * progress - 1.4 * progress * progress + 0.9 * progress * progress * progress;

    let mut score = pr * poly;

    // Reward tight fits, more strongly as stream progresses (smooth cubic coupling).
    let tight = (item_size as f64 / cap).powi(2);
    score -= 12.0 * tight * (0.5 + progress);

    // Penalize wasted residual via smooth non-linear term.
    score += 6.0 * norm_pr * norm_pr * (1.0 + progress);

    // Last-chance bonus: strongly favor the single fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead: reward bins whose post_residual fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 + 3.0 * progress;
    }

    // Mild penalty when bin residual deviates from mean residual (dispersion control).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs() * (1.0 - progress);

    // New-bin candidate handling: discourage opening new bins unless post_residual is large.
    if bin_residual == bin_capacity {
        score += 20.0 - 10.0 * progress + 8.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post residual: bins whose leftover is a "good"
    // modulus-compatible slot should be strongly preferred.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill is always best
    } else {
        // dead-space penalty grows super-linearly for small unusable slivers
        let frac = pr as f64 / cap;
        score += (1.0 - frac) * (1.0 - frac) * 40.0;

        // harmonic class: post_residual divisible by common item sizes
        if pr % 50 == 0 { score -= 25.0; }
        else if pr % 25 == 0 { score -= 18.0; }
        else if pr % 10 == 0 { score -= 12.0; }
        else if pr % 5 == 0 { score -= 8.0; }

        // integer-division thresholds: leftover too small for any plausible item
        if pr < 10 { score += 30.0; }
        else if pr < 20 { score += 12.0; }

        // lookahead coupling: does post_residual exactly fit next item?
        if next_item_size > 0 {
            if pr == next_item_size {
                score -= 35.0; // leaves a perfect slot for the next item
            } else if pr >= next_item_size && (pr - next_item_size) % 10 == 0 {
                score -= 15.0; // next item leaves a round harmonic class
            } else if pr < next_item_size && pr < 10 {
                score += 10.0; // dead sliver next item can't use
            }
        }
    }

    // tightness reward: filling a bin nearly full
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 20.0;

    // last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // new-bin candidate handling: only attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / cap;
        // penalize opening a new bin, more so early on and when bins are tight
        score += 45.0 + 30.0 * (1.0 - fragmentation) + 20.0 * progress;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 15.0; // big next item may justify a fresh bin
        }
    }

    // slight preference for bins below mean residual (keeps balance)
    if bin_residual as f64 > mean_residual {
        score += 4.0;
    } else {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual gap is "dead" if it's smaller than the smallest plausible item (1..100 unknown,
    // but treat gaps < ~10 as nearly dead, and gaps < item_size of next item as unusable).
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // tiny sliver: almost certainly dead space
        } else if post_residual < 25 {
            score += 18.0;
        }
        // Gap that cannot fit the lookahead item is less useful
        if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 30.0;
    }

    // Reward tight fits relative to bin capacity (low post_residual fraction)
    score += (post_residual as f64 / bin_capacity as f64) * 25.0;

    // Open-bins pressure: with many open bins, favor filling existing ones over opening new.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual != bin_capacity {
        // existing bin gets a discount growing with open bin count
        score -= pressure * 0.8;
    } else {
        // new-bin candidate: penalize more when many bins are already open
        score += pressure * 1.2;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Prefer bins whose residual deviates favorably from the mean (below-mean residual = tighter bin)
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    // Lookahead coupling: if this placement leaves exactly room for the next item, reward it
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the leftover exactly matches the next item's size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / bin_capacity as f64);
        // Perfect 2-step match: heavy bonus.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leftovers that are too small for the next item (dead space).
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: minimize waste.
        score += 10.0;
    }

    // Reward bins tighter than average (best-fit style), penalize looser ones.
    let rel = post_residual as f64 - mean_residual;
    score += 0.3 * rel;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin unless it's genuinely needed (many bins, large item).
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score += 15.0; // next item is bigger; keep open bins for it
        }
    }

    // Slight preference for filling fuller bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
