pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: penalize wasted space quadratically (dead space grows worse the smaller it is usable)
    let mut score = pr + 0.9 * (pr / cap).powi(2) * cap;

    // Smooth non-linear coupling with stream progress: early on, waste is cheap;
    // late in the stream, squeeze bins harder.
    let progress_weight = 0.35 + 1.15 * progress * progress;
    score *= progress_weight;

    // Lookahead coupling: reward bins whose post_residual can host the next item,
    // with a smooth saturating term.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let fit_frac = next_item_size as f64 / cap;
        score -= 6.0 * fit_frac / (1.0 + fit_frac);
    } else if next_item_size > 0 {
        // Penalize bins that strand the next item into a new bin
        score += 2.5 * (1.0 - (pr / cap));
    }

    // Last-chance bonus: only this bin fits the item — strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // Crowd penalty: many open bins with high mean residual -> prefer opening fresh bins
    // for large items; conversely reward compacting when bins are nearly full.
    let mean_gap = mean_residual - pr;
    score += 0.05 * mean_gap * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: keep it competitive but slightly conservative; its residual
    // equals capacity, so the quadratic waste term is large — soften it smoothly.
    if bin_residual == bin_capacity {
        let density = 1.0 - (item_size as f64 / cap);
        score -= 8.0 * density * (1.0 - progress);
        score += 1.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space?
    // Residuals that are multiples of common small sizes (5,10,20,25,50) are reusable.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -40.0 // perfect fit, strongly reward
    } else if pr % 25 == 0 {
        -12.0
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 5 == 0 {
        -4.0
    } else {
        6.0 // awkward leftover, penalize
    };
    score += harmonic_bonus;

    // Integer-division threshold: leftover <= 10 is nearly dead space.
    if pr > 0 && pr < 10 {
        score += 10.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Reward proportionally to how well next item nests here
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
            if (pr - next_item_size) % 10 == 0 {
                score -= 4.0; // nested fit leaves harmonic residual
            }
        } else {
            // Next item won't fit here; penalize more if the gap is small (wasted potential)
            let gap = (next_item_size - pr) as f64;
            score += 3.0 + 5.0 * (1.0 - gap / bin_capacity as f64);
        }
    } else {
        // Last item: just minimize residual
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate logic: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        score = 60.0 * (1.0 - pressure) + 50.0 * crowding;
        // If current item is large and next item large too, fresh bin can be good
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
        if step_index as f64 / total_items.max(1) as f64 > 0.9 {
            score += 5.0; // late stream: prefer filling existing bins
        }
    }

    // Mild preference for tight fits relative to bin fullness
    score += 2.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward residual that can still fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // This placement destroys room for the lookahead item.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // few open bins -> tolerate opening a new bin.
    let pressure = (open_bins_count as f64 / 8.0).min(3.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when few bins are open,
        // penalized when open-bin pressure is high.
        score = score * 0.5 - 10.0 + 18.0 * pressure;
    } else {
        score -= 4.0 * pressure;
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space relative to mean residual of open bins
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Aggressive 2-step lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain match: post_residual exactly equals next item size
            if post_residual == next_item_size {
                score -= 25.0;
            } else {
                score -= 10.0;
                // Smaller leftover after chaining is better
                score -= 0.3 * (post_residual - next_item_size) as f64;
            }
        } else {
            // Chaining impossible: penalize more if post_residual is small (dead space)
            score += 0.4 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current item is large and no good chaining exists
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size >= 60 {
            score -= 12.0; // big items deserve fresh bins
        } else {
            score += 10.0 + 5.0 * (1.0 - progress); // early stream: prefer filling open bins
        }
        // If many open bins exist, discourage spreading
        score += 1.5 * open_bins_count as f64;
    }

    // Tight fits are excellent: reward low post_residual strongly
    if post_residual < 10 {
        score -= 20.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: subtract more when post_residual is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Strong reward for near-perfect fits (post_residual <= 5).
    if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: penalize if next item fits well in this bin's post-residual
    // (chaining good placements), reward if next item would be blocked.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (post_residual as f64) >= ni {
            // next item can also fit here: good chaining
            score -= 6.0 * (ni / 100.0);
        } else if (bin_residual as f64) < ni {
            // next item can't fit here anyway; prefer conserving this bin? mild
            score += 2.0;
        }
        // if next item exactly matches post residual, big bonus
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 8.0;
        // late in stream, prefer reusing open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // if many open bins with large mean residual, avoid new bin
        score += mean_residual / 25.0;
    }

    // Penalize leaving very small unusable slivers (dead space 1..9) mildly.
    if post_residual > 0 && post_residual < 10 {
        score += 3.0;
    }

    // Global state: if few bins open relative to stream, encourage consolidation.
    if open_bins_count > 0 {
        score -= 2.0 / open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: prefer small post-residual, with a non-linear (quadratic) penalty
    // that grows super-linearly as wasted space increases.
    let mut score = pr + 0.9 * (pr / cap) * pr;

    // Smooth interaction: waste is more tolerable early in the stream,
    // less tolerable as the stream progresses (tighten packing over time).
    score += 6.0 * progress * (pr / cap) * (pr / cap) * cap;

    // Lookahead coupling: reward leaving a residual that the next item can use.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score -= 4.0 * (1.0 - gap / cap) * (nx / cap);
        // Extra reward for near-perfect two-item chain fits.
        if pr >= nx {
            score -= 2.0 * (1.0 - (pr - nx) / cap) * (1.0 - (pr - nx) / cap);
        }
    }

    // Mean-residual context: penalize bins whose residual deviates badly
    // from the fleet mean (keeps residual distribution compact).
    score += 0.5 * (pr - mean_residual).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, favor the tightest fit via post_residual (already encoded),
        // add mild diversity pressure scaled by open bins count.
        score += 0.15 * open_bins_count as f64 * (pr / cap);
    }

    // New-bin candidate: bin_residual == bin_capacity means an empty bin.
    // Make it mildly unattractive so existing bins are preferred, unless the
    // item is huge relative to capacity (poor fits elsewhere).
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * (it / cap);
        // Late in the stream, opening a fresh bin is cheaper than fragmenting.
        score -= 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Capacity fraction class of the post residual
    let frac = post_residual as f64 / bin_capacity as f64;
    // Harmonic classes: post_residual modulo 20 (common item-size divisibility class)
    let class = (post_residual % 20) as f64;

    // Reward small residuals, but strongly reward residuals that are "perfect" classes
    // (0, 10, 20, 25, 50, 75 are highly reusable dead-space levels).
    let reusable = match post_residual {
        0 => 60.0,
        10 => 40.0,
        20 => 35.0,
        25 => 30.0,
        50 => 25.0,
        75 => 20.0,
        _ => 0.0,
    };
    score -= reusable;

    // Penalize awkward dead space: residuals that are small but not tiny
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // nearly-unusable sliver
    }

    // Modulo-class coupling with next item: if next item fits exactly into post_residual,
    // big reward (perfect chain fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 - ((post_residual - next_item_size) % 20) as f64 * 0.4;
        } else {
            // next item cannot use this bin anyway; slight penalty for wasted space
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Tight-fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.85 {
        score -= 20.0 * fill_ratio;
    } else if fill_ratio < 0.25 && bin_residual < bin_capacity {
        score += 8.0; // dumping small item into big space
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad
    if bin_residual == bin_capacity {
        score += 45.0;
        // but if item is huge relative to typical residuals, new bin is fine
        if item_size as f64 > mean_residual + 10.0 {
            score -= 35.0;
        }
        // late in stream, fewer open bins: opening fresh bins is cheaper early
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Encourage balancing residual distribution across bins
    score -= (mean_residual - frac * 100.0) * 0.05;

    // Integer-division threshold shaping on post_residual
    score += (post_residual / 20) as f64 * 3.0;

    // Small class-based jitter to break ties deterministically
    score += class * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // minimum item are pure waste -> heavy penalty.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // perfect fit, huge reward via subtraction below
    }
    // Penalize "unusable small gaps": residuals below a threshold that future
    // items (sizes 1..100, unknown) are unlikely to exploit.
    let dead_threshold = 15u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 3.0 * (dead_threshold - post_residual) as f64;
    }

    // Reward tight fits.
    score -= 2.0 * (item_size as f64 / bin_capacity as f64) * (bin_capacity as f64 - post_residual as f64);

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive if the fit in open bins is bad
        // or next item won't benefit from leftover space.
        score += 12.0 * open_bins_count as f64;
        if next_item_size > 0 {
            // opening a fresh bin is good if the next item could use the
            // leftover of this bin's placement
            if post_residual >= next_item_size {
                score -= 8.0;
            } else if post_residual > 0 && post_residual < next_item_size {
                score += 4.0;
            }
        }
    } else {
        // mild bonus for keeping bins balanced with mean residual
        score += 0.05 * ((bin_residual as f64) - mean_residual).abs();
    }

    // Progression: as stream advances, be more conservative about new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tightest fit wins.
    score += 0.01 * bin_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item fill
        } else if post_residual >= next_item_size {
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit: penalize dead space relative to mean residual
            score += (post_residual as f64 - mean_residual).abs() * 0.5;
        }
    } else {
        // Last item: prefer minimal post residual.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize leaving residual that no typical small item can use (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mild pressure to close out bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (mean_residual / bin_capacity as f64);

    // New-bin candidate: keep it neutral-ish, only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        score += 20.0 - 15.0 * (mean_residual / bin_capacity as f64);
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual is already the base; amplify waste quadratically.
    let waste = post_residual as f64;
    score += 0.35 * (waste * waste) / bin_capacity as f64;

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space unusable by next item: penalize mildly.
        score += 3.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: opening a new bin should be discouraged unless it's a great idea.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 20.0;
        // If many bins fit the item, opening new bins is wasteful.
        if fitting_bins_count > 0 {
            score += 10.0 * fitting_bins_count as f64;
        }
        // If the item nearly fills a fresh bin alone, opening is fine.
        if item_size as f64 > 0.85 * bin_capacity as f64 {
            score -= 25.0;
        }
        // If next item is large and no open bin would hold it, opening a fresh bin
        // keeps a big residual around — slightly discourage.
        if next_item_size > 0 && next_item_size as f64 > 0.5 * bin_capacity as f64 {
            score += 5.0;
        }
    }

    // Time horizon: late in the stream, be more conservative (prefer filling existing bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.25 * progress;

    // Global state coupling: high mean residual means open bins are roomy; prefer them.
    if bin_residual < bin_capacity {
        score -= 0.05 * mean_residual;
    }

    // Small residual exact-fit reward.
    if post_residual < 5 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let fill = item_size as f64 / bin_capacity as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    let mut score = post_residual as f64;

    // Reward tight fits (large items into small residuals) via smooth coupling.
    score -= fill * (30.0 + 20.0 * progress);

    // Penalize large unusable post-residuals non-linearly (dead space grows quadratically).
    score += post_frac.powi(2) * 25.0;

    // Lookahead coupling: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_frac = next_item_size as f64 / bin_capacity as f64;
        score -= 6.0 + 14.0 * next_frac;
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // Next item would have fit here but won't after this placement: mild penalty.
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize early, allow late in the stream when residuals are fragmented.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + (mean_residual / bin_capacity as f64) * 10.0;
    }

    // Prefer bins whose residual is close to the mean (balanced consolidation).
    score += ((mean_residual - post_residual as f64) / bin_capacity as f64).abs() * 8.0;

    // Slight preference for consolidating into fewer bins as stream progresses.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Residuals in "dead" classes (too small for
    // typical items) are penalized super-linearly.
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let class_penalty = if pr == 0 {
        -60.0 // perfect fit: strong reward
    } else if pr < quarter / 2 {
        40.0 // tiny dead space, nearly unusable
    } else if pr < quarter {
        20.0
    } else if pr < half {
        0.0
    } else {
        -15.0 // roomy residual still useful
    };
    score += class_penalty;

    // Modulo arithmetic on post_residual: residuals congruent to small
    // remainders mod common item sizes tend to be fillable.
    let mod_bonus = if pr > 0 {
        let m10 = (pr % 10) as f64;
        let m20 = (pr % 20) as f64;
        -(20.0 - m10 * 2.0) * 0.5 - (10.0 - m20 * 0.5) * 0.3
    } else {
        0.0
    };
    score += mod_bonus;

    // Lookahead coupling: reward when post_residual exactly accommodates
    // the next item (chain fit), penalize when next item barely misses.
    if next_item_size > 0 {
        let nx = next_item_size;
        if nx <= pr {
            if pr - nx < quarter / 2 {
                score -= 25.0; // next item chains nearly perfectly
            } else {
                score -= 8.0;
            }
        } else if nx > bin_residual {
            // next item won't fit this bin regardless; residual class matters less
            score -= 3.0;
        } else {
            score += 12.0; // next item will strand this residual
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral-to-slightly-positive baseline so
    // it only wins when open bins are genuinely bad.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.1 * (open_bins_count as f64).sqrt();
    }

    // Stream progression: early on, prefer tight packing; late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (mean_residual - post_residual as f64) * 0.2;

    // Favor bins below mean residual (tighter than average).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize unusable small gaps heavily.
    // A residual that is too small to hold even the smallest item (size 1)
    // is pure waste; a residual too small for the lookahead item is likely waste.
    if post_residual > 0 {
        if post_residual < 10 {
            // Tiny unusable sliver -> strong penalty
            score += 40.0;
        } else if next_item_size > 0 && post_residual < next_item_size as f64 {
            // Cannot fit the next item -> probable dead space
            score += 18.0;
        }
    }

    // Reward near-perfect fits strongly (waste minimization)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidating
    // into existing bins rather than spreading items out.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += pressure * 10.0;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral baseline; only wins when existing bins
    // have poor fits. Give it a slight handicap so consolidation wins ties.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Late in the stream, opening fresh bins is less attractive
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
    }

    // Slight preference for bins tighter than the current average residual
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 0.5;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining: bin becomes exactly full
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how much of post_residual it consumes
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill;
        } else {
            // next item won't fit here: penalize leaving a gap smaller than next item (dead space)
            let gap = post_residual as f64;
            if gap < next_item_size as f64 {
                score += 0.35 * gap;
            }
        }
    }

    // Penalize bins far below mean residual (poorly utilized) mildly
    score += 0.15 * (mean_residual - post_residual as f64).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral-ish baseline, only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 30.0;
        // if many bins can fit, discourage opening a new one
        score += 8.0 * fitting_bins_count as f64;
    }

    // Late in stream: prefer closing bins tightly
    let progress = step_index as f64 / total_items as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual is much larger than the item
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Reward exact / near-exact fills
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 18.0;
    }

    // Lookahead: penalize residuals that the next item cannot use
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits well here -> reward proportionally
            let use_ratio = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * use_ratio;
        } else {
            // dead space for the next item -> penalize small residuals that waste capacity
            let waste = post_residual as f64;
            if waste < next_item_size as f64 {
                score += 4.0 * (1.0 - waste / next_item_size as f64);
            }
        }
    } else {
        // last item: prefer fullest packing
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count > 0 {
            (item_size as f64 / bin_capacity as f64).recip()
        } else {
            0.0
        };
        // mild penalty so open bins are preferred unless they leave big waste
        score += 6.0;
        // early in stream, opening bins is cheaper (more future items to fill them)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress) * pressure;
        // many open bins with large mean residual -> don't open another
        score += 0.6 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    } else {
        // penalize spreading across many bins when residuals are already large
        score += 0.3 * (mean_residual - post_residual as f64).abs() / bin_capacity as f64;
    }

    // Slight preference for bins with smaller current residual (best-fit bias)
    score += 0.05 * bin_residual as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling: base cost from post-residual, warped by progress
    let warp = 1.0 + 0.8 * progress - 0.4 * progress * progress;
    let mut score = pr * warp;

    // Non-linear penalty for awkward dead space (mid-range residuals)
    let dead = norm_pr * (1.0 - norm_pr);
    score += 12.0 * dead * (1.0 + progress);

    // Reward tight fits more strongly as the stream matures
    score -= (item_size as f64 / cap) * 8.0 * (0.5 + progress);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead synergy: if next item fits into post_residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - pr / cap) * (1.0 + progress);
    } else if next_item_size > 0 {
        score += 3.0 * (1.0 - pr / cap);
    }

    // New-bin candidate handling: prefer opening a new bin only when
    // open bins are cluttered (high mean residual) or late in stream
    if bin_residual == bin_capacity {
        let clutter = mean_residual / cap;
        score = 60.0 - 30.0 * clutter - 20.0 * progress - 2.0 * open_bins_count as f64 * 0.1;
        if item_size > 60 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of common small item sizes) are preferred.
    let pr = post_residual;
    if pr > 0 {
        // Penalize dead space that cannot be filled by typical small items.
        let dead = if pr < 10 { 60.0 } else if pr < 20 { 25.0 } else { 0.0 };
        score += dead;

        // Reward residuals divisible by small harmonic classes (5, 10, 20, 25, 50).
        let mut harmonics = 0u32;
        if pr % 5 == 0 { harmonics += 1; }
        if pr % 10 == 0 { harmonics += 1; }
        if pr % 20 == 0 { harmonics += 1; }
        if pr % 25 == 0 { harmonics += 1; }
        if pr % 50 == 0 { harmonics += 1; }
        score -= harmonics as f64 * 8.0;

        // Perfect fit is golden.
        if pr == 0 {
            score -= 200.0;
        }
    } else {
        score -= 200.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 150.0;
        } else if next_item_size <= pr {
            // Next item fits: reward proportional tightness.
            score -= 30.0 * (next_item_size as f64 / pr as f64);
            // Harmonic match between next item and post residual.
            if pr % next_item_size == 0 {
                score -= 25.0;
            }
        } else {
            // Next item won't fit here: mild penalty for stranding space.
            score += 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 150.0;
        // If many bins can fit, opening new is wasteful.
        if fitting_bins_count > 1 {
            score += 50.0 * (fitting_bins_count as f64 - 1.0);
        }
        // Late in stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Tight fits are better than loose ones: reward high fill ratio.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 40.0 * fill * fill;

    // Prefer bins with residual below mean (consolidating fuller bins).
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Mild preference for larger residual bins when many bins are open.
    score += 0.05 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (<= 10) are worthless — penalize them hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        // Small gaps are only mildly useful; add nonlinear penalty.
        score += (20.0 - post_residual as f64) * 1.5;
    } else {
        // Larger residual space retains value; reward keeping it.
        score -= (post_residual as f64 - 20.0).min(40.0) * 0.3;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 25.0;

    // Open-bin pressure: when many bins are open, prefer filling existing
    // bins over opening new ones; a new-bin candidate (residual == capacity)
    // gets penalized proportionally to open_bins_count.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 4.0;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // Prefer bins whose residual is below the mean (consolidating fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (item exactly fills the bin)
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when the next item fits snugly into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        if slack_after_next == 0 {
            // Perfect two-item chain: item + next item exactly fill the bin
            score -= 150.0;
        } else {
            // Reward tight chains, penalize leftover slack after the chain
            let tightness = 1.0 - (slack_after_next as f64 / bin_capacity as f64);
            score -= 40.0 * tightness;
        }
    } else if next_item_size > 0 {
        // Next item cannot use the residual: penalize dead space proportionally
        let dead = post_residual as f64;
        let usable_threshold = bin_capacity as f64 * 0.1;
        if dead < usable_threshold {
            score += 30.0 * (usable_threshold - dead) / usable_threshold;
        }
    }

    // Penalize small unusable residuals (< 10% capacity) to avoid dead space
    if post_residual > 0 && post_residual < bin_capacity / 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Relative to mean residual: prefer bins with below-average residual
    // (tighter bins first), unless it would create dead space
    score += (mean_residual - post_residual as f64) * 0.5;

    // Mild pressure to prefer filling existing bins over opening new ones
    // as the stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        // New bin candidate: penalize mildly unless residual is very small
        score += 15.0;
    }

    // Penalize opening new bins when many bins are already open and fit exists
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 20.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward filling the bin proportionally to how much of the residual is used.
    let fill_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 60.0 * fill_ratio * fill_ratio;

    // Penalize creating dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can hold the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 {
        score += 8.0 * (1.0 - (next_item_size as f64 / bin_capacity as f64));
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Time horizon: early in the stream, be conservative (prefer tight fits,
    // avoid new bins); late in the stream, allow more freedom.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * (1.0 - progress) * fill_ratio;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with slack -> encourage consolidating into
    // high-residual bins; few open bins -> slightly prefer new capacity.
    if bin_residual < bin_capacity {
        if (bin_residual as f64) > mean_residual {
            score -= 6.0;
        } else {
            score += 4.0;
        }
    }
    if open_bins_count > 8 {
        score += 2.0 * (open_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 {
            0.0
        } else {
            (fitting_bins_count as f64).ln() + 1.0
        };
        let wasted = (bin_capacity - item_size) as f64;
        score = 45.0 + desperation * 12.0 + wasted * 0.5 - 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 0.8 * progress * progress + 0.4 * progress);

    let mut score = poly * cap;

    // Penalize dead space relative to next item's needs (smooth interaction)
    let next = next_item_size as f64;
    if next > 0.0 {
        let gap = (next - pr).max(0.0) / cap;
        score += 6.0 * gap * gap * cap;
        // Reward when next item fits snugly
        let snug = (pr - next).max(0.0) / cap;
        score -= 3.0 * snug * (1.0 - progress);
    }

    // Last-chance bonus: smooth reward when few fitting bins
    let fit_term = (fitting_bins_count as f64).max(1.0);
    score -= 4.0 / fit_term;

    // Mild penalty for proliferating bins late in stream
    score += 0.05 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Deviation from mean residual: prefer bins near mean (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which "slot" of capacity/10 it falls in.
    let slot = (post_residual / 10) as f64;
    let rem = (post_residual % 10) as f64;
    score += rem * 0.8; // penalize ragged remainders that waste dead space

    // Reward tight fits: small post_residual strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 18.0;
    }

    // Modulo-class coupling: residual classes divisible by 5 are more reusable
    // for items in 10..80 range.
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
            // harmonic match: both in same decade slot
            if (next_item_size / 10) == (post_residual / 10) {
                score -= 8.0;
            }
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when few bins fit or residual is tiny.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap - 30.0 * pressure - 10.0 * (1.0 - progress)
            + 20.0 * (fitting_bins_count.min(4) as f64);
    } else {
        // Slightly prefer bins below mean residual (balance load) unless tight fit.
        if (post_residual as f64) > mean_residual && post_residual > 20 {
            score += 4.0;
        }
    }

    // Dead-space guard: residuals under 10 are nearly unusable (min item 1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits generally (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // If the leftover gap could fit the lookahead item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap too small for next item: penalize proportionally.
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += 2.0 * (open_bins_count as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: mildly penalize by default so it wins only when fits are bad.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if no good fit exists (large dead space everywhere), new bin is attractive.
        if post_residual == bin_capacity {
            score += (mean_residual / 10.0).min(20.0);
        }
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact chain fits
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0; // perfect 2-item chain fill
        } else if post_residual >= next_item_size {
            // next item fits; prefer residual just above next_item_size
            score -= 40.0 - (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // dead space relative to lookahead item
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Perfect closure of current bin
    if post_residual == 0 {
        score -= 150.0;
    }

    // Penalize leaving tiny unusable slivers (1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Discourage wasting very large residual bins on small items
    if item_size < bin_residual / 2 && bin_residual != bin_capacity {
        score += (bin_residual - 2 * item_size) as f64 * 0.2;
    }

    // Prefer tighter bins relative to mean residual of open bins
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Early in stream: slightly prefer reusing open bins over opening new ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline cost, adjusted by progress and open-bin load
        score += 10.0 + 30.0 * (1.0 - progress) - open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize dead space: small post_residuals are good, but a tiny unusable
    // leftover (<10) is fine since nothing can use it anyway.
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.1 * next_item_size as f64;
        } else {
            score += 4.0;
        }
    }

    // New-bin candidate handling: make an empty bin attractive only when existing
    // bins are mostly full or the fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        // Open a new bin when open bins are crowded; keep it costly early on.
        score += 15.0 + 40.0 * avg_fullness - 20.0 * progress;
        if item_size > 60 {
            score -= 10.0; // big items start fresh bins more readily
        }
    } else {
        // Slight preference for bins already below-average residual (balance load).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Late in the stream, consolidate aggressively into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tight = 1.0 - pr / cap; // how full the bin becomes

    // Base: prefer tight fits, penalize residual quadratically
    let mut score = pr * (1.0 + 0.5 * (1.0 - tight) * (1.0 - tight));

    // Smooth polynomial coupling of residual with stream progress:
    // early on, tolerate loose fits (future items may fill); late, demand tightness
    let prog_coupling = pr * (0.6 * progress * progress - 0.4 * progress + 0.2);
    score += prog_coupling;

    // Dead-space penalty: residuals too small for typical future items
    let dead = (cap * 0.2 - pr).max(0.0) / cap;
    score += 8.0 * dead * dead;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - tight);
    }

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 3.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 {
        score += 2.0 * (next_item_size as f64 - pr) / cap;
    }

    // Mild penalty when many bins already open (consolidate early)
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Deviation from mean residual: prefer bins near the mean (balanced packing)
    score += 0.5 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: penalize opening a fresh bin unless current fits are bad
    if bin_residual == bin_capacity {
        score += 12.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits strongly (small post_residual preferred).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Harmonic class of the leftover space: classify post_residual by
    // integer division into "usable" buckets for future items (sizes 1..100).
    // Buckets: [0..9] dead space, [10..19] tiny, [20..49] medium, [50..99] large.
    let bucket = post_residual / 25; // 0..4 harmonic class
    let bucket_penalty = match bucket {
        0 => 60.0, // near-perfect fill, but any waste is dead space
        1 => 15.0, // small gap fits only tiny items
        2 => 0.0,  // medium gap, generally reusable
        3 => -8.0, // large gap, very reusable
        _ => -10.0,
    };
    score += bucket_penalty;

    // Modulo coupling: leftover congruent to common item sizes is valuable.
    // If post_residual % 10 == 0, the gap aligns with decimal item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // If post_residual is exactly a plausible next-item size, huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // If next item fits exactly into the post_residual gap, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; penalize stranding capacity.
        score += 10.0 * (1.0 - fit_ratio);
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent fit. Penalize opening a new bin progressively.
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
        // But if stream is early and mean residual is fragmented, opening is fine.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < 20.0 && progress < 0.5 {
            score -= 25.0;
        }
        // If next item is large and current item is small, a fresh bin can
        // serve future big items better.
        if next_item_size >= 60 && item_size <= 30 {
            score -= 12.0;
        }
    }

    // Fragmentation guard: avoid leaving gaps in the awkward 1..9 range.
    if post_residual >= 1 && post_residual < 10 {
        score += 25.0;
    }

    // Mild preference to consolidate across many open bins.
    score += 0.3 * open_bins_count as f64 * fit_ratio;

    // Small lookahead harmony: if next item shares harmonic class with current.
    if next_item_size > 0 && (next_item_size / 20) == (item_size / 20) {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let tight = (next_item_size as f64 / post_residual as f64).abs();
        if tight > 0.7 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    }

    // New-bin candidate handling: neutral-ish baseline so it wins only over bad fits.
    if bin_residual == bin_capacity {
        score += 8.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late-stream consolidation: keep using existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: post_residual exactly matches next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near-perfect chain: next item still fits with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Dead space penalty: small residual that next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Reward tight fits relative to mean residual of open bins.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.5;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.25;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize leaving exactly tiny unusable residuals (1..9).
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual as f64 > mean_residual * 1.5);
        if poor_fit {
            score -= 20.0;
        } else {
            score += 25.0;
        }
    }

    // Early stream: slightly prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize residuals that no plausible future item can use.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 0.0 } else { post_residual as f64 };
        score += 0.15 * dead;
    }

    // Perfect-fill reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer fuller bins among many open bins (best-fit bias).
    score -= 0.5 * (bin_residual as f64) / (open_bins_count.max(1) as f64).sqrt();

    // Time horizon: early in stream, be pickier about waste; late, pack greedily.
    let t = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - t) * 0.1 * post_residual as f64;
    score -= t * 10.0 * (mean_residual / bin_capacity as f64);

    // Discourage opening new bins when good fits exist.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.3 * open_bins_count as f64;
        if fitting_bins_count > 0 && post_residual > 20 {
            score += 15.0;
        }
    }

    // Mean-residual coupling: when open bins are on average roomy, favor compacting.
    score -= 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= poly * (20.0 + 60.0 * progress);
    // penalize tiny unusable residuals, more so late in the stream
    let tiny = (1.0 - norm_pr.min(1.0)).max(0.0);
    score += tiny * tiny * (1.0 - norm_pr) * (10.0 + 40.0 * progress);
    // lookahead coupling: reward residuals that still fit the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = if pr >= nxt { 1.0 } else { 0.0 };
        let ratio = (nxt / cap).min(1.0);
        score -= fits * (1.0 - (norm_pr - ratio).abs()) * (15.0 + 25.0 * progress);
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * (1.0 - progress);
    }
    // mild preference for concentrating items when many bins open
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 2.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into "usable"
    // residue classes (multiples of common item sizes) are more valuable.
    let usable = [0u32, 10, 20, 25, 30, 40, 50, 60, 70];
    let mut class_bonus = 0.0f64;
    for &u in usable.iter() {
        if post_residual == u {
            class_bonus -= 18.0;
        } else if post_residual >= u {
            class_bonus -= 2.0 * (u as f64 / bin_capacity as f64);
        }
    }
    score += class_bonus;

    // Penalize awkward dead space: post_residual in (0,10) wastes capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item exactly matches post_residual,
    // this placement chains perfectly; if next item would be wasted, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item cannot use this bin's leftover: dead space risk
            score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if only one open bin fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer reusing a well-filled bin over opening
    // a fresh one unless the fresh bin offers a great deal.
    if bin_residual == bin_capacity {
        // new empty bin: baseline = capacity; reward only slightly for tight fits
        score = bin_capacity as f64 - 10.0
            + if item_size >= bin_capacity / 2 { 5.0 } else { 0.0 };
        if fitting_bins_count == 1 {
            // an existing last-chance bin exists; opening new bin is wasteful
            score += 40.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 12.0; // room to pair next item
        }
    } else {
        // tighter fill fraction => lower score
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 15.0 * fill;
    }

    // Mean residual coupling: when open bins are loose on average, tighten packing.
    if mean_residual > 30.0 && bin_residual < bin_capacity {
        score -= 5.0 * (mean_residual / bin_capacity as f64);
    }

    // Stream progression: late in stream, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    // Modulo harmonic: leftover divisible by 10 is reusable by typical items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the worst outcome.
    if post_residual > 0 {
        let min_item = 1.0f64;
        if (post_residual as f64) < min_item {
            score += 50.0; // theoretically unreachable, safety guard
        }
        // Penalize gaps too small for the smallest possible future item relative to residual size
        let dead_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
        if post_residual < 10 {
            score += 40.0 * (1.0 - post_residual as f64 / 10.0);
        } else if post_residual < 25 {
            score += 12.0;
        }
        let _ = dead_ratio;
    }

    // Reward tight fits (post_residual near zero is good, already low base).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // next item cannot use this gap -> dead space likely
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a good fit exists.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins first).
    score -= 0.5 * ((bin_residual as f64) - mean_residual);

    // Slight preference for filling older bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 5.0 * progress;
    }

    // New-bin candidate: only attractive when item is huge and no open bin fits well.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        if fill > 0.9 {
            score -= 10.0 * (fill - 0.9) * 10.0;
        } else {
            score += 10.0 + 20.0 * (1.0 - fill);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let nis = next_item_size as f64;

    // Perfect 2-step fit: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Next item fits in the residual: reward proportionally (tighter leftover better)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = pr - nis;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Next item does NOT fit: penalize creating dead space, worse when residual small
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 12.0 + 10.0 * (1.0 - pr / bin_capacity as f64);
    }

    // Zero residual is ideal closure
    if post_residual == 0 {
        score -= 30.0;
    }

    // Coupling with mean residual: bins below mean residual are tighter -> prefer them
    score -= (mean_residual - pr) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 + t);
    }

    // New-bin candidate: only attractive when current bins would leave large dead space
    if bin_residual == bin_capacity {
        let best_possible = if next_item_size > 0 {
            (bin_capacity as f64 - item_size as f64 - next_item_size as f64).max(0.0)
        } else {
            bin_capacity as f64 - item_size as f64
        };
        score = (best_possible + 15.0).max(10.0);
    }

    // Early stream: mild preference for consolidating into fewer bins
    score -= (open_bins_count as f64) * 0.05 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more than linearly.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tightness) * (1.0 - tightness) * 10.0;

    // Penalize dead space that no plausible item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / (bin_capacity as f64);
        let poor_fit = (post_residual as f64) / (bin_capacity as f64);
        score += 20.0 * crowding;
        if poor_fit < 0.15 {
            score -= 35.0; // opening a fresh bin beats making tiny dead space
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Mild preference for bins with residual above the mean (keeps small bins for small items).
    if bin_residual != bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.1 * diff;
    }

    // Encourage consolidation when many bins are open.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 + progress) - 0.6 * pr_norm * progress;

    let mut score = pr + poly * cap;

    // Reward tight fits, more strongly later in the stream
    score -= 12.0 * fill * fill * (0.5 + progress);

    // Last-chance bonus: penalize alternatives when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 + 4.0 * progress;
    }

    // Penalize bins that are far below the mean residual (wasteful spread)
    score += 0.15 * (pr - mean_residual).abs();

    // Mild pressure against opening many bins late
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the residual: classify post_residual into modulo classes of 10
    let class = post_residual / 10;
    match class {
        0 => score -= 40.0,               // tiny dead space, nearly perfect
        1 => score -= 15.0,               // good
        2 => score -= 5.0,
        3 => score -= 0.0,
        4 => score += 5.0,
        5 => score += 12.0,               // half-full leftover
        6 => score += 20.0,
        7 => score += 30.0,
        8 => score += 42.0,
        _ => score += 55.0,               // mostly empty bin, wasteful placement
    }

    // Lookahead coupling: can next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic bonus scaled by how well next item fills remaining space
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * fill;
            // exact modulo match: next item leaves another clean class
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot follow here; penalize more if leftover is small-but-unusable
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Capacity-fraction pressure: prefer filling bins that are already committed
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill_frac * fill_frac;

    // Prefer bins below mean residual (tighter bins) mildly
    score += 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: empty bin gets a moderate default score;
    // open it only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = 150.0 + 0.5 * item_size as f64;
        if fitting_bins_count == 0 {
            score = -100.0;
        } else if fitting_bins_count == 1 {
            // only one open bin fits: still prefer it unless item is tiny
            score = 60.0 + 0.3 * item_size as f64;
        }
        // late in stream, avoid spawning bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item (1..10)
    // are pure waste; penalize them super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving residuals that can accommodate the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space relative to the known next item.
        score += 0.5 * (post_residual as f64).min(next_item_size as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // over spreading; with few bins, new-bin option stays cheap.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln_1p() * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost rising with open-bin pressure.
        score += 25.0 + 8.0 * pressure;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin has full flexibility for lookahead
        }
    } else {
        // Existing bins get a mild discount that grows with pressure.
        score -= 4.0 * pressure;
        // Penalize placing into bins whose residual deviates from the mean
        // (prefer keeping a balanced pool of usable residuals).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Mild preference for tighter fits overall.
    score += 0.1 * (bin_residual - item_size) as f64 * 0.0; // no-op guard
    score -= 0.3 * item_size as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (low post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step chain: fills bin completely next step
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: dead space risk, penalize proportionally
            let gap = (next_item_size - post_residual) as f64;
            score += 12.0 * (gap / bin_capacity as f64);
        }
    } else {
        // Last item: prefer maximal fill.
        score -= 30.0 * (1.0 - fit_ratio);
    }

    // Relative to mean residual: prefer using bins with more residual than average
    // (keeps tight bins for tighter future fits).
    score -= 8.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    // Last-chance bin: strongly favor placing here before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize so we only open when no good fit exists.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if next item is large and current item small, opening early can help.
        if next_item_size > 0 && next_item_size >= 60 && item_size <= 30 {
            score -= 20.0;
        }
    }

    // Late in stream: be greedy, minimize waste aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 15.0 * fit_ratio;
    score -= (1.0 - progress) * 5.0;

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 3 {
        score -= 6.0 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space that can't fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this placement is very valuable.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty for fragmenting.
            score += 8.0 * (next_item_size as f64 / (post_residual + 1) as f64);
        }
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep residuals large); late in the stream, pack tighter and prefer
    // existing bins to avoid leaving many half-filled bins.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Early: opening a bin is fine (low score). Late: discourage unless
        // nothing else is reasonable.
        score += 55.0 * progress;
        // Also discourage new bins when many bins are open with slack.
        score += 0.8 * open_bins_count as f64;
        // If the current item is small, a fresh bin wastes capacity.
        if (item_size as f64) < 0.35 * bin_capacity as f64 {
            score += 20.0;
        }
    } else {
        // Existing bin: reward using it more as stream progresses.
        score -= 20.0 * progress;
        // Prefer bins whose residual deviates below the mean (tighter bins),
        // keeping the mean residual low overall.
        score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);
    }

    // Global pressure: many open bins -> consolidate into existing bins.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // Prefer bins that leave post-residual matching common small sizes (10..20).
    for r in [10u32, 15, 20, 25, 30].iter() {
        if post_residual == *r {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual, with smooth non-linear polynomial coupling to progress.
    let mut score = pr * (1.0 + 0.8 * progress) + 60.0 * norm_pr * norm_pr * (1.0 - progress);

    // Penalize large dead space that no future small item is likely to fill late in stream.
    score += 25.0 * norm_pr * norm_pr * norm_pr * (0.5 + progress);

    // Lookahead: reward bins whose post residual fits the next item (smooth coupling).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fit_next = (ns - pr).abs();
        score -= 18.0 * (1.0 - fit_next / cap).max(0.0) * (1.0 + progress);
        // If next item cannot fit here, mild penalty grows with progress.
        if ns > pr {
            score += 10.0 * (ns - pr) / cap * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: penalize opening a new bin, more so early/mid stream,
    // but allow it when post residual of existing fits is very poor.
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - progress);
        if next_item_size > 0 {
            // New bin is attractive if next item also fits well in fresh capacity.
            let ns = next_item_size as f64;
            score -= 12.0 * (ns / cap) * (1.0 - progress);
        }
    }

    // Mean residual coupling: prefer bins close to mean residual (smooth quadratic).
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits
    score -= (item_size as f64 / cap_f) * 12.0;

    // Harmonic class of post_residual: residues near multiples of small classes
    // are more reusable. Classes: 0, <=10, <=20, etc.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect closure
    } else {
        let class = pr % 10;
        // residues divisible into small classes are more likely filled by future items
        if class == 0 {
            score -= 8.0;
        } else if class <= 3 {
            score -= 4.0;
        } else if class >= 8 {
            score += 3.0; // awkward remainder
        }
        // Integer-division thresholds: post_residual in [1,10] is a dead zone
        if pr <= 10 {
            score += 15.0 * (1.0 - pr as f64 / 10.0);
        }
        // Harmonic fractions of capacity: residual equal to C/2, C/3, C/4 are valuable
        for (k, w) in [(2u32, 6.0f64), (3, 5.0), (4, 4.0), (5, 3.0)].iter() {
            let target = bin_capacity / k;
            let d = (pr as i64 - target as i64).abs();
            if d <= 2 {
                score -= *w;
            }
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 10.0 * (1.0 - slack as f64 / cap_f);
            // harmonic match: next item leaves another clean residue
            let nr = pr - next_item_size;
            if nr % 10 == 0 && nr > 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot use this bin's residue anyway; neutral
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter competition signal
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Mean residual coupling: placing into a bin below mean residual balances load
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.05;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.03;
    }

    // New-bin candidate handling: only attractive early or when open bins are crowded
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score = cap_f - (item_size as f64) - 5.0;
        score += progress * 10.0; // new bins get costlier as stream matures
        score += open_bins_count as f64 * 0.5;
        if fitting_bins_count <= 1 && fitting_bins_count > 0 {
            // an existing bin fits: new bin should rarely win
            score += 25.0;
        }
    }

    // Stream phase modulation: late stream favors consolidation
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit is ideal.
        score -= 100.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Pressure from number of open bins: discourage spreading across many bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    }
    // Penalize if the leftover gap can't hold the next item but is small (dead space).
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size && post_residual < 30 {
        score += 20.0;
    }

    // New-bin candidate: keep it moderately attractive so we open bins when
    // remaining bins would create dead space, but not so cheap we never reuse.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    // Late in the stream, slightly prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact fit now
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits perfectly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0; // perfect chain
        } else if next_item_size < post_residual {
            // next fits: reward proportional to how tight the second fit is
            let next_left = post_residual - next_item_size;
            score -= 200.0 * (1.0 - next_left as f64 / bin_capacity as f64);
        } else {
            // next item does NOT fit: penalize leaving residual that wastes space
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: strongly prefer minimal residual
        score -= 300.0;
    }

    // Prefer bins tighter than the mean residual (fill full bins first)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless current item is large and no good fit exists
    if bin_residual == bin_capacity {
        score += 60.0;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 40.0; // fresh bin useful for upcoming big item
        }
    }

    // Late in stream: consolidate harder, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 100.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post-residual), with slight superlinearity
    let pr = post_residual as f64;
    score = pr * (1.0 + 0.004 * pr);

    // Reward bins that fit the item exactly or near-exactly
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: if the next item can use this bin's post-residual, reward placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }
    // If next item is large and would need a fresh bin anyway, mildly favor new bin
    if next_item_size > 0 && next_item_size > bin_capacity - item_size {
        score += 6.0;
    }

    // Penalize creating dead space smaller than the minimum plausible item (1..100 unknown,
    // but small residuals relative to mean residual are wasteful)
    if pr > 0.0 && pr < mean_residual * 0.5 {
        score += 8.0;
    }

    // Global state: when many bins are open, consolidate; when few, allow spreading
    let t = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = (open_bins_count as f64).ln().max(0.0);
    score += 0.8 * consolidation * (pr / bin_capacity as f64);

    // Late in stream: be more conservative, prefer filling existing bins over opening new
    let new_bin_bias = 25.0 * (1.0 - t);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, penalize more if open bins fit well
        score += new_bin_bias;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
        // Opening a new bin is fine if current bins' mean residual is large (fragmented)
        if mean_residual > 40.0 {
            score -= 10.0;
        }
    }

    // Mild bonus for bins whose residual is close to the item (best-fit sharpening)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 15.0 * tightness * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // non-linear coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - t) * 40.0 + norm_pr * t * 10.0;
    score += coupling;
    // penalize tiny unusable residuals more strongly as stream progresses
    let dead = if pr > 0.0 { (cap / pr.max(1.0)) } else { 0.0 };
    score -= dead * 0.5 * t;
    // reward tight fits
    let tight = (item_size as f64 / bin_residual as f64).powi(3);
    score -= tight * 15.0;
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0;
    }
    // lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score += diff * 0.15;
    }
    // discourage opening new bins early / too many open bins
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - t);
    }
    score += (mean_residual - norm_pr * cap) * 0.05;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: modulo-10 residue classes.
    let post = post_residual as i64;
    let cap = bin_capacity as i64;
    let item = item_size as i64;
    let next = next_item_size as i64;

    // Perfect-fit bonus (post_residual == 0)
    if post == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: residuals that are multiples of common item sizes (10, 20, 25, 50)
    // are "reusable" classes — reward them.
    let reusable = |r: i64| -> f64 {
        if r == 0 { 0.0 }
        else if r % 50 == 0 { 40.0 }
        else if r % 25 == 0 { 30.0 }
        else if r % 20 == 0 { 25.0 }
        else if r % 10 == 0 { 20.0 }
        else { 0.0 }
    };
    score -= reusable(post);

    // Penalize awkward small residuals (dead space): 1..=9 are hard to fill.
    if post > 0 && post < 10 {
        score += 15.0;
    }
    // Class of residual in (10, 20): only items <= post fit; mildly awkward.
    if post > 10 && post < 20 {
        score += 5.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chain packing).
    if next > 0 {
        if next == post {
            score -= 200.0;
        } else if next <= post {
            let nxt_post = post - next;
            // Reward if the chain leaves a reusable class again.
            score -= reusable(nxt_post);
            if nxt_post > 0 && nxt_post < 10 {
                score += 10.0; // chain creates dead space
            }
            // Fractional capacity coupling
            let frac = post as f64 / cap as f64;
            let nfrac = next as f64 / cap as f64;
            score -= (frac - nfrac).abs() * 10.0;
        } else {
            // Next item won't fit here; penalize slightly based on wasted fraction.
            score += (post as f64 / cap as f64) * 5.0;
        }
    }

    // Integer-division threshold: bins whose residual is in the "large half"
    // (> capacity/2) are more valuable to keep flexible.
    if post > cap / 2 {
        score -= 8.0;
    } else if post > cap / 4 {
        score -= 3.0;
    }

    // Last-chance bin: if this is the only bin that fits the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // and no good class exists among open bins.
    if bin_residual == bin_capacity {
        score += 50.0;
        if item * 4 >= cap * 3 {
            score -= 40.0; // big items: fresh bin is fine
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Stream progression: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post as f64).abs().min(50.0) * 0.5;

    // Prefer bins below mean residual (tighter bins) mildly.
    score += (mean_residual - post as f64) * 0.1;

    // Modulo-5 fine class: residuals divisible by 5 are slightly more usable.
    if post % 5 == 0 && post > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest item (1) are pure waste; residuals below a
    // "usable threshold" are heavily penalized since they are hard to fill.
    let min_item = 1u32;
    let usable_floor = 10u32; // typical small-item size
    if post_residual < min_item {
        score += 500.0; // impossible gap (cannot happen with ints, safety)
    } else if post_residual == 0 {
        score -= 60.0; // perfect fit: strongly reward
    } else if post_residual < usable_floor {
        // unusable micro-gap: penalize quadratically beyond raw residual
        score += (usable_floor - post_residual) as f64 * 12.0;
    }

    // Reward tight fits: relative fill ratio of this placement
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // New-bin candidate handling: opening a bin is costly; make the empty
    // bin unattractive unless existing bins would leave large dead space.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a new bin
        score += 45.0;
        // pressure from open bins: more open bins -> discourage new ones
        score += open_bins_count as f64 * 2.5;
        // if this bin is the last chance, opening a new bin is competitive
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // early in stream, opening bins is cheaper (builds options)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
        // if next item is large, a fresh bin gives flexibility
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0;
        }
    } else {
        // existing bin: reward using bins that are already open, especially
        // when many bins are open (consolidation pressure)
        score -= 5.0;
        if fitting_bins_count == 1 {
            // last chance: strongly prefer this bin over opening a new one
            score -= 20.0;
        }
        // coupling with mean residual: prefer bins below mean residual
        // (fill emptier-relative bins first keeps others flexible)
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    }

    // Lookahead: if next item would exactly fit the post_residual of this
    // bin, this placement is excellent (chains a perfect follow-up).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < usable_floor {
            // next item would create dead space here; slight penalty
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits
    score += 0.5 * (post_residual as f64 / bin_capacity as f64).powf(2.0) * 100.0;

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            // reward proportional to how little space remains after chaining
            score -= 40.0 * (1.0 - leftover as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize more if leftover dead space is unusable
            let dead = (post_residual as f64) / bin_capacity as f64;
            score += 25.0 * dead * dead;
        }
    }

    // Relative to mean residual: prefer bins whose post-residual is below average
    // (keeps large residuals available for large future items)
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless it enables
    // a perfect lookahead chain and few bins are open
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Late in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward near-zero post-residual.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Penalize leaving dead space that no plausible future item can use
    // (items are >= 1, but small residuals below ~10 are usually wasted).
    let t = step_index as f64 / (total_items.max(1) as f64);
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 1.5;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly reward this placement (chain fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // next item still fits here: mild reward proportional to leftover
            let leftover2 = post_residual - next_item_size;
            score -= 20.0 - (leftover2 as f64).min(20.0);
        } else {
            // next item won't fit after this placement: mild penalty,
            // worse when this bin was the only option
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is expensive early (few bins),
    // cheaper late when open bins are mostly full.
    if bin_residual == bin_capacity {
        let avg_open_fullness = bin_capacity as f64 - mean_residual;
        let pressure = if open_bins_count > 0 {
            avg_open_fullness / bin_capacity as f64
        } else {
            0.0
        };
        // Base cost of a new bin, reduced when existing bins are underutilized.
        score += 40.0 + 50.0 * (1.0 - pressure) + 20.0 * (1.0 - t);
        // If nothing fits anywhere except the new bin, fitting_bins_count
        // reflects only open bins; the +40 base already makes this a fallback.
        if fitting_bins_count == 0 {
            score -= 100.0; // forced: must open a new bin
        }
    } else {
        // Mild preference for filling bins that are already relatively full
        // (keep small residuals consolidated).
        let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * fullness;
        // Slight penalty for spreading across many bins when mean residual is high.
        score += (mean_residual - post_residual as f64).abs() * 0.1;
    }

    // Late-stream conservatism: near the end, avoid opening bins that will
    // remain mostly empty.
    if t > 0.9 && bin_residual == bin_capacity {
        score += 30.0 * (t - 0.9) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = item_size as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Base: prefer minimal post residual, with quadratic tightness reward.
    let mut score = post + 60.0 * (post / cap) * (post / cap);

    // Smooth non-linear coupling: tightness reward grows with stream progress.
    let tight = 1.0 - post / cap; // 0..1, higher = tighter fit
    score -= 90.0 * tight * tight * tight * (0.4 + 0.6 * progress);

    // Penalize post residual that cannot host the lookahead item (dead space).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post < nx {
            score += 45.0 * (nx - post) / cap * (1.0 + progress);
        } else {
            // Reward leaving room exactly usable by next item (smooth bump).
            let slack = (post - nx) / cap;
            score -= 35.0 * (-12.0 * slack * slack).exp();
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0 * (0.5 + 0.5 * progress);
    }

    // Mild penalty for spreading across many open bins when mean residual is high.
    let open = open_bins_count as f64;
    score += 8.0 * (open / (open + 5.0)) * (mean_residual / cap);

    // Smooth penalty for wasting a nearly-full bin on a small item.
    let waste = (post / cap) * (1.0 - fit / cap);
    score += 25.0 * waste * waste;

    // New-bin candidate bias: only attractive early or when no open bin fits well.
    if bin_residual == bin_capacity {
        let early = 1.0 - progress;
        score += 12.0 * early - 15.0 * progress * (fitting_bins_count as f64).min(3.0) / 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residual classes mod 10
    // and integer-division thresholds on capacity fractions.
    let post_class = post_residual / 10; // 0..=10 harmonic class
    let item_class = item_size / 10;

    // Reward tight fits: small post_residual classes are desirable.
    // Class 0 (perfect fit) heavily rewarded, class 1-2 mild reward.
    match post_class {
        0 => score -= 60.0,
        1 => score -= 25.0,
        2 => score -= 12.0,
        3 => score -= 5.0,
        _ => {}
    }

    // Penalize dead space that no typical item (1..100) can use well:
    // post_residual in awkward bands (e.g., 31..=40, 61..=70) waste space.
    if post_residual >= 31 && post_residual <= 40 {
        score += 10.0;
    }
    if post_residual >= 61 && post_residual <= 70 {
        score += 6.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly favor this bin (chain of perfect fits).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual && post_residual - next_item_size <= 5 {
            score -= 35.0;
        } else if next_item_size > post_residual {
            // Next item cannot follow here; penalize leaving residue
            // smaller than any useful chunk relative to next item.
            if post_residual < next_item_size && post_residual > 0 {
                score += (next_item_size - post_residual) as f64 * 0.3;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.2 * post_residual as f64;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a decent fit. Penalize the fresh bin mildly so
    // that any reasonable existing fit beats it; the penalty shrinks when
    // the current item is large (poorly packable) or many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 55.0;
        // Large items fragment bins; opening fresh bins for them is fine.
        if item_size >= 50 {
            new_bin_penalty -= (item_size - 50) as f64 * 0.5;
        }
        // Early in the stream, having few bins, prefer consolidation less.
        new_bin_penalty -= progress * 10.0;
        score += new_bin_penalty.max(5.0);
    }

    // Modulo-based harmonic penalty: post_residual congruent to small
    // values mod 7 are slightly favored (empirically reusable chunks).
    let m = post_residual % 7;
    if m == 0 {
        score -= 4.0;
    } else if m <= 2 {
        score -= 2.0;
    }

    // Mean residual coupling: prefer bins whose residual is below the
    // mean (i.e., already well-filled bins).
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold the
    // smallest plausible item are worthless — punish them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (small relative post residual).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 15.0;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= (10.0 - slack.min(10.0)) * 1.5;
    }
    // If next item cannot use the leftover gap, penalize slightly.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: prefer consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is near the mean (balanced packing),
    // penalize extremes unless it's a perfect fit.
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.15;

    // New-bin candidate: make empty bin mildly attractive only when the
    // item is large relative to capacity or many bins already struggle.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score = 55.0 - large_item * 30.0 + open_bins_count as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is gold.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // next item fills this bin exactly
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow into this bin: penalize dead space
            score += 10.0 + 0.3 * post_residual as f64;
        }
    } else {
        // last item: just minimize waste
        score += 0.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.4 * (post_residual as f64 - mean_residual);

    // Last-chance bin before opening a new one: strong bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening new bins early in the stream when open bins exist.
    if bin_residual == bin_capacity {
        score += 15.0 + 5.0 * (open_bins_count as f64).sqrt();
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 10.0; // fresh bin is tempting for lookahead, discourage anyway
        }
    }

    // Mild waste-avoidance: tiny post-residuals are great.
    if post_residual < 10 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 8.0;

    // Penalize small dead space that nothing can use
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    } else if post_residual >= 10 {
        score -= 2.0;
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits in post_residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 6.0;
    } else if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 && (next_item_size as f64) <= bin_residual as f64 {
        // next item would have fit here if we placed elsewhere
        score += 4.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor
    if bin_residual == bin_capacity {
        score += 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits, must open new bin
        }
        if fit_ratio < 0.5 {
            score += 5.0;
        }
    }

    // Time horizon: early on, be conservative (favor spreading); later, pack tight
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // Global pressure: many open bins -> prefer filling existing ones
    score -= (open_bins_count as f64).ln().max(0.0) * 1.5;
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p = progress;
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * p) - norm_pr * norm_item * p;
    score += poly * cap;

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * cap * (0.5 + p);

    // Penalize dead space (small post-residual that is still unusable)
    if next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        score += (next_item_size as f64 - pr) * (0.5 + p);
    }

    // Last-chance bin bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + p);
    }

    // Mild penalty when bin diverges from mean residual (prefer balanced fills)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev.abs() * cap * 0.1 * (1.0 - p);

    // New-bin candidate: penalize slightly so open bins are preferred unless fit is poor
    if bin_residual == bin_capacity {
        score += cap * (0.3 + 0.4 * (1.0 - norm_item)) * (1.0 - p);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo 10: residuals divisible by 10
    // are "harmonic" and reusable by the widest set of future item sizes.
    let post = post_residual as i64;
    let cap = bin_capacity as i64;
    let harmonic_bonus = if post % 10 == 0 {
        -6.0
    } else if post % 5 == 0 {
        -2.5
    } else if post % 2 == 0 {
        -0.5
    } else {
        1.5
    };
    score += harmonic_bonus;

    // Integer-division thresholds: how many "next item" units fit in post_residual.
    if next_item_size > 0 && next_item_size <= post as u32 {
        let fits_next = post / (next_item_size as i64);
        score -= 4.0 * fits_next as f64;
        // Perfect match: post_residual exactly equals next item size.
        if post == next_item_size as i64 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this residual: penalize proportionally to waste.
        score += 3.0 * (next_item_size as f64 - post as f64).max(0.0) / 10.0;
    }

    // Capacity-fraction classes: reward residuals that are small fractions of C.
    let frac = post as f64 / cap as f64;
    if frac <= 0.1 {
        score -= 2.0; // near-full bin is excellent (little dead space)
    } else if frac <= 0.25 {
        score -= 1.0;
    } else if frac >= 0.5 {
        score += 1.5 * frac; // large residual = wasteful bin
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 5.0;
    } else if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: penalize opening a fresh bin unless residuals
    // across open bins are already very low (nothing useful left).
    if bin_residual == bin_capacity {
        let base = 12.0 + 0.15 * mean_residual;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = base + 5.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 4.0; // big upcoming item justifies a fresh bin
        }
    }

    // Mild preference for tight packing early, consolidation later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64).sqrt() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the minimum item are wasted.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Perfect-fit lookahead: if the next item exactly fills post_residual, strongly favor.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.5;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when current fits are poor.
    if bin_residual == bin_capacity {
        score -= 10.0 + mean_residual * 0.3;
        if post_residual < 10 { score += 0.0; } // empty bin has post_residual = cap - item
    }

    // Slight preference to fill bins below mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin; relax penalty if few bins can fit or
        // the current bin would leave a large unusable gap.
        let mut new_bin_penalty = 25.0;
        if fitting_bins_count <= 1 {
            new_bin_penalty -= 20.0;
        }
        if post_residual < next_item_size as f64 * 0.5 && post_residual > 0.0 {
            new_bin_penalty -= 10.0;
        }
        score += new_bin_penalty;
        return score;
    }

    // Perfect 2-step match: post_residual equals next item size exactly.
    if next_item_size > 0 && post_residual as u32 == next_item_size {
        score -= 40.0;
    }

    // Near-match: post_residual within a small band of next_item_size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap <= 4.0 {
            score -= 25.0 - gap * 4.0;
        }
        // Penalize dead space: leftover too small for the next item
        // (wasted capacity that likely can never be reused).
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size as f64 - post_residual as f64) * 1.5;
        }
    }

    // Reward leaving residuals that are large and reusable relative to mean.
    if post_residual as f64 > mean_residual {
        score -= (post_residual as f64 - mean_residual) * 0.3;
    } else {
        score += (mean_residual - post_residual as f64) * 0.2;
    }

    // Last-chance bin: strongly prefer filling it rather than wasting it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer tight fits overall (small post_residual), with extra weight
    // early in the stream to keep bins compact from the start.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * (0.1 + 0.2 * (1.0 - progress));

    // Mild bonus for consolidating into fewer bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual, with a slight super-linear penalty
    // on dead space so large leftover gaps are strongly discouraged.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    // Perfect-ish fit reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 10 {
        score -= 5.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item,
    // penalize bins that would strand the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.10 * (post_residual - next_item_size) as f64;
        } else if post_residual > 0 {
            // Dead space that the next item cannot use.
            score += 0.25 * post_residual as f64;
        }
        // If the next item would exactly fill the remainder, strong reward.
        if post_residual == next_item_size && next_item_size > 0 {
            score -= 15.0;
        }
    }

    // Last-chance dynamics: if this is the only bin that fits, using it
    // avoids opening a new bin — reward proportionally to how full it gets.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.20 * item_size as f64;
    }
    // Many alternatives: slight penalty for consuming a scarce large residual.
    if fitting_bins_count > 2 {
        score += 0.05 * (post_residual as f64).sqrt();
    }

    // Global state coupling: when mean residual is high, prefer placements
    // that reduce dispersion (move residual toward the mean).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Time horizon: early in the stream, be conservative about opening bins;
    // late in the stream, tolerate slightly worse fits since bins are sunk cost.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only when item is large relative to
        // capacity or no good fits exist; penalize mildly otherwise so we
        // don't proliferate bins.
        score += 18.0 - 0.15 * item_size as f64 - 12.0 * progress;
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a bin anyway
        }
        if next_item_size > 0 && next_item_size >= post_residual {
            score -= 5.0; // fresh bin leaves room for lookahead item
        }
    }

    // Mild preference for filling bins that are already heavily loaded.
    let load_frac = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 6.0 * load_frac * load_frac;

    // Small open-bin pressure: with many open bins, favor consolidation.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let is_new = (bin_residual == bin_capacity) as f64;

    // Base: penalize wasted space, with non-linear polynomial coupling to stream progress.
    let mut score = pr * (1.0 + 0.6 * progress * progress) + 12.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits: smooth quadratic bonus when post_residual is small.
    score -= 30.0 * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Lookahead coupling: reward if next item fits the post residual (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (pr >= nxt) as f64;
        let slack = ((pr - nxt).abs()) as f64 / cap;
        score -= 8.0 * fits_next * (1.0 - slack) * (1.0 + 0.5 * progress);
        score += 4.0 * slack * (1.0 - fits_next);
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    let last_chance = (fitting_bins_count == 1 && is_new == 0.0) as f64;
    score -= 25.0 * last_chance * (1.0 - pr_norm);

    // New-bin candidate: penalize mildly, less so late in the stream when residuals are fragmented.
    score += is_new * (15.0 - 10.0 * progress * (mean_residual / cap).min(1.0));

    // Congestion: many open bins with low mean residual -> prefer consolidating into existing bins.
    let congestion = (open_bins_count as f64) / (1.0 + mean_residual / cap);
    score += 0.5 * congestion * (1.0 - is_new) * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: dead space tiers via integer division
    let class = post_residual / 10;
    score += match class {
        0 => -6.0,              // residual < 10: perfect closure
        1 => -2.0,              // 10..19: likely fillable
        2 => 1.5,               // 20..29: mild waste
        3 => 4.0,               // 30..39
        4 => 7.0,               // 40..49
        _ => 10.0,              // >=50: large dead space
    };

    // Reward exact modulo harmony: post_residual divisible into classes of 5/10
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    } else if post_residual % 5 == 0 {
        score -= 1.5;
    }

    // Lookahead harmony: next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 8.0;
        } else if next_item_size <= post_residual {
            score -= 2.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 2.0 * (next_item_size as f64 - post_residual as f64) / 50.0;
        }
    } else {
        // last item: prefer tightest closure
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 9.0;
    }

    // Penalize opening a new bin when many bins are open and mean residual is large
    if bin_residual == bin_capacity {
        score += 4.0 + 0.05 * open_bins_count as f64 + 0.02 * mean_residual;
    }

    // Stream progression: later in stream, be more tolerant of imperfect fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest plausible item (1..100 range, so anything < ~10) are dead space.
    if post_residual > 0 {
        if post_residual < 10 {
            // Completely wasted capacity: heavy penalty scaled by how close to zero.
            score += 60.0 * (1.0 - post_residual as f64 / 10.0) + 20.0;
        } else if post_residual < 25 {
            // Marginal gap: likely unusable for many items, moderate penalty.
            score += 15.0 * (1.0 - (post_residual as f64 - 10.0) / 15.0);
        } else {
            // Usable residual: reward proportionally (subtract to favor).
            score -= 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Perfect fill: strong reward.
        score -= 40.0;
    }

    // Exact-fit lookahead: if next item exactly fills post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits: mild reward.
        score -= 5.0;
    } else if next_item_size > 0 {
        // Next item would NOT fit here: this bin's residual becomes dead for next step.
        score += 10.0;
    }

    // Open bins pressure: when many bins are open, prefer filling existing ones;
    // when few bins are open, tolerate opening new bins less harshly.
    let pressure = (open_bins_count as f64).sqrt() * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open.
        score += pressure + 5.0;
    } else {
        // Existing bin: reward slightly reduced by pressure (favor consolidation).
        score -= pressure * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it is a
    // laggard bin — filling it consolidates waste.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 3.0 * dev.min(50.0) / 50.0;
    }

    // Late in the stream: consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    } else {
        score += 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let exact = (post_residual as f64 - next_item_size as f64).abs();
        score -= 18.0 * (1.0 - exact / bin_capacity as f64);
        // perfect two-item fill bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here: penalize dead space
        score += 6.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // tight fit reward relative to current item
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 10.0 * tightness;

    // penalize bins far from mean residual (prefer typical-fill bins)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // discourage opening new bins when decent fits exist
    if bin_residual == bin_capacity {
        score += 8.0 + 4.0 * (open_bins_count as f64).ln().max(0.0);
        // allow new bin when stream is early
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 6.0 * (1.0 - progress);
    }

    // penalize leaving tiny unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream processed (dynamic time horizon).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: reward near-exact fits strongly (non-linear).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tight * tight * tight;

    // Penalize dead space that nothing (current or next item) can use.
    if post_residual > 0 {
        if next_item_size > 0 && next_item_size <= post_residual {
            // Next item can still use the leftover: mild bonus.
            score -= 8.0;
        } else {
            // Dead space: penalize proportionally to wasted capacity.
            score += 0.35 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // Many alternatives: mild penalty so tightest fits win.
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decays late in the stream
        // (fewer future items to amortize the bin => discourage opening).
        score += 30.0 + 40.0 * t;

        // Opening a bin is attractive if the item is large and would leave
        // a big, awkward residual in existing bins, or if few bins fit it.
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // no open bin fits: must open
        }
        // If next item is large and current item small, a fresh bin can
        // serve both: slight discount.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    } else {
        // Existing bin: reward bins that are already well-utilized
        // (packing large items into low-residual bins first).
        let used = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 20.0 * used;

        // Penalize placing into bins far from mean residual only early on,
        // to keep a balanced pool; late, balance matters less.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += (1.0 - t) * 0.05 * dev;
    }

    // Mild global pressure: many open bins -> prefer filling existing ones.
    score += 0.5 * open_bins_count as f64 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    let mut score = post * (1.0 + 0.6 * progress * (post / cap));

    // Non-linear coupling: quadratic waste term amplified by stream progress
    let waste_frac = post / cap;
    score += 18.0 * waste_frac * waste_frac * (0.5 + progress);

    // Reward near-perfect fits smoothly
    score -= 12.0 * (1.0 - waste_frac) * (1.0 - waste_frac);

    // Lookahead: penalize if post-residual can't fit next item, reward if it can
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 8.0 * (1.0 - progress);
        } else {
            score -= 4.0 * (1.0 - post / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Prefer filling bins with larger residuals relative to mean (consolidate space)
    if bin_residual < bin_capacity {
        score -= 3.0 * (mean_residual - post).signum() * ((mean_residual - post).abs() / cap);
    }

    // Mild penalty for opening a brand-new bin when other bins fit
    if bin_residual == bin_capacity {
        score += 10.0 + 6.0 * (1.0 - progress) + (fitting_bins_count as f64);
    }

    // Encourage more bins being used early (spread), consolidate late
    score += (open_bins_count as f64) * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact half / third / quarter fits are valuable
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if pr == cap as u32 / 2 {
        score -= 25.0;
    } else if pr == cap as u32 / 3 {
        score -= 15.0;
    } else if pr == cap as u32 / 4 {
        score -= 8.0;
    }

    // Modulo-10 harmonic band: small residuals in a "usable band" are fine
    let band = pr % 10;
    if band <= 2 {
        score += 12.0; // tiny sliver = dead space
    } else if band >= 8 {
        score -= 4.0; // near a harmonic decade, likely reusable
    }

    // Next-item lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            // partial compatibility, scaled by how well it divides
            let gap = pr - next_item_size;
            score -= 20.0 * (1.0 - gap as f64 / cap);
        } else {
            // next item won't fit here; penalize large leftovers slightly
            score += (pr as f64 / cap) * 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: keep it competitive only when current fit is poor
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if bin_residual == bin_capacity {
        score += 55.0; // default penalty for opening a new bin
        if fit_ratio > 0.85 {
            score -= 40.0; // but a big item into fresh bin is fine
        }
    } else if fit_ratio < 0.3 && post_residual > cap as u32 / 2 {
        // very small item into a very roomy bin wastes potential
        score += 10.0;
    }

    // Progress-aware dead-space aversion
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / cap) * 10.0 * progress;

    // Coupling with mean residual: avoid bins far from the mean (fragmentation)
    score += (mean_residual - post_residual as f64).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: residuals that are too small to fit a typical
    // future item (<= 10) are wasted forever.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Tightness ratio: favor bins where the item fills a large fraction of the gap.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio;

    // If this bin is the ONLY fitting bin, strongly prefer using it (last chance).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only attractive when open bins have poor residuals
    // or no bin fits well.
    if bin_residual == bin_capacity {
        // Base new-bin cost grows with number of open bins (avoid bin proliferation).
        score += 30.0 + 4.0 * open_bins_count as f64;
        // If current bin's post residual is unusable for the lookahead item,
        // opening a new bin becomes relatively more attractive.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 20.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    } else {
        // Penalize placing into a bin whose post residual can't hold the lookahead item
        // while another bin (or new bin) could.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 12.0;
        }
        // Mild pressure to prefer bins with below-mean residual (consolidate emptier space).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Lookahead synergy: reward placements that leave room exactly for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size).
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 30.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: strongly reward bins where the next item fits the post residual.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size <= post_residual {
            let next_tightness = (next_item_size as f64) / (post_residual as f64);
            // Prefer bins where next item fills the remainder nicely.
            score -= 25.0 * next_tightness;
            if next_item_size == post_residual {
                score -= 40.0; // chain perfect fit
            }
        } else {
            // Next item won't fit here: penalize leaving dead space relative to next item.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Compare against mean residual: bins far below mean are already tight; using them
    // for this item may be wasteful if a looser bin could absorb the item.
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        if res < mean_residual - 10.0 {
            score += 8.0; // penalize burning already-tight bins
        } else if res > mean_residual + 10.0 {
            score -= 5.0; // favor draining loose bins
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // Multiple options: mild penalty to encourage diversity, resolved by tightness.
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: only attractive for large items or when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Opening a new bin is good for big items (poor fit anywhere) or late in stream.
        let item_frac = item_size as f64 / bin_capacity as f64;
        score -= 20.0 * item_frac;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin accommodates lookahead item too
        }
        if item_size >= 60 {
            score -= 25.0;
        }
        // Slightly discourage opening new bins early when open bins exist.
        if open_bins_count > 0 && progress < 0.3 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * next_item_size as f64;
    }
    // Lookahead: if next item would be stranded by this placement, penalize slightly.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 0.15 * (next_item_size - post_residual) as f64;
    }

    // Discourage consuming a large residual bin with a small item early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio < 0.4 {
        score += (1.0 - progress) * 10.0 * (0.4 - fit_ratio);
    }

    // Penalize placements below the mean residual (using a tighter-than-average bin badly),
    // reward placements in bins with more residual than average.
    if bin_residual != bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score -= 0.08 * diff;
    }

    // New-bin candidate: baseline cost of opening a bin; becomes attractive only when
    // existing bins would leave large dead space or are scarce.
    if bin_residual == bin_capacity {
        score += 18.0 - 0.10 * waste; // post_residual == capacity here, keep near-constant
        score -= 4.0 * (fitting_bins_count as f64); // more alternatives -> less attractive
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late in the stream, prioritize filling bins completely.
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let tightness = 1.0 - (pr / cap).clamp(0.0, 1.0); // 0 empty bin, 1 full bin

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = tightness * tightness * (1.0 + progress) - tightness * progress * (1.0 - progress);
    score -= 12.0 * poly;

    // Penalize dead space that can't fit the next item (smooth interaction)
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            let waste_frac = (gap / cap).clamp(0.0, 1.0);
            score += 8.0 * waste_frac * waste_frac * (1.0 - progress);
        } else {
            // next item fits perfectly afterwards: reward
            score -= 6.0 * (1.0 - progress) * (1.0 - pr / cap);
        }
    }

    // Last-chance bin: reward using it to avoid opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * (1.0 - 0.5 * progress);
    }

    // New-bin candidate: neutral-ish baseline with slight progress-dependent penalty
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
    }

    // Mild preference for bins tighter than the mean residual
    score += 0.3 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by 10 (decile-aligned)
    // are more reusable against typical item sizes, reward them.
    let decile = post_residual % 10;
    if decile == 0 {
        score -= 4.0;
    } else if decile <= 2 {
        score -= 1.5;
    } else if decile >= 8 {
        score += 1.5;
    }

    // Quotient class: large post_residuals (>= half capacity) keep the bin flexible.
    let half = bin_capacity / 2;
    if post_residual >= half {
        score -= 3.0;
    } else if post_residual >= bin_capacity / 4 {
        score -= 1.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this placement is perfect — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual > next_item_size {
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 {
                score -= 5.0;
            } else if gap < 10 {
                score += 2.0; // near-fit creates tiny dead space next step
            }
        } else {
            // next item won't fit here; small post_residual wastes less
            score += 0.5 * (next_item_size - post_residual) as f64 / 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): neutralize its raw
    // post_residual so it only wins when open bins are genuinely poor fits.
    if bin_residual == bin_capacity {
        score += 6.0;
        // early stream: opening bins is fine; late stream: prefer consolidation
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 10.0 * progress;
        }
    }

    // Mild consolidation pressure: with many open bins, prefer reusing existing
    // capacity rather than spreading residual space.
    score += 0.15 * open_bins_count as f64;

    // Prefer bins whose residual is below the mean (filling the emptier bins
    // keeps the mean residual distribution tight).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Exact fit is always ideal.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item are "dead". Penalize them heavily.
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64);
    }

    // Reward near-perfect fits (post_residual close to 0 but not 0 handled above).
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Reward tightness non-linearly: prefer small residuals strongly.
        let r = post_residual as f64;
        score += 0.02 * r * r;
    }

    // Reward bins that could fit the NEXT item too (lookahead chainability).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // residual unusable for the next item: mild penalty
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; but
    // recognize the new-bin candidate (bin_residual == bin_capacity).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is penalized by the number of open bins,
        // plus the mean residual available across open bins.
        score += 30.0 + 6.0 * open_bins_count as f64 + 0.5 * mean_residual;
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Using an existing bin relieves open-bin pressure.
        score -= 2.0 * open_bins_count as f64;
    }

    // Mild preference for bins below mean residual (consolidate emptier bins).
    score += 0.1 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 20.0;

    // 2-step lookahead: reward if next item exactly fits post_residual.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if post >= nxt {
            let gap = post - nxt;
            if gap == 0.0 {
                score -= 60.0; // perfect chain fit
            } else {
                // penalize gap relative to post_residual (wasted space even after next item)
                score += (gap / post) * 30.0;
            }
        } else {
            // next item cannot follow into this bin: penalize by leftover dead space
            score += 15.0 + (nxt - post).min(50.0);
        }
    }

    // Compare against mean residual: prefer bins with below-average residual
    // (filling emptier-ish bins keeps tighter bins available), but only mildly.
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 45.0;
        // allow new bin if the item is large and would leave a big awkward residual
        if post_residual as f64 > bin_capacity as f64 * 0.5 {
            score -= 30.0;
        }
        // open new bin if next item is large too (better to start fresh)
        if next_item_size >= 60 && item_size >= 50 {
            score -= 35.0;
        }
    }

    // Early in stream: be slightly more willing to open bins (spread items).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional fill of this bin after placement: reward high fill.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill * fill;

    // Penalize large dead space nonlinearly (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny sliver: bad
    } else if post_residual >= 10 && post_residual < 30 {
        score -= 2.0; // still usable for small items
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let exact = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - exact / bin_capacity as f64);
    }
    // If next item won't fit in post_residual, mild penalty proportional to gap.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 0.05 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / bin_capacity as f64;
        score += 10.0 + 8.0 * (1.0 - progress) - 12.0 * crowding;
        if open_bins_count == 0 {
            score -= 20.0; // must open a bin
        }
    }

    // Global balance: prefer bins whose residual deviates from mean to consolidate space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    // Slight preference for fuller bins late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = norm_pr * (1.0 + 0.8 * progress * progress);
    score += 0.5 * norm_pr * norm_pr * (1.0 - progress);
    if pr == 0.0 { score -= 2.0; }
    if next_item_size as f64 > pr { score += 0.3 * norm_pr; }
    if fitting_bins_count == 1 { score -= 1.5 * (1.0 - progress); }
    score += 0.1 * (mean_residual - pr) / cap;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space (mod-10 classes on post_residual)
    let pr = post_residual;
    let harmonic = pr % 10;
    // Dead space: residuals < 10 are nearly unusable (min item is 1..=100, but
    // small leftovers waste capacity). Penalize small nonzero residuals hard.
    if pr > 0 && pr < 10 {
        score += 15.0;
    }
    // Exact fit is perfect
    if pr == 0 {
        score -= 25.0;
    }
    // Harmonic alignment: leftover in a "nice" class (multiples of 5) is more
    // reusable by future items; reward it.
    if harmonic == 0 {
        score -= 6.0;
    } else if harmonic == 5 {
        score -= 3.0;
    } else {
        score += (harmonic as f64) * 0.15;
    }

    // Integer-division threshold classes on post_residual
    let pr_class = pr / 10; // 0..=9 coarse class
    score += (pr_class as f64) * 0.5; // prefer bins with larger coarse class

    // Lookahead coupling: does the next item fit into the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Great: chain continues, reward proportional to tightness
            let tight = 1.0 - (pr - next_item_size) as f64 / cap;
            score -= 4.0 + 6.0 * tight;
        } else {
            // Next item won't fit: this bin becomes dead-ish
            score += 3.0;
        }
    } else {
        // Last item: just fill anything, prefer exact fit
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin wastes all residual of
    // other bins; penalize unless this bin is unusable anyway.
    if bin_residual == bin_capacity {
        let open_util = mean_residual / cap;
        // Penalize new bins more when existing bins are still roomy
        score += 8.0 + 10.0 * open_util;
        // But if nothing fits well (post_residual would be tiny in every bin),
        // the penalty above is what the new bin must beat; give slight relief
        // late in the stream when many bins are open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 4.0 * progress;
    }

    // Prefer tighter existing bins: subtract relative fill
    score -= (1.0 - bin_residual as f64 / cap) * 5.0;

    // Mild preference to keep number of open bins low
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are worse than large ones.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    if post_residual == 0 {
        score -= 500.0; // perfect fit
    }

    // Reward tight fits relative to item size.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 40.0;

    // Open-bin pressure: when many bins are open, prefer packing into existing ones
    // (penalize the new-bin candidate).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 8.0 * (1.0 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 200.0;
    }
    // Penalize leaving a residual the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 30.0;
    }

    // Mean residual coupling: avoid dumping items into bins already far below average.
    if (post_residual as f64) > mean_residual * 1.5 && bin_residual != bin_capacity {
        score += 15.0;
    }

    // New-bin candidate: make it mildly attractive only when it's a genuinely large item
    // that would leave big dead space elsewhere.
    if bin_residual == bin_capacity {
        score -= (item_size as f64 / bin_capacity as f64) * 60.0;
        if fitting_bins_count > 0 {
            score += 50.0; // discourage new bin if an existing bin fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a slight quadratic
    // penalty on large leftover space to discourage dead space.
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // 2-step lookahead: strongly reward bins where the NEXT item also fits
    // into the post_residual (perfect chaining of two items).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact or near-exact match for the next item is ideal.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
            if post_residual == next_item_size {
                score -= 20.0; // perfect two-item packing
            }
        } else {
            // Next item won't fit here: mild penalty proportional to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Compare against mean residual: penalize bins whose residual deviates
    // upward from the mean (they hoard space), reward below-mean residuals.
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.3 * (res - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin — reward it, but less if the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }
    // Crowded bin selection is generally good (consolidation).
    if open_bins_count > 1 && bin_residual < bin_capacity {
        score -= 2.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when no open bin offers a decent fit. Penalize the empty bin so we
    // only open it when existing fits are poor or the item is huge.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 40.0
            - 35.0 * poor_fit_elsewhere
            - 10.0 * big_item
            + 0.2 * (next_item_size as f64);
        // Late in the stream, avoid spawning bins with tiny leftovers demand.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * (1.0 - progress);
    }

    // Progress-aware tightening: as the stream advances, be greedier about
    // tight fits (less willing to leave medium residuals around).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (res / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item leaves little waste.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize creating small unusable residuals (dead space below typical item sizes).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 3.0 * (1.0 - (post_residual as f64 - 10.0) / 15.0);
    }

    // Lookahead (k=2): if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // Next item still fits but not perfectly: mild reward scaled by how much slack remains.
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; penalize leaving large residuals that trap the lookahead.
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item is large
    // (a fresh bin wastes little) or when many bins are open but residuals are fragmented.
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 18.0;
        let fragmentation_pressure = if mean_residual > 0.0 {
            (open_bins_count as f64).ln().max(0.0) * (item_size as f64 / mean_residual.max(1.0)).min(3.0)
        } else {
            0.0
        };
        score -= large_item_bonus + fragmentation_pressure;
        // Early in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * (1.0 - progress);
        // If next item is small, a fresh bin wastes capacity; penalize.
        if next_item_size > 0 && next_item_size < 30 {
            score += 5.0;
        }
    }

    // Mild global pressure: when mean residual across open bins is low, prefer existing bins
    // (they are nearly full anyway); when mean residual is high, encourage using fuller bins.
    if bin_residual != bin_capacity {
        score += 2.0 * (mean_residual / bin_capacity as f64);
        // Slight preference for bins below average residual (fuller than average).
        score += 1.5 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Late-stream consolidation: as we approach the end, minimize bin count by filling open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth non-linear coupling of residual waste with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress) + 2.0 * norm_pr * (1.0 - progress);
    score += 15.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let fit_ratio = item_size as f64 / cap;
    score -= 10.0 * fit_ratio * (1.0 + progress);

    // Penalize when this placement leaves residual too small for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 8.0 * (nx - pr) / cap * (0.5 + progress);
        } else {
            score -= 4.0 * (1.0 - (pr - nx) / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln() * 2.0 * norm_pr;

    // Discard near-empty residuals (dead space) with smooth term
    score += 20.0 * (norm_pr * (1.0 - norm_pr)).powi(2) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into a
    // "usable" residue class (divisible into common small item sizes) are favored.
    let harmonic_bonus = |r: u32| -> f64 {
        let mut h = 0.0;
        if r == 0 {
            h += 12.0; // perfect closure
        } else {
            if r % 10 == 0 { h += 5.0; }
            if r % 20 == 0 { h += 4.0; }
            if r % 25 == 0 { h += 3.0; }
            if r % 50 == 0 { h += 3.0; }
            // small leftovers are flexible
            if r <= 15 { h += 3.0; }
        }
        h
    };
    score -= harmonic_bonus(post_residual);

    // Penalize mid-range dead space (hard to fill later)
    if post_residual > 15 && post_residual < 40 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item exactly matches this bin's post-residual
    // (or a divisor class of it), reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if post_residual >= next_item_size && post_residual % next_item_size.max(1) == 0 {
            score -= 10.0;
        } else if next_item_size > post_residual {
            // next item won't fit here anyway; slight penalty for wasting large residual
            score += (post_residual as f64) * 0.1;
        }
    }

    // New-bin candidate handling: only prefer a fresh bin when all open fits are bad
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = (open_bins_count as f64) * 0.5 + (step_index as f64 / total_items.max(1) as f64) * 10.0;
        score += 15.0 + pressure; // default: discourage opening new bins
        if fitting_bins_count == 0 {
            score -= 40.0; // no open bin fits -> must open
        }
    }

    // Mild tie-break toward fuller bins and fewer open bins
    score -= (bin_capacity - bin_residual) as f64 * 0.05;
    score += open_bins_count as f64 * 0.1;
    score -= mean_residual * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward leaving room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0;
        } else {
            score += 15.0;
        }
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 40.0 + 5.0 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Prefer bins with residuals below the mean (tighter packing).
    score += ((mean_residual - bin_residual as f64) / bin_capacity as f64).max(-1.0) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/very tight fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose leftover matches the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() <= 2.0 {
            score -= 150.0; // next item fits this bin perfectly after current placement
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 80.0; // near-perfect two-item chain
        } else if post_residual < next_item_size {
            // Leftover too small for next item: penalize dead space, worse for large leftovers.
            score += (post_residual as f64) * 0.6;
        }
        // Chain tightness: smaller combined slack is better.
        score += (post_residual as f64 - next).abs() * 0.25;
    }

    // Relative to mean residual: prefer bins tighter than average when they fit well.
    let tightness = mean_residual - bin_residual as f64;
    score += tightness * 0.4;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 + item_size as f64 * 0.3;
    }

    // Penalize leaving large unusable gaps (below smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Mild preference for filling already-open bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        // New bin: only attractive when open bins are nearly full on average.
        score += mean_residual * 0.3 + open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with slight super-linear penalty on waste.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.5 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that next item cannot use: penalize proportional to wasted chunk.
        let waste = post_residual as f64 - (post_residual.min(next_item_size - 1) as f64);
        score += 0.15 * waste;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate logic: an empty bin has full residual; make it unattractive unless
    // no open bin fits well or item is large relative to mean residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Prefer new bin for large items late in the stream, or when mean residual is small.
        let new_bin_bonus = 40.0
            - 30.0 * item_frac
            - 20.0 * progress
            - 0.5 * mean_residual;
        score += new_bin_bonus;
        // If many bins already open, discourage proliferation.
        score += 0.4 * open_bins_count as f64;
    }

    // Mild preference for bins below mean residual (balance residual distribution).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr * norm_pr);

    // Tight fits are strongly rewarded (low post_residual), more so later in the stream
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize bins far from the mean residual (fragmentation avoidance)
    score += 0.15 * (pr - mean_residual).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead coupling: reward bins whose post_residual can hold the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - pr / (pr + nxt)) * (1.0 - progress * 0.5);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Slight penalty for very small items into large residual (waste avoidance)
    let waste_ratio = pr / (item_size as f64 + pr + 1.0);
    score += 3.0 * waste_ratio * waste_ratio * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands in "reusable" bands
    // (multiples of 10 / large enough for common small items) are rewarded.
    let pr = post_residual;
    let class_bonus = match pr {
        0 => -40.0,                      // perfect fit: heavily reward
        p if p % 10 == 0 => -12.0,       // harmonic decade residual
        p if p >= 10 && p < 20 => -6.0,  // fits smallest items
        p if p >= 50 => -4.0,            // still broadly usable
        _ => 0.0,
    };
    score += class_bonus;

    // Integer-division dead-space penalty: residuals that cannot fit any typical item
    // (pr < 10) are dead space -> penalize.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if post_residual exactly accommodates next item.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 18.0;
        } else if pr >= next_item_size {
            score -= 4.0;
        } else {
            // next item cannot go here; mild penalty scaled by how badly it misses
            score += (next_item_size - pr) as f64 * 0.15;
        }
        // Harmonic pair: pr + next_item_size hits a decade boundary exactly
        if (pr + next_item_size) % 10 == 0 && pr >= next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if pr >= 10 || pr == 0 {
            score -= 20.0;
        } else {
            score -= 5.0; // still prefer it slightly, but dead space tempers it
        }
    }

    // New-bin candidate handling: make the empty bin attractive only when open bins
    // are mostly full / fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if mean_residual > 0.0 { mean_residual / cap } else { 0.0 };
        // Default: new bin is worse than a decent fit.
        score += 30.0;
        // But if few fitting bins and mean residual is small, opening fresh is good.
        if fitting_bins_count <= 1 || fragmentation < 0.25 {
            score -= 25.0 + 10.0 * (1.0 - fragmentation);
        }
        // Early in stream, new bins are cheap.
        if progress < 0.2 {
            score -= 8.0;
        }
        // Too many open bins with high mean residual: avoid spreading.
        if open_bins_count > 8 && mean_residual > 40.0 {
            score += 20.0;
        }
    }

    // Tightness reward: prefer bins that end up tightly packed (post_residual small
    // relative to what was there), harmonic via integer division of residual by item.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Modulo-3 harmonic jitter on post_residual to break ties deterministically.
    score -= (pr % 3) as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps: post_residual in (0, min_item] is dead space.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size.min(20)) {
        score += 50.0;
    }
    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Reward using bins when few bins fit the item (last-chance pressure).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // over opening new ones.
    let open_pressure = open_bins_count as f64 * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 20.0 + open_pressure;
    } else {
        score -= open_pressure * 0.5;
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Lookahead: if next item could use the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += (next_item_size as f64 - post_residual as f64).abs() * 0.2;
    }

    // Slight preference to fill earlier bins as stream progresses.
    score += (step_index as f64 / total_items.max(1) as f64) * 2.0;

    // Deviation from mean residual: prefer bins tighter than average.
    score += (bin_residual as f64 - mean_residual).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: aggressive 2-step lookahead matching.
    // Reward bins whose post_residual exactly (or nearly) matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: strong reward.
        if post_residual == next_item_size {
            score -= 40.0;
        } else {
            // Smooth proximity reward, decaying with distance.
            let proximity = 20.0 / (1.0 + diff / 8.0);
            score -= proximity;
        }
        // Penalize post_residuals that are too small to fit the next item
        // unless the residual is tiny anyway (dead space is fine).
        if next_item_size > post_residual && post_residual > 0 {
            let unusable = (next_item_size - post_residual) as f64;
            score += 0.8 * unusable;
        }
        // If the next item fits exactly into current residual (not post),
        // placing here wastes a perfect future fit elsewhere; mild penalty.
        if bin_residual == next_item_size && post_residual > 0 {
            score += 5.0;
        }
    } else {
        // Last item: prefer tightest fit only.
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are
    // already tight; filling them is good. Bins far above mean are loose;
    // penalize leaving large slack there.
    let rel = (bin_residual as f64) - mean_residual;
    score += 0.15 * rel.max(0.0) - 0.05 * (-rel).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is a blank slate. Prefer it
    // only when the item is large relative to typical open-bin slack, or
    // when no open bin offers a decent fit. Otherwise make it unattractive
    // so fragmentation is avoided.
    if bin_residual == bin_capacity {
        let slack = mean_residual;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Large items (relative to mean slack) justify a fresh bin.
        if item_frac > 0.6 || (fitting_bins_count == 0) {
            score -= 15.0;
        } else {
            score += 12.0 + 0.2 * slack;
        }
    }

    // Mild stream-progression pressure: late in the stream, consolidate
    // into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 8.0 * progress;
    } else {
        score -= 3.0 * progress;
    }

    // Slight preference for bins with few competitors fitting.
    score += 0.5 * (fitting_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit core: prefer tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 4.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Penalize creating dead space the next item cannot use,
            // scaled by how dead the space is.
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate: default is mildly unattractive; only attractive
    // when existing fits are poor (large post_residual) or no bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 - 10.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_residual - item_size.min(bin_residual) {
            score -= 2.0;
        }
        // Late in stream, opening new bins is fine since few items remain.
        let remaining = total_items.saturating_sub(step_index) as f64;
        score -= (remaining / total_items.max(1) as f64) * 5.0;
    }

    // Global state coupling: when mean residual is high (lots of slack
    // spread around), prefer consolidating into fuller bins.
    score += 0.05 * (mean_residual - post_residual as f64);

    // Prefer bins with more open bins available (less pressure on this one)
    // when this bin would be left with tiny unusable residual.
    if post_residual > 0 && post_residual < 10 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let prog2 = progress * progress;
    let coupling = pr_norm * pr_norm * (0.5 + 2.0 * progress) + pr_norm * (1.0 - progress) * (1.0 - progress);
    score += 12.0 * coupling;

    // Reward tight fits more strongly as the stream progresses (smooth interaction)
    let tightness = (item_size as f64) / cap;
    score -= 8.0 * tightness * (0.3 + 0.7 * progress);

    // Penalize leaving dead space that next item cannot use (smooth penalty)
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            let g = gap / cap;
            score += 6.0 * g * g * (1.0 - progress);
        } else {
            // next item fits exactly-ish: reward
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it (smooth with progress)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild pressure to prefer bins below mean residual (balance open bins)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * dev - 1.5 * dev * (1.0 - progress);

    // New-bin candidate: penalize opening new bins early, allow late in stream
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) * (1.0 - progress) + 4.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity-fraction bucket it lands in.
    let class = post_residual / 10; // 0..10 deciles of capacity
    // Dead-space penalty grows super-linearly for small unusable residuals.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward landing in "harmonic" residual classes divisible by common item sizes (mod logic).
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 12.0; }
        else if post_residual % 5 == 0 { score -= 6.0; }
    }
    // Perfect fit: maximal reward.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Next-item lookahead coupling: does the residual land in a class that can host the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Good chain: reward if post-residual class aligns with next item's class.
            if post_residual - next_item_size < 10 {
                score -= 18.0; // chain leaves near-zero dead space
            } else {
                score -= 6.0;
            }
            // Integer-division threshold: residual >= 2*next means double chaining possible
            if post_residual >= 2 * next_item_size {
                score -= 4.0;
            }
        } else {
            // Post-residual too small for the next item: penalize proportionally to wasted potential.
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.8;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer fuller bins among many open bins (mild density pressure).
    score -= (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Late in the stream, be more conservative: penalize leaving medium residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.15;

    // New-bin candidate: only attractive when residual would be tiny elsewhere or stream is early.
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are nearly useless
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable dead space (min item is 1..100, but small gaps rarely usable)
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item (k=2)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            score -= 10.0; // bin stays usable for the next item
        } else {
            score += 15.0; // next item cannot use this bin
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: discourage opening new bins when existing ones fit well
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive if open bins are crowded
        score += 30.0 + 8.0 * open_bins_count as f64;
        if mean_residual < item_size as f64 * 0.5 {
            score -= 20.0; // open bins are tight; new bin is reasonable
        }
    } else {
        score -= 3.0 * open_bins_count as f64; // favor filling existing bins
    }

    // Late in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 20.0 * progress;
    }

    // Mild preference for bins tighter than the mean (best-fit flavor)
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item fits with small slack afterwards.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item will not fit in this residual: penalize dead space.
        score += 15.0;
    }

    // Reward tight fits relative to mean residual of open bins.
    if (post_residual as f64) < mean_residual {
        score -= 0.5 * (mean_residual - post_residual as f64);
    } else {
        score += 0.3 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize tiny unusable residuals (dead space below min item size).
    if post_residual < 10 {
        score += 5.0;
    }

    // New-bin candidate: open a fresh bin only when current bins have poor
    // residuals and the next item is large (fresh bin keeps flexibility).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_open = mean_residual < item_size as f64 * 0.5;
        let big_next = next_item_size as f64 > mean_residual;
        if poor_open || (big_next && open_bins_count > 2) {
            score -= 20.0 * (0.5 + progress);
        } else {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Penalize leaving dead space that nothing can use later:
    // residual smaller than the smallest plausible item is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big bonus;
    // if the next item would fit better elsewhere, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to leftover waste
            score += 2.0;
        }
    }

    // New-bin candidate handling: opening a bin is only attractive when existing
    // bins fit poorly (high mean residual mismatch) or few bins are open.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_bin_cost = 18.0;
        // Cheaper to open early in the stream when the future is long.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_cost -= 8.0 * (1.0 - progress);
        // More expensive when many bins are already open (encourage consolidation).
        new_bin_cost += 1.5 * open_bins_count as f64;
        // If mean residual of open bins is large, they are roomy: discourage new bin.
        new_bin_cost += mean_residual * 0.25;
        score += new_bin_cost;
    } else {
        // Using an existing bin: small reward scaled by how full it already is.
        let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 4.0 * fill;
        // Prefer bins with residual below the mean (denser bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Time-horizon modulation: late in the stream, be greedy about tight fits.
    let horizon = step_index as f64 / (total_items as f64).max(1.0);
    score -= 5.0 * horizon * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: penalize wasted residual, but with diminishing effect for tiny leftovers
    let mut score = pr as f64;

    // Smooth non-linear waste penalty: dead space between 1 and ~half capacity is worst
    score += 40.0 * fit_norm * (1.0 - fit_norm) * (1.0 - fit_norm) * cap * 0.25;

    // Stream-progress coupling: early on, prefer tight packing (low post_residual);
    // later, allow looser fits to keep bins usable
    let tightness = (1.0 - progress) * (1.0 - progress);
    score += tightness * 30.0 * fit_norm;
    score -= progress * 20.0 * fit_norm * fit_norm;

    // Interaction with mean residual: placing into a bin near the mean residual is neutral;
    // deviating wastes either small or large space
    let dev = (fit_norm - mean_residual / cap).abs();
    score += 15.0 * dev * dev * cap;

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: reward leaving room for the next item if it fits; penalize otherwise
    if next_item_size > 0 {
        let nres = next_item_size as f64;
        if post_residual as f64 >= nres {
            score -= 25.0 * (nres / cap);
        } else {
            score += 10.0 * (1.0 - pr / nres.max(1.0));
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // residue classes modulo 10 (fine granularity) and capacity fractions.
    let residue_class = post_residual % 10;
    // Dead space penalty: small nonzero leftovers are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    } else if post_residual <= 20 {
        score += 6.0; // modest dead space
    }

    // Harmonic fraction penalty: leftover that is a small fraction of capacity
    // but larger than any plausible next item is wasted.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.0 && frac < 0.3 {
        score += 8.0 * (0.3 - frac);
    }

    // Lookahead coupling: reward if the next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Tighter coupling when next item nearly fills the leftover.
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use this leftover: penalize proportionally.
            score += 4.0 + 0.05 * (next_item_size - post_residual) as f64;
        }
        // Harmonic class match: if next item's size class matches residue class,
        // the leftover is "harmonic" and reusable.
        if next_item_size % 10 == residue_class && next_item_size <= post_residual {
            score -= 5.0;
        }
    } else {
        // Last item: prefer perfect closure, otherwise leftover is pure waste.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity and many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Penalize new bins generally, discount when item is big or stream early.
        score += 18.0 - 20.0 * item_frac - 6.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 10.0; // extra penalty since alternatives exist
        }
    }

    // Mild preference for bins below mean residual (balance / spread filling).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Prefer filling already-open bins when many are open (limit bin sprawl).
    score += 0.3 * open_bins_count as f64;

    // Tie-break: prefer earlier bins slightly (deterministic stabilization).
    score += 0.01 * (post_residual % 7) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals that are too small for any item (1..=10)
    // are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to residual (best-fit flavor).
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // filling existing bins and discourage opening yet another bin.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; allow only when the
        // alternative would leave large dead space or no bin fits well.
        score += 30.0 + pressure * 12.0;
        // If lookahead item can pair with this item in a fresh bin, soften.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 20.0;
        }
    } else {
        // Existing bin: mild bonus for keeping bin count low.
        score -= pressure * 2.0;
    }

    // Lookahead synergy: if next item exactly fills the resulting residual,
    // reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item would NOT fit the post residual, mild penalty for stranding.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += (post_residual as f64) * 0.5;
    }

    // Mean-residual coupling: bins far below mean residual are "fresher";
    // prefer filling bins with large residual first (keep small-residual bins
    // for small items later).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Stream progression: late in the stream, be more conservative about
    // opening bins (fewer future items to fill them).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += progress * 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item fits tightly into post residual.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Reward tight fits, penalize loose leftover space nonlinearly.
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        score += 0.5 * slack;
    }
    // Next item cannot fit in the leftover: dead space unless residual is tiny.
    else if next_item_size > 0 {
        // Penalize unusable residual, scaled by how "wasted" it is.
        let waste = post_residual as f64;
        score += 0.8 * waste * waste / bin_capacity as f64;
        // Small residual (<10) is nearly dead space; discourage leaving it.
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Prefer bins whose residual is above mean (consume large residuals first),
    // but strongly prefer exact fits regardless.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 5.0 * dev;

    // Last-chance bin: if this is the only bin that fits, avoid forcing a new bin
    // unless the fit is very loose.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual for empty bin = capacity - item_size, handled naturally).
    if bin_residual == bin_capacity {
        // Slight penalty so open bins with tight fits win; removed when lookahead
        // rewards dominate.
        score += 12.0;
        // Late in the stream, opening fresh bins is less desirable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) non-linearly.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is gold
    } else if post_residual < 10 {
        score -= 25.0;
    } else {
        score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Penalize dead space that can't fit even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            score -= 10.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // next item won't fit here; slight penalty for leaving large residual
            score += 3.0;
        }
    }

    // Time horizon: early in stream, be more willing to open new bins (favor
    // tight fits only); late in stream, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: accept early, penalize later.
        score += 12.0 * progress - 5.0 * (1.0 - progress);
        // If many bins open and mean residual is large, discourage new bin.
        score += 0.5 * open_bins_count as f64;
        score += 0.3 * mean_residual;
    } else {
        // Existing bin: reward more when stream is near the end.
        score -= 8.0 * progress;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 0.4 * open_bins_count as f64 * (bin_residual == bin_capacity) as i32 as f64;

    // Deviation from mean residual: prefer bins tighter than average.
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // base: penalize wasted space, quadratically amplified
    let mut score = pr * (1.0 + 0.02 * pr / cap);

    // smooth non-linear coupling of residual waste with stream progress
    let w = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += w * 30.0 * norm_pr * norm_pr;

    // reward tight fits: non-linear in item size
    score -= 25.0 * (it / cap) * (1.0 - (it / cap)) * (1.0 - w);

    // last-chance bonus (only fitting bin)
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - norm_pr);
    }

    // penalty when many bins compete (prefer spreading)
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // lookahead: penalize leaving residual smaller than next item
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 8.0 * ((next_item_size as f64 - pr) / cap);
    } else if next_item_size > 0 {
        score -= 6.0 * (pr / (next_item_size as f64 + 1.0)).min(1.0);
    }

    // mean residual coupling: penalize deviating far from mean state
    score += 0.1 * (pr - mean_residual).abs();

    // new-bin candidate: mild preference early, harder to open late
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * w;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo common item sizes
    let pr = post_residual;
    let small = pr.min(100 - pr.min(100)); // symmetry around half-capacity
    let residue_penalty = ((pr % 10) as f64) * 0.4 + ((pr % 25) as f64) * 0.3;
    score += residue_penalty;

    // Reward perfect / near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Harmonic coupling: does next_item_size divide or fit into post_residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            // next item fits here: strong reward, scaled by how snugly
            let snug = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 60.0 + 80.0 * snug;
            if post_residual % next_item_size == 0 {
                score -= 40.0; // exact harmonic multiple
            }
        } else {
            // next item won't fit: penalize leftover dead space
            score += 30.0 + (post_residual as f64) * 0.5;
        }
    } else {
        // last item: prefer filling bins as tightly as possible
        score -= 150.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is justified only if current bin leaves bad dead space
        let waste = post_residual as f64;
        if waste > 0.35 * cap {
            score -= 90.0; // prefer fresh bin over wasting space
        } else {
            score += 150.0; // keep filling existing bins when fit is decent
        }
        // discourage many open bins early in stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += open_bins_count as f64 * 8.0 * (1.0 - progress);
    }

    // Prefer bins with residual far below mean (tight bins first)
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Integer-division thresholds: bins with post_residual in "dead zones" penalized
    if pr >= 11 && pr <= 19 {
        score += 25.0; // awkward dead zone
    }
    if pr >= 21 && pr <= 29 {
        score += 15.0;
    }
    if pr >= 31 && pr <= 39 {
        score += 8.0;
    }

    // Favor bins whose residual is a harmonic fraction of capacity (50, 25, 75)
    if pr == 50 || pr == 25 || pr == 75 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can't fit even the smallest
    // future item (<10) are pure waste; penalize them heavily.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Small gaps that fit nothing likely coming next: dead space penalty.
    if post_residual > 0 && next_item_size > post_residual {
        score += 8.0 + 0.25 * (next_item_size - post_residual) as f64;
    }

    // Reward perfect or near-perfect fills.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward tight fits relative to bin residual (best-fit style coupling).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing bins
    // and discourage opening new ones.
    let pressure = (open_bins_count as f64 / 10.0).min(3.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost grows with open bins and mean residual.
        score += 10.0 + 6.0 * pressure + 0.1 * mean_residual;
        // Late in the stream, opening new bins is even less attractive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 8.0 * progress;
        // But if this bin would be nearly wasted anyway (huge item, big gap left),
        // a fresh bin can be fine.
        if item_size >= 70 {
            score -= 15.0;
        }
    } else {
        // Existing bins get a mild discount scaled by open-bin pressure.
        score -= 4.0 * pressure;
        // If the leftover after placement can host the next item, reward it.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // 2-step lookahead: reward residuals that exactly match the next item,
    // penalize residuals that are just barely too small for it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual > next_item_size {
            // next item fits here too: mild bonus proportional to tightness
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item cannot fit: dead-space penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.8 * gap;
        }
    }

    // Compare residual against mean residual: prefer bins tighter than average.
    score += 0.6 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 120.0;
        // Allow new bin late in stream when many bins are open and fit is poor.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual as f64 > 0.6 * bin_capacity as f64 && progress > 0.3 {
            score -= 60.0;
        }
    }

    // Deter wasteful placements into large-residual bins.
    if post_residual > 40 {
        score += 0.3 * (post_residual - 40) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strong bonus when the item nearly fills the bin.
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fill is heavily favored.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead: bonus if the next item fits exactly into the post residual,
    // penalty if post residual is a "dead space" trap the next item can't use.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size > post_residual {
            // dead space unless item is small relative to capacity
            let dead_frac = post_residual as f64 / bin_capacity as f64;
            score += 40.0 * dead_frac;
        } else {
            // next item fits: mild reward proportional to how much it consumes
            score -= 20.0 * (nr / post_residual as f64);
        }
    } else {
        // Last item: prefer leaving zero residual.
        score += 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing bins fit poorly.
    if bin_residual == bin_capacity {
        let prog = step_index as f64 / (total_items.max(1) as f64);
        let waste = if fitting_bins_count > 0 {
            // best possible residual among fitting bins approximated by mean residual
            (mean_residual - item_size as f64).max(0.0)
        } else {
            0.0
        };
        score = 100.0 + prog * 20.0 + waste * 0.5 + (open_bins_count as f64) * 2.0;
        // If the item is large, a fresh bin is often fine.
        if item_size >= 60 {
            score -= 40.0;
        }
    } else {
        // Mild penalty for leaving many tiny-residual bins scattered.
        let frag = (post_residual as f64 - mean_residual).abs();
        score += 0.3 * frag;
    }

    // Prefer bins whose residual is close to the item (best-fit core).
    score += 0.1 * ((bin_residual as f64 - item_size as f64)).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let pr = post_residual as f64;

    // Core non-linear fit quality: strongly reward small post_residual.
    let mut score = pr * pr / bin_capacity as f64;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space becomes more costly.
    let coupling = 1.0 + 2.0 * progress * progress;
    score *= coupling;

    // Reward near-perfect fits with a smooth bonus term.
    let fit_ratio = 1.0 - pr / bin_capacity as f64;
    score -= 10.0 * fit_ratio * fit_ratio * fit_ratio;

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - gap / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin for one item.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // Penalize spreading across many open bins slightly; encourage consolidation.
    score += 0.5 * open_bins_count as f64 * (pr / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin, but less when existing
    // residuals are large (poor fits) or late in the stream when consolidation
    // is less valuable.
    if is_new_bin {
        let open_pressure = (open_bins_count as f64 / (1.0 + progress)).min(10.0);
        score += 12.0 + 2.0 * open_pressure - 6.0 * progress;
    } else {
        // Mild reward for bins already tighter than the mean residual.
        if (bin_residual as f64) < mean_residual {
            score -= 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "reusable" is the leftover space?
    // Class residuals into buckets of 10 (capacity fractions). Small leftovers are dead space.
    let post_class = (post_residual / 10).min(10) as f64;

    // Penalize dead space super-linearly for tiny residuals (waste).
    if post_residual <= 10 {
        score -= 40.0 - 2.0 * post_residual as f64; // perfect fit reward
    } else if post_residual <= 20 {
        score -= 12.0;
    } else if post_residual <= 30 {
        score -= 4.0;
    } else {
        // Large leftover: mild penalty scaled by class, encouraging tight fits
        score += post_class * 0.8;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chained harmonic packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let leftover2 = post_residual - next_item_size;
            if leftover2 <= 10 {
                score -= 25.0;
            } else {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here: prefer bins whose post-residual is a
            // "harmonic" size (multiple of 10) that other items may match.
            if post_residual % 10 == 0 {
                score -= 3.0;
            } else {
                score += (post_residual % 10) as f64 * 0.5;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when all
    // open bins would leave very awkward residuals.
    if bin_residual == bin_capacity {
        // Neutral base for new bin; it competes via its residual (== capacity),
        // so give it a moderate handicap that tight fits can overcome.
        score += 25.0;
        // Early in the stream, opening bins is cheap-ish; late, discourage it.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If many bins are already open, discourage one more.
        score += open_bins_count as f64 * 1.5;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean
    // (it's already small), using it up is good housekeeping.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.3;
    } else {
        score += (-diff) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (min size 1..~10) are pure waste; penalize
    // small nonzero gaps super-linearly.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 40.0 * (1.0 - post_residual as f64 / 11.0); // worst for tiny gaps
        } else if post_residual < 25 {
            score += 8.0; // moderately unusable zone
        } else {
            score -= 6.0; // large usable residual is fine
        }
    } else {
        // Perfect fit: strong reward
        score -= 30.0;
    }

    // Reward when this bin can also fit the lookahead item after placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // lookahead won't fit here: mild penalty scaled by wasted potential
            score += 3.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer packing existing bins
    // (penalize new-bin candidate / discourage spreading).
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): penalize unless current bins are tight.
    if bin_residual == bin_capacity {
        let avg_tightness = mean_residual / bin_capacity as f64;
        // open new bin only if open bins are mostly full
        score += 20.0 - 30.0 * avg_tightness;
        score += 5.0 * open_bins_count as f64;
    }

    // Mean-residual coupling: if mean residual is small (bins nearly full),
    // reward placements that preserve large residuals elsewhere.
    score += 0.1 * (mean_residual - post_residual as f64);

    // Slight preference for tight fits relative to bin residual
    score += 0.2 * (bin_residual - item_size) as f64 * 0.0; // no-op guard
    score += 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead: exact match leaves zero waste across two items ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-item fill: item + next item exactly fill this bin.
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement; reward tightness of the fit.
            let slack_after_pair = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack_after_pair / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover residual: penalize dead space,
            // scaled by how much of it is stranded.
            let stranded = next_item_size as f64 - post_residual as f64;
            score += 0.5 * stranded;
        }
    }

    // --- Tightness of the current fit ---
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 8.0 * tightness * tightness;

    // --- Prefer bins whose residual is already small (consolidate waste) ---
    let rel_residual = post_residual as f64 / bin_capacity as f64;
    score += 10.0 * rel_residual * rel_residual;

    // --- Last-chance bin: strongly favor using it to avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // --- New-bin candidate: only attractive when it enables a great pair fill ---
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            let pair_slack = (post_residual - next_item_size) as f64;
            if pair_slack == 0.0 {
                score -= 45.0; // fresh bin can be filled perfectly by the pair
            } else if pair_slack <= 10.0 {
                score -= 20.0;
            }
        }
        // Late in the stream, opening new bins is cheaper than stranding space.
        let progress = step_index as f64 / total_items as f64;
        score -= 8.0 * progress;
    }

    // --- Mild bias toward bins with low mean residual (balance-aware) ---
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit shaping: penalize large wasted space non-linearly.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste * waste;

    // Reward tight fits (small post residual) strongly.
    if post_residual < 5 {
        score -= 25.0;
    } else if post_residual < 15 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 18.0 - 0.5 * gap;
        if post_residual == next_item_size {
            score -= 20.0; // perfect chain
        }
    }
    // If next item cannot fit in post residual but could fit elsewhere, mild penalty.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Discourage opening new bins when healthy open bins exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 + 8.0 * (1.0 - progress);
        // If mean residual across open bins is small (fragmented), new bin is more attractive.
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 10.0;
        // If this bin is the only fitting option, opening new bin is bad.
        if fitting_bins_count <= 1 {
            score += 25.0;
        }
    }

    // Prefer filling bins with small residuals relative to fleet average.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.08 * diff;

    // Slight preference for bins whose residual is close to item size (snug fit).
    let snug = (bin_residual - item_size) as f64;
    score += 0.15 * snug;

    // Mild penalty for too many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual

    // Non-linear polynomial coupling of post_residual with stream progress
    let base = pr * (1.0 + 0.6 * progress) - 0.8 * pr * x * (1.0 - progress);
    let quad = -12.0 * x * x * (1.0 - progress) - 4.0 * x * progress;

    let mut score = base + quad;

    // Reward tight fits smoothly: strong penalty for small post_residual
    let tight = (1.0 - x).powi(3);
    score -= 15.0 * tight * (1.0 + 0.5 * progress);

    // Penalize large unusable dead space relative to mean residual
    let dead = ((pr as f64) - mean_residual).max(0.0) / cap;
    score += 10.0 * dead * dead;

    // Last-chance bin: reward using it
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits in post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - (pr - next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        score += 3.0 * (next_item_size as f64 - pr) / cap;
    }

    // Mild penalty for spreading across many bins early
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: neutral baseline so it wins only over poor fits
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - progress) - 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact-fill classes are golden.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward exact fills heavily.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: residuals divisible into capacity fractions
    // (C/2=50, C/3~33, C/4=25, C/5=20) are more reusable.
    for &div in &[50u32, 25, 20, 10, 5] {
        if post_residual > 0 && post_residual % div == 0 {
            score -= div as f64 * 0.4;
        }
    }

    // Penalize awkward residuals: small prime-ish dead zones (1..5, 6..9)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead coupling: can next item exactly fit the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            // harmonic class of the double residual
            if gap % 25 == 0 || gap % 20 == 0 || gap % 10 == 0 {
                score -= 60.0;
            }
            score += gap as f64 * 0.15;
        } else {
            // next item won't fit here; mild penalty scaled by how much it overshoots
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    } else {
        // last item: prefer tightest fill
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a fresh bin for one item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad residue
    // and there are many open bins already.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = if post_residual > 0 && post_residual < 20 { 1.0 } else { 0.0 };
        score += 40.0 - 120.0 * bad_fit - 30.0 * progress;
        // discourage hoarding new bins when many open with slack
        score += open_bins_count as f64 * 2.0;
        score += (mean_residual - post) * 0.3;
    }

    // Prefer filling fuller bins among equals (best-fit reinforcement).
    score -= (bin_residual as f64 / cap) * 10.0;

    // Mean-residual alignment: bins deviating from mean residual are slightly
    // deprioritized unless the item creates harmonic residual.
    let dev = (mean_residual - bin_residual as f64).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 3.0;
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins that can still hold the lookahead item after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.05 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // leftover too small for lookahead: mild penalty
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading.
    score += open_bins_count as f64 * 0.3;

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., many fitting bins but all poor fits) — keep default high-ish,
    // discount slightly when item is large and mean residual is small.
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size > 60 && mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    // Slight preference for tighter fits as stream progresses.
    score += (step_index as f64 / total_items.max(1) as f64) * 2.0
        * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a superlinear penalty
    // on wasted space relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * waste_frac * waste_frac;

    // Aggressive 2-step lookahead: reward bins whose post_residual can exactly
    // (or nearly) host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let gap = post_residual as f64 - nxt;
            // Exact match is ideal; decaying reward as gap grows.
            score -= 45.0 * (-gap / 12.0).exp();
            // Extra bonus if the pair nearly fills the bin completely.
            if gap <= 3 {
                score -= 20.0;
            }
        } else {
            // Next item cannot fit here: mild penalty proportional to shortfall,
            // encouraging bins that chain items together.
            let shortfall = nxt - post_residual as f64;
            score += 8.0 * (-shortfall / 20.0).exp();
        }
    } else {
        // Last item: just minimize residual.
        score -= 10.0;
    }

    // Compare against mean residual: bins already tighter than average are
    // worth closing out (reward placing into below-average-residual bins).
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = (res_f - mean_residual) / mean_residual;
        score += 15.0 * rel; // larger-than-average residual -> penalize
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when the item
    // is large relative to capacity or no open bin fits well.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        let crowd = open_bins_count as f64;
        // Base cost of opening a new bin, discounted when bins are scarce or
        // the item is huge (poor fit anywhere else).
        let mut open_cost = 55.0 - 0.6 * crowd;
        if fill > 0.7 {
            open_cost -= 40.0 * (fill - 0.7) / 0.3;
        }
        // If next item is also large, a fresh bin gives it room.
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * bin_capacity as f64 {
            open_cost -= 15.0;
        }
        score += open_cost.max(-10.0);
    }

    // Slight stream-phase awareness: late in the stream, consolidate more
    // aggressively (avoid new bins).
    if total_items > 0 {
        let phase = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += 25.0 * phase;
        } else {
            score -= 10.0 * phase;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post-residual, non-zero)
    if post_residual > 0 {
        score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    } else {
        // perfect fill
        score -= 40.0;
    }

    // Penalize dead space that no plausible future item can use:
    // residuals smaller than the minimum item size are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 0.05 * next_item_size as f64;
    }
    // If next item is bigger than post_residual but this bin is nearly full,
    // that's fine (bin is "closed" naturally).
    if next_item_size > post_residual && post_residual <= 15 && post_residual > 0 {
        score -= 4.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoids opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Encourage packing into more-filled bins (best-fit bias via residual ratio)
    score += (bin_residual as f64 / bin_capacity as f64) * 6.0;

    // New-bin candidate handling: opening a new bin is expensive early,
    // acceptable late or when open bins have poor residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_penalty = open_bins_count as f64 * 1.5;
        let mean_gap = (mean_residual - item_size as f64).abs();
        let mut new_bin_score = 30.0 + open_penalty + 20.0 * (1.0 - progress);
        // If no open bin really fits well, opening new bin is less bad
        if mean_gap > 20.0 {
            new_bin_score -= 10.0;
        }
        // Late in stream, prefer filling existing bins
        if progress > 0.7 {
            new_bin_score += 15.0;
        }
        score += new_bin_score;
    }

    // Slight preference to balance residual usage across bins vs mean
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Polynomial coupling of post-residual with stream progress:
    // early on, tolerate waste slightly; late, punish it more.
    let progress_coupling = 1.0 + 1.5 * progress * progress + 0.7 * progress;
    score *= progress_coupling;

    // Smooth penalty for leaving residual that matches the lookahead item:
    // reward when next item fits into post_residual (smooth via ratio).
    if next_item_size > 0 {
        let fit_ratio = (next_item_size as f64 / (pr + 1.0)).min(1.0);
        let bonus = if next_item_size as u32 <= post_residual {
            -6.0 * (1.0 - fit_ratio) * (1.0 + progress)
        } else {
            2.0 * fit_ratio * (1.0 + progress)
        };
        score += bonus;
    }

    // Last-chance bin: smooth reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 - norm_pr) * (0.5 + progress);
    }

    // Mild penalty for scattering across many bins when mean residual is large.
    let mean_norm = mean_residual / cap;
    score += 0.3 * open_bins_count as f64 * mean_norm * mean_norm * progress;

    // Slight smooth preference for filling tighter bins (relative to mean).
    score -= 1.5 * (mean_residual - bin_residual as f64) / cap * (0.5 + progress);

    // New-bin candidate: smooth baseline with progress-dependent reluctance.
    if bin_residual == bin_capacity {
        score = cap as f64 * (1.2 + 0.8 * progress) + 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that fall into
    // "usable" classes (multiples of common small item sizes), penalize others.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -40.0 // perfect fit is king
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 5 == 0 {
        -4.0
    } else if pr % 3 == 0 {
        -2.0
    } else {
        3.0 // awkward dead space
    };
    score += harmonic_bonus;

    // Integer-division threshold on post_residual: residuals below the smallest
    // plausible item size are dead space; penalize quadratically.
    if pr < 10 {
        score += (10 - pr) as f64 * 2.5;
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // reward; if it almost fits (within a small gap), mild penalty.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 6.0 + (pr - next_item_size) as f64 * 0.1;
        } else if next_item_size - pr <= 5 {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity equal to
    // the mean residual of open bins; make it costly unless everything is full.
    if bin_residual == bin_capacity {
        let waste = mean_residual.max(0.0);
        score = 60.0 + waste * 0.8 + open_bins_count as f64 * 0.5;
        // If all open bins are nearly full, a new bin is fine.
        if mean_residual < 8.0 {
            score -= 30.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Slight preference for bins with residual close to the item (tight fit)
    // beyond the raw post_residual ordering.
    score += (bin_residual as f64 - item_size as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps (<10) are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Medium dead space (10..25) is also hard to reuse.
    if post_residual >= 10 && post_residual < 25 {
        score += 25.0;
    }
    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins that were already fairly full (tight packing).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Pressure from number of open bins: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it before opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when nothing fits well,
    // i.e., penalize the fresh bin unless the item would leave a big reusable gap.
    if bin_residual == bin_capacity {
        score += 35.0;
        // But if item is large relative to capacity, new bin wastes less.
        score -= 0.3 * item_size as f64;
        // Early in the stream, opening bins is cheaper.
        score -= 20.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Lookahead coupling: if next item fits the post_residual, this placement is great.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item almost fits but not quite, this bin becomes a trap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Prefer bins with below-average residual (they are the "dying" bins to close out).
    if bin_residual != bin_capacity && (post_residual as f64) < mean_residual {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack left afterwards.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 40.0 - (slack as f64).min(40.0);
    }
    // Next item does NOT fit after this placement: penalize dead space creation.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Relative residual coupling: residual much below mean residual means tight fit (good).
    let rel = post_residual as f64 - mean_residual;
    score += 0.3 * rel;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins exist and this is the new-bin candidate.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 10.0 + 0.2 * mean_residual;
    }

    // Late in stream: prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * fill_ratio * fill_ratio;

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive if existing residuals are fragmented
    // (mean residual high but unusable) or we are early with many future items.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Penalize new bins generally, less so when residuals are wasted space.
        score += 30.0 - 20.0 * fragmentation * (1.0 - progress);
        // If no open bin fits tightly, new bin becomes more acceptable.
        if post_residual == 0 {
            score -= 15.0;
        }
    }

    // Lookahead: penalize leaving a residual that fits nothing like the next item,
    // reward leaving residual that pairs well with it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit in the leftover; mild penalty scaled by waste.
            score += 0.08 * post_residual as f64;
        }
    } else {
        // Last item: prefer filling as much as possible.
        score += 0.05 * post_residual as f64;
    }

    // Prefer reusing bins with low residual overall (consolidate waste).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs().min(50.0);

    // Time horizon: early in the stream, keep bins flexible (mild penalty on tiny leftovers);
    // late in the stream, just minimize waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.5 && post_residual > 0 && post_residual < 10 {
        score += 8.0 * (1.0 - progress);
    }

    // Slight penalty for spreading across too many open bins.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual (waste minimization)
    let mut score = pr;

    // Non-linear polynomial coupling with stream progress
    // Early: prefer tight fills (penalize residual strongly, super-linearly)
    // Late: residual penalty softens slightly, allow opening bins
    let progress_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep in [0,1]
    score += (1.0 - progress_poly) * norm_pr * norm_pr * 40.0;

    // Reward near-perfect fits: quadratic bonus on small post_residual
    let fit_bonus = (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= fit_bonus * fit_bonus * 30.0;

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack_after_next = (pr - nxt) / cap;
            score -= 15.0 * (1.0 - slack_after_next) * (1.0 - slack_after_next);
        } else {
            // next item won't fit here; penalize leaving large unusable gap
            score += 8.0 * norm_pr * (nxt / cap);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mean residual interaction: placing into a bin below mean residual
    // (larger than average leftover) is less attractive; smooth coupling
    let mean_norm = mean_residual / cap;
    score += 10.0 * (norm_pr - mean_norm) * (norm_pr - mean_norm) * (1.0 - progress);

    // New-bin candidate (empty bin): penalize mildly unless current fit is bad
    if bin_residual == bin_capacity {
        let bad_fit_penalty = norm_pr * norm_pr * 60.0; // empty bin has norm_pr=1
        score = cap + bad_fit_penalty - fit_bonus * 0.0;
        // encourage opening new bin only when no open bin gives tight fit:
        // if the best open fit would leave big residual, this relatively loses
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by residue mod 10
    let dead_class = post_residual % 10;
    // Dead space in (0..10) exclusive of 0 is worst; exact zero is perfect
    if post_residual == 0 {
        score -= 25.0; // perfect closure reward
    } else if dead_class == 0 {
        score -= 6.0; // post residual is a round class (10,20,...) -> reusable
    } else {
        // penalty grows for awkward residues near the middle of the decade
        let awkward = (dead_class.min(10 - dead_class)) as f64;
        score += (5.0 - awkward) * 1.2; // residue 5 worst (+6), residues 1/9 mild (+1.2)
    }

    // Tightness reward: fraction of bin consumed by this item
    let fill = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fill * fill;

    // Lookahead: if next item fits the post residual exactly, big reward
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            // next item leaves another residual; check its harmonic class
            let nd = (post_residual - next_item_size) % 10;
            if nd == 0 { score -= 8.0; } else { score += 1.5; }
        } else {
            // next item cannot use this bin's remainder; mild penalty scaled by overflow
            let over = (next_item_size - post_residual) as f64;
            score += (over / 40.0).min(3.0);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin should be penalized,
    // unless no open bin gives a decent fit
    if bin_residual == bin_capacity {
        let base_penalty = 30.0
            + 2.0 * open_bins_count as f64
            + 10.0 * (step_index as f64 / (total_items.max(1) as f64));
        // forgive the new bin if this bin is the only option or fit is very poor
        let poor_fit = if fitting_bins_count == 0 { 35.0 }
                       else if post_residual < 15 { 20.0 }
                       else { 0.0 };
        score += base_penalty - poor_fit;
    }

    // Global pressure: when mean residual is low, conserve space aggressively
    score += (mean_residual - post_residual as f64) * 0.15;

    // Late in stream: prefer closing bins out
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 && post_residual < 10 && post_residual > 0 {
        score += 4.0; // avoid stranding tiny fragments late
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are "dead".
    // Penalize post_residual heavily if it falls into an unusable band (1..MIN_USEFUL).
    let min_useful = 10u32.min(bin_capacity / 10);
    if post_residual > 0 && post_residual < min_useful {
        score += 25.0 * (min_useful - post_residual) as f64;
    }

    // Reward perfect or near-perfect fits (post_residual == 0 is ideal).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item (lookahead coupling).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + min_useful {
        score += 10.0; // gap will likely become dead after next item
    }

    // Best-fit style: tighter fit relative to bin residual is better.
    if bin_residual > 0 {
        score += 0.5 * (bin_residual - item_size) as f64 / bin_residual as f64 * 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is excellent.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * (0.5 + progress);

    // Mean residual coupling: if this bin's residual is far below mean, it's a small bin; prefer filling it.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it moderately attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset by item size (bigger items waste less in a fresh bin).
        score = 60.0 - 0.2 * item_size as f64;
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 20.0 * (fitting_bins_count as f64 - 1.0);
        }
        // Early in stream, opening bins is cheaper; late, prefer consolidation.
        score += 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size (perfect chain placement).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        // Perfect match: next item exactly fills the bin -> strong reward.
        if diff < 0.5 {
            score -= 40.0;
        } else if pr >= nxt {
            // Next item fits: reward proportional to tightness of the chain.
            score -= 15.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item does not fit: penalize leftover dead space that
            // is too small to be useful for typical items.
            if pr < 10.0 {
                score += 10.0;
            }
            score += 5.0 * (1.0 - pr / bin_capacity as f64);
        }
    } else {
        // Last item: prefer the fullest possible packing.
        score -= 20.0;
    }

    // Relative to mean residual: prefer bins that are already fuller
    // than average (best-fit style), scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let rel = (bin_residual as f64) - mean_residual;
    score -= rel * (0.3 + 0.4 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): penalize moderately so it is only
    // chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 35.0 + 10.0 * progress;
        // But if the item is huge and nothing fits well, new bin is fine:
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Slight penalty on proliferation of open bins late in the stream.
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: square the waste so near-perfect fills win.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that fits, heavily favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits: good, but only mildly reward (keep tightness dominant).
            score -= 5.0 + 0.1 * (post_residual - next_item_size) as f64;
        } else {
            // Next item won't fit here: penalize leaving an awkward gap that is
            // too small to be useful relative to the upcoming demand.
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item in the stream: pure tight-fit, no future to plan for.
        score -= 10.0;
    }

    // Global pressure: when many bins are open relative to stream progress,
    // discourage fragmentation by penalizing large residuals mildly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += 0.05 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Compare against mean residual: bins with residual far from the mean are
    // either outliers; slightly prefer bins whose residual is close to item size.
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.02 * gap;
    let mean_gap = (bin_residual as f64 - mean_residual).abs();
    score -= 0.01 * mean_gap;

    // New-bin candidate handling: an empty bin has no waste yet, but opening a
    // new bin is costly unless the item fits poorly everywhere else. Make the
    // empty-bin score a moderate constant plus a term that shrinks when the
    // item is large (large items leave little usable residual anyway).
    if bin_residual == bin_capacity {
        score = 30.0 + 0.5 * (bin_capacity - item_size) as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open a bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (small post_residual), with a non-linear penalty
    // for both very large leftover (wasted space) and awkward mid-range leftovers.
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early in the stream, tolerate larger residuals (bins can still be filled);
    // late in the stream, aggressively prefer near-perfect fits.
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep in [0,1]
    score += (1.0 - poly) * 8.0 - poly * 14.0;

    // Cubic coupling term: penalize residuals near half-capacity more strongly
    // as the stream progresses (hard-to-fill dead space).
    let mid = (x - 0.5).abs();
    score += mid * mid * (20.0 + 30.0 * progress);

    // Reward using an existing bin when few bins can fit the item
    // (last-chance bin should be strongly favored over opening a new one).
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        score -= 3.0 * (fitting_bins_count.min(6) as f64);
    }

    // Lookahead coupling: if the next item fits the post residual, reward this placement;
    // if the next item would exactly fill the bin, reward even more.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let tightness = ni / pr.max(1.0);
            score -= 6.0 + 10.0 * tightness;
        } else {
            score += 4.0;
        }
    }

    // Global pressure: many open bins with large mean residual -> discourage
    // spreading items; consolidate into bins that keep residuals small.
    let pressure = (mean_residual / cap) * (open_bins_count as f64).ln();
    score += pressure * (2.0 + 6.0 * progress);

    // Slight penalty for opening a brand-new bin, scaled by how well the item
    // would fill it (a fresh bin with a big item is acceptable).
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" residue classes are more likely to be filled later -> reward.
    let r = post_residual;
    let class = r / 10; // integer division thresholds (0..10)
    match class {
        0 => score -= 25.0,              // near-perfect fit
        1 => score -= 15.0,              // small leftover, likely reusable
        2 => score -= 8.0,
        3 => score -= 4.0,
        4 => score += 2.0,               // awkward dead zone
        5 => score += 5.0,               // half-empty: poor
        6 => score += 6.0,
        7 => score += 4.0,
        8 => score -= 1.0,               // big residual, flexible
        _ => score -= 3.0,               // nearly empty bin, very flexible
    }

    // Modulo coupling: leftover that is congruent to common item sizes
    // (mod 10) is more reusable.
    if r > 0 && (r % 10 == 0) {
        score -= 6.0;
    }
    if next_item_size > 0 && next_item_size <= r {
        // lookahead: this bin can also take the next item -> strong reward
        let pair_waste = (r - next_item_size) % 10;
        score -= 10.0 - pair_waste as f64;
    } else if next_item_size > r {
        // next item cannot follow here; penalize proportionally
        score += (next_item_size - r) as f64 * 0.15;
    }

    // Last-chance bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer tight bins when many bins are open (consolidation pressure).
    score += mean_residual * 0.05 * (open_bins_count as f64).sqrt();

    // New-bin candidate: only attractive early or when no good fit exists.
    if bin_residual == bin_capacity {
        let new_bin_bonus = 40.0 * (1.0 - progress);
        score -= new_bin_bonus;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if post_residual == 0 {
            score -= 10.0; // impossible for empty bin, safe guard
        }
    }

    // Slight late-stream tightening: waste less as stream ends.
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (10)
    // are permanently unusable -> penalize quadratically.
    if post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual > 50 {
        // Large leftover space is fine (still reusable); mild bonus.
        score -= 5.0;
    }

    // Tight fit reward: fraction of residual consumed by the item.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: default neutral-ish score; discourage unless open bins
    // would leave bad dead space. Penalize slightly with open bin pressure
    // (fewer bins is better, so a new bin is penalized when bins are few).
    if bin_residual == bin_capacity {
        score = 60.0 + 2.0 * open_bins_count as f64;
        // If the lookahead item fits perfectly in a fresh bin, encourage opening.
        if next_item_size > 0 && next_item_size == bin_capacity {
            score -= 40.0;
        }
        // Late in the stream, opening new bins is more costly.
        score += 20.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Prefer bins whose residual is already below the mean (consolidate waste).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Lookahead synergy: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slightly penalize leaving it stranded.
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff);
        if post_residual == next_item_size {
            score -= 500.0;
        }
        // penalize dead space too small for any plausible future item
        if post_residual < next_item_size && post_residual < 10 {
            score += 30.0;
        }
    }

    // Tight-fit preference relative to mean residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;
    score += 5.0 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if all open fits are bad
    if bin_residual == bin_capacity {
        score += 45.0 + post_residual as f64 * 0.5;
        if next_item_size > 0 && post_residual as i64 - next_item_size as i64 == 0 {
            score -= 200.0; // fresh bin perfectly sized for next item
        }
    }

    // Slight preference to consolidate bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: reward small post_residual relative to capacity
    let tight = post_residual as f64 / bin_capacity as f64;
    score += tight * 60.0;

    // Lookahead: penalize if next item fits better in another bin; reward if this bin can host next item too
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain placement possible: reward proportional to chained fill
            score -= 15.0 + (next_item_size as f64) * 0.4;
        } else if post_residual > 0 && post_residual < 10 {
            // tiny dead space that next item can't use: strong penalty
            score += 40.0;
        }
    } else {
        // last item: any residual is pure waste
        score += tight * 200.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Many open bins: discourage spreading; favor bins below mean residual (denser bins)
    if open_bins_count > 1 {
        let denser = mean_residual - bin_residual as f64;
        score += denser * 0.8;
        // pressure to consolidate when many bins open
        score -= (open_bins_count as f64).ln() * 6.0;
    } else {
        // single open bin: keep using it
        score -= 30.0;
    }

    // Time horizon: early stream -> keep residual flexible; late stream -> fill aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.35 * progress;

    // New-bin candidate handling: only attractive when item is large relative to residual
    if bin_residual == bin_capacity {
        let big = item_size as f64 / bin_capacity as f64;
        // new bin is good for big items or when nothing fits well
        score = 100.0 - big * 80.0
            + if next_item_size > 0 && next_item_size <= bin_capacity - item_size { 10.0 } else { 0.0 }
            + (fitting_bins_count as f64) * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear tight-fit reward: cubic decay of residual advantage.
    let tight = (pr / cap).powi(3);
    score -= 18.0 * tight;

    // Smooth interaction: residual waste matters more as stream progresses.
    let waste = (pr / cap) * (1.0 + 6.0 * progress * progress);
    score += 10.0 * waste * (pr / cap);

    // Lookahead coupling: penalize residuals that fit next item poorly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 8.0 * (1.0 - slack).max(0.0) * (1.0 - progress);
        } else {
            score += 4.0 * ((nx - pr) / cap);
        }
    }

    // Last-chance bonus: only fitting bin should be strongly favored.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // New-bin candidate: penalize mildly, less so late in stream or when
    // open bins are crowded (high mean residual).
    if bin_residual == bin_capacity {
        let crowd = (mean_residual / cap).clamp(0.0, 1.0);
        score += 12.0 - 8.0 * progress - 6.0 * crowd * crowd;
        if next_item_size > 0 && (next_item_size as f64) > pr + 0.0 {
            score -= 2.0;
        }
    }

    // Mild preference for bins below mean residual (balance residuals).
    score += 1.5 * ((bin_residual as f64 - mean_residual) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Class residuals into coarse buckets (multiples of 10) — small leftovers are dead space.
    let pr = post_residual;
    let class = pr / 10; // integer division threshold
    match class {
        0 => score -= 6.0,          // near-perfect fit
        1 => score -= 3.0,
        2 => score -= 1.0,
        3 | 4 => score += 1.5,      // awkward mid-range dead space
        5 | 6 => score += 3.0,
        _ => score += 0.5,
    }

    // Exact harmonic match: post_residual equals a plausible future item size
    if next_item_size > 0 && pr >= next_item_size {
        let gap = (pr as i64 - next_item_size as i64).abs();
        if gap == 0 {
            score -= 12.0; // perfect chain: next item fills this bin exactly
        } else if gap <= 5 {
            score -= 7.0;
        } else if gap <= 15 {
            score -= 2.0;
        } else {
            score += 1.0;
        }
    } else if next_item_size > 0 && pr < next_item_size {
        // next item cannot use this leftover: leftover likely wasted
        score += (pr as f64) * 0.05;
    }

    // Last-chance bonus: this is the only bin that fits the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening new bins when good fits exist
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost of a fresh bin
        score = cap * 0.5 + (pr as f64);
        // open a new bin if current open bins are fragmented (high mean residual spread)
        if open_bins_count > 0 && (mean_residual / cap) > 0.35 {
            score -= 8.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size > 50 {
            score -= 4.0; // big follower: prefer fresh bin
        }
    } else {
        // reward tightness relative to mean residual
        let tightness = (bin_residual as f64 - mean_residual) / cap;
        score += tightness * 4.0; // prefer fuller-than-average bins
    }

    // Early stream: be conservative about dead space; late stream: close bins aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (cap - bin_residual as f64) * 0.05;

    // Waste fraction penalty (non-linear)
    score += (pr as f64 / cap) * (pr as f64 / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: post_residual in (0, 10) is unusable dead space.
    if post > 0.0 && post < 10.0 {
        score += 40.0; // heavy penalty for creating a sliver gap
    } else if post == 0.0 {
        score -= 25.0; // perfect fit is excellent
    }

    // Reward filling large fractions of the bin.
    let fill_ratio = item_size as f64 / cap;
    score -= 15.0 * fill_ratio;

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly so we only open when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 12.0;
        // If next item is small, a fresh bin is more attractive.
        if next_item_size > 0 && (next_item_size as f64) < mean_residual * 0.5 {
            score -= 6.0;
        }
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing ones.
    score += 0.8 * open_bins_count as f64;

    // Lookahead: if the next item fits the post-residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post > 0.0 {
        score += 4.0; // gap won't serve the next item
    }

    // Progress scaling: late in stream, be more conservative about new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (bin_residual == bin_capacity) as u8 as f64;

    // Prefer bins below mean residual (fill emptier bins first).
    score += 0.3 * (mean_residual - (bin_residual as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base tightness: strongly reward small post_residual (good fill now).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // --- 2-step lookahead core ---
    if next_item_size > 0 {
        if post_residual == 0 {
            // Perfect closure of this bin: excellent, nothing wasted.
            score -= 25.0;
        } else if next_item_size == post_residual {
            // Next item EXACTLY fills the remaining space: ideal chain.
            score -= 40.0;
        } else if next_item_size < post_residual {
            // Next item fits here later; reward proportional closeness of fit.
            let gap = (post_residual - next_item_size) as f64;
            let fit_ratio = 1.0 - gap / post_residual as f64;
            score -= 18.0 * fit_ratio * fit_ratio;
        } else {
            // Next item cannot use the residual: penalize dead space,
            // worse when the leftover is small and unusable.
            let dead = post_residual as f64;
            let unusable = if dead < next_item_size as f64 { 1.0 } else { 0.0 };
            let small_dead = 1.0 - dead / bin_capacity as f64;
            score += 12.0 * unusable * small_dead * small_dead;
        }
    } else {
        // Last item: only current fill matters.
        score -= 20.0 * tightness;
    }

    // Relative-to-mean coupling: prefer bins whose post_residual stays near
    // the fleet mean (balanced residuals keep future options open), but
    // allow slightly below-mean (denser bins) which is mildly good.
    let diff = post_residual as f64 - mean_residual;
    score += 0.08 * diff.abs();

    // Last-chance bin: if this is the ONLY bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when current item is large and would leave a tiny residual elsewhere,
    // or when no open bin fits well. Penalize the empty-bin call generally.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if item nearly fills a fresh bin, a new bin is reasonable.
        if item_size * 10 >= bin_capacity * 9 {
            score -= 30.0;
        }
        // Lookahead synergy: fresh bin leaves post_residual = C - item;
        // if next item matches that, opening new bin is great.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 45.0;
        }
    }

    // Slight preference to fill older/more crowded fleets first.
    score += 0.5 * open_bins_count as f64;

    // Early-stream: be a bit more willing to open bins (build diverse
    // residuals); late-stream: squeeze everything.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strong reward for leaving zero residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space that no typical item can use.
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 30.0; // unusable sliver
        } else if dead < 20.0 {
            score -= 5.0; // small but potentially usable
        }
        // Reward residual that exactly matches the lookahead item.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 60.0;
        }
        // If lookahead cannot fit in this residual, dead space is more likely.
        if next_item_size > 0 && next_item_size > post_residual {
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Tightness of fit: prefer bins where the item fills a large fraction.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 40.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    } else if fitting_bins_count > 1 {
        // With alternatives, mildly prefer bins that are already fragmented.
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized, but less when few bins fit the item
        // or the stream is early and many items remain.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut open_penalty = 150.0;
        if fitting_bins_count == 0 {
            open_penalty = 0.0; // no alternative: new bin is fine
        } else if fitting_bins_count == 1 {
            open_penalty = 200.0; // keep the last-chance bin busy instead
        }
        if progress < 0.5 && total_items > 20 {
            open_penalty += 20.0; // early stream: conserve open bins less aggressively
        }
        score += open_penalty;
        // A new bin is attractive if the item is huge (fits nothing well anyway).
        if item_size >= 70 {
            score -= 80.0;
        }
    }

    // Global state coupling: when mean residual is high, prefer placing into
    // bins with below-average residual (consolidate fragmentation).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Late stream: pack tighter, avoid opening bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 50.0 * progress * tightness;
    if progress > 0.8 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild preference for fewer open bins overall.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap; late, waste is heavily penalized.
    let waste_weight = 1.0 + 2.5 * progress * progress;
    score += 0.6 * waste_weight * (pr / cap).powi(3) * cap;

    // Reward tight fits (small post_residual) with smooth quadratic bonus.
    score -= 8.0 * (1.0 - pr / cap).powi(2);

    // Lookahead coupling: if next item fits into post_residual, reward this bin.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let slack = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 6.0 * (1.0 - slack).powi(2);
    } else if next_item_size > 0 {
        // post_residual too small for next item: penalize dead space smoothly.
        score += 3.0 * (pr / cap).powi(2) * cap * 0.25;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer keeping it closed unless open bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score += 4.0 + 2.0 * crowd;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size as f64 > item {
            score -= 5.0 * (next_item_size as f64 - item) / cap;
        }
    }

    // Mild preference for fuller bins among open ones.
    score -= 2.0 * (1.0 - bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: prefer residuals in "usable" classes.
    // Class by post_residual / 10: small dead space is fine, mid-range is worst.
    let pr = post_residual as f64;
    let class = (post_residual / 10) as f64;
    // Mid-class residuals (20..60) are hard to fill later -> penalize via quadratic hump.
    let hump = -((class - 4.0) * (class - 4.0)) + 16.0; // peak at class 4 (residual 40-49)
    score += 0.35 * hump;

    // Exact or near-exact fit reward (harmonic: post_residual divides nicely).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual % 10 == 0 {
        score -= 12.0; // round residual keeps future integer pairing easy
    }

    // Lookahead: if next item fits the post residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0 + 0.25 * (next_item_size as f64);
        // Harmonic pairing: next item exactly fills remainder
        if next_item_size == post_residual {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit: penalize proportionally to wasted lookahead potential
        let waste = (next_item_size as f64 - pr).min(50.0);
        score += 0.15 * waste;
    }

    // Last-chance bin: this is the only bin that fits -> strong reward to avoid opening new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fit: relative fill fraction
        let fill = item_size as f64 / bin_capacity as f64;
        score -= 25.0 * fill * fill;
    }

    // New empty bin candidate: penalize unless residuals across bins are all poor.
    if bin_residual == bin_capacity {
        let base = 45.0;
        // Early in stream, opening bins is cheap; later, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = base + 20.0 * (1.0 - progress);
        // If mean residual is large, opening a new bin is wasteful.
        score += 0.4 * mean_residual;
        // If nothing else fits this item, new bin becomes attractive.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Tie-break with slight noise-free harmonic jitter on bin index proxy (open_bins_count).
    score += 0.01 * ((open_bins_count % 7) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 1..10) can
    // ever use are pure waste. Penalize small gaps quadratically.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 3.0;
    }

    // Reward tight fits: the smaller the waste relative to capacity, the better.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Perfect / near-perfect fits get a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item can use the post_residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item is close to residual but not exact, mild penalty for teasing.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 10 {
        score += 6.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (which costs a full fresh bin).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, consolidate; with few, spreading is cheap.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += pressure * 10.0;

    // Prefer bins whose residual is already below the mean (they're the "small" ones).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // New-bin candidate handling: an empty bin has zero dead space, so its raw
    // post_residual is high. Make it attractive only when existing bins would
    // leave bad gaps or when residuals across the board are tiny.
    if bin_residual == bin_capacity {
        let bad_gap_risk = if post_residual < 10 { 12.0 } else { 0.0 };
        score -= 20.0;               // base attractiveness of a clean bin
        score -= mean_residual * 0.05; // more attractive when open bins are nearly full
        score += bad_gap_risk * 0.0;   // placeholder coupling (empty bin never has small gap)
        // Late in the stream, opening new bins is less desirable (leftover waste).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Mild preference for bins that would end up with residual >= 10 (usable gap).
    if post_residual >= 10 && post_residual <= 50 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward if the next item exactly fills the post residual (perfect 2-step match).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Reward near-perfect matches too.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap <= 10.0 {
            score -= (10.0 - gap) * 1.5;
        }
        // Penalize residuals the next item cannot partially use (dead space risk).
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Reward tight fits of the current item (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 15.0;

    // Penalize leaving residuals that are hard to fill (small but nonzero).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Compare against mean residual: bins with residual near/below mean are good targets.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // Prefer filling bins that are already fairly full when many bins are open.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * open_bins_count as f64 * 0.5;

    // New-bin candidate: only attractive when item is large and no good fit exists.
    if bin_residual == bin_capacity {
        score += 10.0; // default penalty for opening a new bin
        if item_size >= 50 && (fitting_bins_count == 0 || fitting_bins_count == 1) {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && item_size >= 40 {
            score -= 10.0; // large pair may justify a fresh bin
        }
    }

    // Mild stream-progression bias: later in stream, prefer consolidating.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 3.0 * fill_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (small post_residual).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * 30.0;

    // Reward near-perfect fits heavily.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Penalize dead space that can't hold the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + 0.2 * next_item_size as f64;
        } else {
            // Penalize leaving a residual that wastes the next item's fit options.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.1 * gap.min(20.0);
        }
    }

    // Time horizon: early in the stream, be conservative (prefer filling existing bins);
    // late in the stream, slightly favor new bins since future payoff is limited.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (bin_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> discourage spreading waste;
    // prefer bins whose residual deviates favorably from the mean.
    if open_bins_count > 0 {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev; // prefer bins with residual below mean (tighter bins)
        if open_bins_count > 10 && bin_residual as f64 > mean_residual + 20.0 {
            score += 6.0; // avoid very loose bins when many bins are open
        }
    }

    // New-bin candidate handling: empty bin gets a base penalty so it's only
    // chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 40.0;
        // If the item is large relative to capacity, opening a new bin is more acceptable.
        score -= 0.15 * item_size as f64;
        // If few fitting bins exist, opening a new bin is more justified.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // Late in stream with many open bins, avoid opening yet another.
        if progress > 0.7 && open_bins_count > 8 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; later, penalize them more strongly
    score += pr * (0.8 * progress * progress + 0.4 * progress * norm_pr);

    // Penalize residual that cannot fit the next item (dead space), smoothly scaled
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let waste = (nxt - pr).max(0.0) / cap;
        score += 25.0 * waste * (1.0 + progress);
        // Reward if post residual still fits next item
        if pr >= nxt {
            score -= 6.0 * (1.0 - progress);
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild preference for bins deviating from mean residual (consolidation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev - 2.0 * dev * progress;

    // New-bin candidate: penalize opening a new bin unless item is large
    // relative to residual and stream is early
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score += 12.0 - 8.0 * fill - 5.0 * progress;
    }

    // Slight penalty per open bin to encourage consolidation
    score += (open_bins_count as f64).ln() * 0.5 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 / integer division classes
    let post_class = post_residual / 10;          // 0..=9 coarse class
    let post_mod = post_residual % 10;            // fine residue

    // Reward small post residuals, especially those in "usable" harmonic classes.
    // Classes 0 (full) and >=3 (can host typical items) are valuable.
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else {
        // Dead-space penalty for tiny unusable leftovers (1..10)
        if post_class == 0 {
            score += 25.0 + (10 - post_mod) as f64;
        }
        // Usable classes: reward proportionally to class depth
        if post_class >= 3 {
            score -= 8.0 + 2.0 * post_class as f64;
        }
        // Class 1-2: marginal space, mild reward only if next item can use it
        if post_class >= 1 && post_class <= 2 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        }
    }

    // Next-item lookahead coupling: if the next item fits exactly or nearly, boost
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = post_residual - next_item_size;
        score -= 10.0 + (next_fit == 0) as i32 as f64 * 20.0;
    } else if next_item_size > 0 {
        // next item won't fit here: slight penalty if we leave large residual anyway
        if post_residual > 40 {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): penalize opening unless residuals are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = if open_bins_count > 0 { mean_residual } else { 0.0 };
        // open new bin if existing residuals are small relative to item
        score += 30.0 - fragmentation * 0.4 - progress * 5.0;
        if next_item_size > 0 && next_item_size > 50 {
            score -= 10.0; // big next item: fresh bin useful
        }
    }

    // Tight fit bonus: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if post_residual <= 15 {
        score -= 15.0 * fill_ratio;
    }

    // Prefer packing into bins whose residual is close to item (best-fit sharpening)
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 20.0 * tightness * tightness;

    // Slight preference to spread across bins when many are open (avoid hoarding one bin)
    if open_bins_count > 3 && post_residual > 0 {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in small unusable gaps is heavily penalized.
    // Gaps below the minimum item size (1) can't exist, but tiny gaps (1..=12) are hard to fill.
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 6.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else {
        // Larger residual gaps: mild penalty scaled by gap size.
        score += post_residual as f64 * 0.05;
    }

    // Reward bins whose residual is well-matched to the item (tight fit without overflow).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.08;

    // Lookahead: if the next item would fit in the post-residual, reward this placement;
    // otherwise penalize leaving a gap that blocks the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> prefer packing into existing bins,
    // disfavor opening new ones (new bin has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 12.0 + 2.5 * open_bins_count as f64;
    } else {
        score -= 1.0 * open_bins_count as f64;
    }

    // Mean-residual coupling: placing into a bin with residual below the mean
    // helps reduce fragmentation spread; reward that.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Stream progression: early on, be more tolerant of opening bins;
    // later, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> huge reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-match: next item can still fit tightly after this placement
    else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 300.0;
    }
    // Next item would leave a fresh large residual: mild reward
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0;
    }
    // Next item cannot fit here: penalize creating dead space
    else if next_item_size > 0 {
        score += 40.0 + 0.3 * (post_residual as f64);
    }

    // Reward tight fits relative to bin capacity
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Penalize residuals far below mean residual (this bin is unusually small)
    score += 0.5 * (mean_residual - post_residual as f64).max(0.0);

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when few/no good fits exist
    if bin_residual == bin_capacity {
        // Penalize opening a new bin when many bins fit the item
        if fitting_bins_count > 0 {
            score += 150.0 * fitting_bins_count as f64;
        }
        // Early in the stream, new bins are cheap
        score -= 30.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 80.0;
        }
    }

    // Slight penalty for accumulating too many open bins
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio: later in the stream, tighten up / avoid waste more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Base: prefer tight fits (small post_residual), with a non-linear tightening.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Reward nearly-exact fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0 - post_residual as f64 * 3.0;
    }

    // Dead-space penalty: residuals too small for typical future items are worthless.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 50.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.5;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize more if leftover is unusable.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.4 * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Crowding: many open bins -> prefer consolidating into existing bins.
    let crowding = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / bin_capacity as f64);
    score += crowding * 1.5;

    // New-bin candidate handling: empty bin gets a baseline cost that grows
    // with how well existing bins could absorb the item.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 25.0 + waste * 0.5 * (0.5 + progress);
        // Opening a new bin is more attractive when few bins fit the item
        // or existing bins are crowded.
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else if fitting_bins_count <= 2 {
            score -= 10.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Filling an existing bin: reward proportional to how much of the
        // residual the item consumes, scaled by global mean residual pressure.
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= fill_ratio * 15.0;
        score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;
    }

    // Mild time-horizon modulation: early on, be lenient about leftovers;
    // late, penalize them harder.
    score += post_residual as f64 * progress * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = norm_pr * (1.0 + 2.0 * progress + 3.0 * p2 + 1.5 * p3);
    score += 30.0 * coupling;

    // Reward tight fits: smooth quadratic decay of bonus as post_residual grows
    let tight_bonus = (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 25.0 * tight_bonus * (0.5 + progress);

    // Penalize dead space relative to mean residual (smooth interaction)
    let dead = (pr - mean_residual).max(0.0) / cap;
    score += 15.0 * dead * dead * (1.0 + 2.0 * progress);

    // Last-chance bin: strongly favor using it (smooth exponential flavor via polynomial)
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - norm_pr) * (1.0 + progress);
    }

    // Lookahead: reward leaving space exactly usable by next item (smooth polynomial match)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let diff = (pr - ns) / cap;
        let match_term = 1.0 - (diff * diff) / ((1.0 + norm_pr) * (1.0 + norm_pr));
        score -= 20.0 * match_term.max(0.0) * (0.4 + 0.6 * progress);
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 + progress);
    }

    // Mild penalty for too many open bins, scaled by progress
    score += 1.5 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions
    let post = post_residual as i64;
    let nxt = next_item_size as i64;

    // Perfect fit: zero residual is ideal
    if post == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead-space classes: residual too small for any plausible item (min size 1, but
    // harmonic banding: residuals in 1..=5 are near-waste unless next item fits)
    if nxt > 0 && post >= nxt {
        // Next item fits here: strong reward proportional to how snugly it fits
        score -= 40.0 + (post - nxt) as f64 * 0.5;
    } else if nxt > 0 {
        // Next item does NOT fit: penalize by how much we "waste" the slot
        score += 15.0 + (nxt - post) as f64 * 0.3;
    }

    // Integer-division thresholds on post_residual (capacity quarters)
    let quarter = (bin_capacity / 4) as i64;
    let half = (bin_capacity / 2) as i64;
    if post < quarter {
        // Tiny residual: nearly unusable — heavy penalty unless last-chance bin
        score += 25.0;
    } else if post < half {
        // Small residual band: mildly penalize
        score += 8.0;
    } else if post <= half + quarter {
        // Mid band: slight reward for keeping usable chunks
        score -= 5.0;
    }

    // Modulo-10 harmonic class of post_residual: multiples of 10 align with
    // typical item-size grids, making residual reusable
    let m = post % 10;
    if m == 0 {
        score -= 10.0;
    } else if m >= 8 {
        score -= 4.0; // close to a grid point
    } else if m <= 2 {
        score += 4.0; // just past a grid point: awkward
    }

    // Last-chance bonus: only bin that fits — avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        // If mean residual is large, prefer existing bins -> new bin costly
        score += 60.0 + 50.0 * crowding;
        // Late in stream, opening new bins is less recoverable
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * progress;
        if nxt > 0 && nxt >= bin_capacity {
            score -= 100.0; // oversized next item needs fresh bin anyway
        }
    }

    // Prefer filling bins when many are open
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Small tie-breaker favoring tighter fits (smaller post_residual already dominates)
    score += item_size as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 40.0 } else if post_residual < 20 { 15.0 } else { 0.0 };
        score += dead;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Prefer bins whose residual was already tight relative to mean.
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; opening a
    // new empty bin gets a penalty that grows with open_bins_count.
    if bin_residual == bin_capacity {
        score += 25.0 + 4.0 * open_bins_count as f64;
    } else {
        score -= 4.0 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize leaving a gap that only the next item barely fits, wasting it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 20.0;
    }

    // Early in the stream, allow slightly more freedom to open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), with non-linear penalty.
    score += (post_residual as f64).powi(2) / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining
        } else if next_item_size <= post_residual {
            score -= 25.0 - (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here: penalize large leftover dead space
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // last item: only tightness matters
        score -= 10.0;
    }

    // Relative to mean residual: prefer bins with residual near/below mean
    // (avoid wasting large residual bins on small items).
    let resid_f = bin_residual as f64;
    if resid_f > mean_residual + 1.0 {
        score += (resid_f - mean_residual) * 0.25;
    } else {
        score -= (mean_residual - resid_f) * 0.10;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it moderately attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // neutral baseline anchored to mean residual of open bins
        score = (bin_capacity - item_size) as f64 * 0.9 + mean_residual * 0.1;
        if next_item_size > 0 && next_item_size <= (bin_capacity - item_size) {
            score -= 8.0; // fresh bin can chain next item too
        }
        if fitting_bins_count == 1 {
            score += 55.0; // don't abandon the sole fitting open bin
        }
    }

    // Slight stream-phase coupling: early on, be more willing to open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual), non-linear.
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 40.0 * tightness * tightness;

    // Penalize post_residual that is too small to be useful later (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use this residual: mild penalty proportional to leftover.
            score += 5.0 * (1.0 - (post_residual as f64 / cap));
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Discourage spreading across many open bins when mean residual is high.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = (open_bins_count as f64) * mean_residual / (cap * (open_bins_count as f64 + 1.0));
    score += 10.0 * crowding * (1.0 - progress);

    // New-bin candidate: only attractive when open bins are badly fragmented
    // (high mean residual but none fitting well) or late in the stream.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        score = 55.0 + 60.0 * (1.0 - fragmentation) + 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 80.0; // nothing fits anywhere: opening a bin is required
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: tight fit reward, non-linear (quartic-ish) in normalized residual
    let mut score = 2.0 * pr + 60.0 * norm_pr * norm_pr * norm_pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, large residuals are tolerated more; late, they are penalized heavily
    let coupling = 40.0 * norm_pr * norm_pr * (0.5 + progress) * (1.0 - progress) * 2.0;
    score += coupling;

    // Reward filling a bin nearly exactly (dead-space aversion grows with progress)
    let exact = (bin_residual - item_size) as f64;
    if exact == 0.0 {
        score -= 25.0 + 30.0 * progress;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize proportionally to how many open bins exist
    // and how much mean residual space is being wasted elsewhere
    if bin_residual == bin_capacity {
        let waste = mean_residual / cap;
        score += 30.0 + 10.0 * open_bins_count as f64 + 50.0 * waste * (1.0 - progress);
    } else {
        // Slight bonus for using existing bins generally
        score -= 3.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        let fit_next = (1.0 - diff / cap).max(0.0);
        score -= 12.0 * fit_next * fit_next * fit_next;
    }

    // Mild preference for bins with residuals close to the item (best-fit flavor)
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += 10.0 * tightness * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: quantize leftover space into coarse classes.
    // Small leftovers are good (tight fit); large leftovers are wasteful.
    let class = post_residual / 10; // 0..=10 harmonic class
    score += (class as f64).powi(2) * 1.5;

    // Reward near-perfect fits strongly.
    if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 10 {
        score -= 5.0;
    }

    // Dead-space penalty: residual too small for the smallest possible item (1..100 interface).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: chain placement possible. Reward proportional to how well next item uses leftover.
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 6.0 + 8.0 * next_fit;
        } else if next_item_size <= bin_capacity {
            // Next item won't chain here; penalize more if leftover is large and stranded.
            let waste = post_residual as f64;
            score += 0.03 * waste;
        }
    }

    // Last-chance bonus: this is the only open bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Prefer opening a new bin only when existing fits are poor.
        // Penalize new bins mildly, more so when many bins are open and mean residual is large.
        score += 15.0;
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            score += 10.0;
        }
        // Early in stream, opening bins is cheap and gives flexibility.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
    }

    // Modulo / integer-division harmonic structure on post_residual:
    // favor residuals that are "usable" sizes (multiples of common item granularities).
    let mod_class = post_residual % 10;
    if mod_class == 0 {
        score -= 2.0;
    } else if mod_class >= 7 {
        score += 1.0;
    }

    // Tie-break: prefer bins with lower residual relative to mean (larger bins first for big items).
    if item_size > 50 {
        score += 0.5 * (bin_residual as f64 - mean_residual).max(0.0).min(20.0) / 20.0;
    }

    // Slight preference for filling nearly-full bins to consolidate.
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 4.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is smaller than the smallest plausible item (1..100 stream,
    // assume min useful gap ~ 10) but nonzero.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 12.0; // steep penalty for creating tiny useless slivers
    }
    // Moderate penalty for medium gaps that few future items can use
    if pr >= 10.0 && pr < 25.0 {
        score += (25.0 - pr) * 2.0;
    }

    // Reward near-perfect fits strongly
    if pr == 0 {
        score -= 80.0;
    } else if pr <= 5 {
        score -= 40.0 - pr as f64 * 4.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / 50.0).max(0.0);
        } else {
            // next item cannot use this bin's leftover; penalize proportionally
            score += ((next_item_size - post_residual) as f64) * 0.5;
        }
    }

    // Open-bin pressure: prefer spreading load when many bins are open,
    // but conserve bins when few are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    score += bin_pressure * (2.0 + 3.0 * progress);

    // Mean residual coupling: placing into a bin far below mean residual wastes capacity elsewhere
    score += ((mean_residual - pr) * 0.3).max(0.0);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate handling: an empty bin has full residual. Make it attractive
    // only when no open bin offers a decent fit (post_residual small relative to item).
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin, softened by stream progress and pressure
        score = bin_capacity as f64 * 0.9 + 30.0 * (1.0 - progress) + bin_pressure * 4.0;
        if fitting_bins_count == 1 {
            score += 70.0; // don't open a new bin when a last-chance bin exists
        }
        if next_item_size > 0 && next_item_size >= bin_residual {
            score += 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Post-residual can still host the next item: reward proportionally.
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit in the leftover: penalize dead space.
        let unusable = (next_item_size - post_residual) as f64;
        score += 15.0 * (unusable / bin_capacity as f64);
    }

    // Tight fit reward: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 20.0 * (1.0 - tightness) * (item_size as f64 / bin_capacity as f64);

    // Penalize bins whose residual deviates above the mean (fragmented bins).
    if mean_residual > 0.0 {
        score += 0.5 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Slight preference for keeping number of open bins low early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    // New-bin candidate: neutral-ish score based on capacity; only chosen when
    // no open bin offers a good fit (its raw residual = 100 keeps it high unless
    // bonuses elsewhere are absent).
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    score
}
